1	"use strict";
2	// Run manager for POST /v2/run: queueing, spawning `claude -p` in stream-json mode,
3	// normalizing events, per-run replay buffer, SSE fan-out, abort.
4	
5	const { spawn } = require("child_process");
6	const crypto = require("crypto");
7	const fs = require("fs");
8	const path = require("path");
9	const { Normalizer } = require("./normalizer");
10	
11	const SLUG_RE = /^[a-z0-9][a-z0-9-]{0,47}$/;
12	const WORKTREE_RE = /^[a-z0-9][a-z0-9_-]{0,63}$/;
13	const RUN_ID_RE = /^[A-Za-z0-9._:-]{1,128}$/;
14	const SESSION_ID_RE = /^[A-Za-z0-9._-]{1,128}$/;
15	const MODEL_RE = /^[A-Za-z0-9._:\[\]\/@-]{1,128}$/;
16	const MODES = new Set(["auto", "edit", "plan", "ask"]);
17	const THINKING = { off: "0", normal: "8000", max: "32000" };
18	const EFFORTS = new Set(["low", "medium", "high", "xhigh", "max"]);
19	const AGENT_NAME_RE = /^[a-z0-9][a-z0-9-]{0,47}$/;
20	const AGENT_MODEL_RE = /^[A-Za-z0-9._:\[\]\/@-]{1,128}$/;
21	const TOOL_NAME_RE = /^[A-Za-z0-9_*:().\- ]{1,200}$/;
22	const AGENTS_INLINE_MAX = 32 * 1024; // larger --agents JSON goes through a temp file
23	// --autocompact takes the auto-compact *window* (100k-1M); compaction fires at window - 13k
24	// (CLI: threshold = min(window - 13000, window * PCT_OVERRIDE/100)).
25	const AUTOCOMPACT_MIN_WINDOW = 100_000;
26	const AUTOCOMPACT_MAX_WINDOW = 1_000_000;
27	const AUTOCOMPACT_BUFFER = 13_000;
28	
29	// `Skill` is listed so (plugin) skills work in edit/ask mode; skills that write are still bound by the mode's tool gate.
30	const EDIT_TOOLS = ["Read", "Edit", "Write", "Glob", "Grep", "Bash", "WebFetch", "WebSearch", "TodoWrite", "TaskCreate", "TaskUpdate", "TaskGet", "TaskList", "Skill"];
31	const ASK_TOOLS = ["Read", "Glob", "Grep", "WebFetch", "WebSearch", "TodoWrite", "TaskCreate", "TaskUpdate", "TaskGet", "TaskList", "Skill"];
32	
33	// ---- lean mode (docs/research/token-efficiency.md §4.1) ----
34	// Tools a web IDE never needs. --disallowedTools (NOT --tools) keeps ToolSearch deferral on (an explicit list inlines
35	// every schema: +1.9k tokens/call measured). `Skill` stays available (plugin skills).
36	const LEAN_DISALLOWED_TOOLS = [
37	  "DesignSync", "EnterWorktree", "ExitWorktree", "ListAgents", "Monitor", "NotebookEdit", "PushNotification", "RemoteTrigger",
38	  "ReportFindings", "ScheduleWakeup", "SendMessage", "TaskStop", "CronCreate", "CronDelete", "CronList", "Workflow",
39	];
40	const LEAN_ENV = {
41	  CLAUDE_CODE_DISABLE_GIT_INSTRUCTIONS: "1", // commit/PR workflow text (the workspace checkpoints itself)
42	  CLAUDE_CODE_DISABLE_AUTO_MEMORY: "1",
43	  CLAUDE_CODE_DISABLE_BUNDLED_SKILLS: "1", // run/verify/deep-research/... listing; plugin skills are unaffected
44	  CLAUDE_CODE_DISABLE_CLAUDE_API_SKILL: "1",
45	  CLAUDE_CODE_DISABLE_CRON: "1",
46	  CLAUDE_CODE_DISABLE_WORKFLOWS: "1",
47	  CLAUDE_CODE_DISABLE_ADVISOR_TOOL: "1",
48	  BASH_MAX_OUTPUT_LENGTH: "12000", // default 30000 chars; overflow is saved to a file + preview
49	  CLAUDE_CODE_FILE_READ_MAX_OUTPUT_TOKENS: "15000",
50	  DISABLE_TELEMETRY: "1",
51	};
52	// Bundled skills that survive CLAUDE_CODE_DISABLE_BUNDLED_SKILLS (and would compete with workspace skills).
53	const LEAN_SKILL_OVERRIDES = { design: "off", doctor: "off", "plugin-authoring": "off" };
54	
55	const TERMINAL = new Set(["done", "error", "aborted"]);
56	const NEXUS_CWD_RE = /^\/[A-Za-z0-9._\/-]+$/;
57	
58	function isInside(child, parent) {
59	  const rel = path.relative(parent, child);
60	  return rel === "" || (!!rel && !rel.startsWith("..") && !path.isAbsolute(rel));
61	}
