63	/**
64	 * Build CLI args for a v2 run. `features` comes from parsing `claude --help`.
65	 */
66	function buildRunArgs(opts, features = {}, config = {}) {
67	  const args = ["-p", "--output-format", "stream-json", "--verbose", "--include-partial-messages"];
68	  if (features.permissionPrompts !== false) args.push("--permission-prompts", "none");
69	  if (opts.model) args.push("--model", opts.model);
70	  if (opts.sessionId) args.push("--resume", opts.sessionId);
71	  if (opts.maxTurns) args.push("--max-turns", String(opts.maxTurns));
72	  if (opts.maxBudgetUsd && features.maxBudgetUsd !== false) args.push("--max-budget-usd", String(opts.maxBudgetUsd));
73	  // Effort drives thinking depth and verbosity: keep simple requests cheap.
74	  const EFFORT = { off: "low", normal: "medium", max: "high" };
75	  const effort = opts.effort || (features.effort !== false ? EFFORT[opts.thinking || "normal"] : null);
76	  if (effort) args.push("--effort", effort);
77	  // Newer CLIs hide thinking text unless asked; summarized display streams readable thinking deltas.
78	  if (opts.thinking !== "off" && config.thinkingDisplay) args.push("--thinking-display", config.thinkingDisplay);
79	  if (opts.appendSystemPromptFile) args.push("--append-system-prompt-file", opts.appendSystemPromptFile);
80	  else if (opts.appendSystemPrompt) args.push("--append-system-prompt", opts.appendSystemPrompt);
81	  // Extra readable dirs: the attachments dir (sandbox home uploads or the shared uploads dir) + any granted dirs.
82	  const addDirs = opts.addDirsResolved || [...(config.uploadsDir ? [config.uploadsDir] : []), ...(opts.addDirs || [])];
83	  for (const d of addDirs) args.push("--add-dir", d);
84	  const ac = autocompactPlan(opts.autocompactTokens);
85	  if (ac && features.autocompact !== false) args.push("--autocompact", String(ac.window));
86	  const hasAgents = !!(opts.agents && Object.keys(opts.agents).length);
87	  if (hasAgents) args.push("--agents", opts.agentsFile || JSON.stringify(opts.agents));
88	  if (opts.agent) args.push("--agent", opts.agent);
89	  if (features.forwardSubagentText && config.forwardSubagentText !== false) args.push("--forward-subagent-text");
90	  if (isLean(opts, config)) {
91	    // Nexus runs have no subagents: drop the Agent tool (its description lists the built-in agents).
92	    const disallow = [...LEAN_DISALLOWED_TOOLS, ...(opts.nexus && !hasAgents ? ["Agent"] : [])];
93	    if (features.disallowedTools !== false) args.push("--disallowedTools", disallow.join(","));
94	    if (features.strictMcpConfig !== false) args.push("--strict-mcp-config");
95	    if (features.excludeDynamicSections) args.push("--exclude-dynamic-system-prompt-sections");
96	    args.push("--settings", JSON.stringify({ skillOverrides: LEAN_SKILL_OVERRIDES }));
97	  }
98	
99	  const modes = features.permissionModes || null; // null = unknown, assume all
100	  const has = (m) => !modes || modes.includes(m);
101	  switch (opts.mode || "auto") {
102	    case "auto": {
103	      const wanted = config.autoPermissionMode || "bypassPermissions";
104	      args.push("--permission-mode", has(wanted) ? wanted : "bypassPermissions");
105	      break;
106	    }
107	    case "edit":
108	      // Custom subagents are only useful in edit mode if the Agent tool is pre-approved.
109	      args.push("--permission-mode", "acceptEdits", "--allowedTools", ...EDIT_TOOLS, ...(hasAgents ? ["Agent"] : []));
110	      break;
111	    case "plan":
112	      args.push("--permission-mode", "plan");
113	      break;
114	    case "ask":
115	      if (has("dontAsk")) args.push("--permission-mode", "dontAsk");
116	      args.push("--tools", ASK_TOOLS.join(","), "--allowedTools", ...ASK_TOOLS);
117	      break;
118	  }
119	  // Sandboxed runs read the prompt from stdin so it never shows up in other uids' `ps` / /proc/<pid>/cmdline.
120	  if (!opts.promptViaStdin) args.push("--", opts.fullPrompt ?? opts.prompt);
121	  return args;
122	}
