124	/**
125	 * Map a desired auto-compact *threshold* (tokens of context at which compaction fires) to CLI settings.
126	 * Returns null for "CLI default" (0 / null). Thresholds below 87k use the minimum window (100k) plus
127	 * CLAUDE_AUTOCOMPACT_PCT_OVERRIDE (percent of the window).
128	 */
129	function autocompactPlan(tokens) {
130	  if (!tokens) return null;
131	  const want = tokens + AUTOCOMPACT_BUFFER;
132	  if (want >= AUTOCOMPACT_MIN_WINDOW) return { window: Math.min(AUTOCOMPACT_MAX_WINDOW, want), pct: null };
133	  return { window: AUTOCOMPACT_MIN_WINDOW, pct: Math.round((tokens / AUTOCOMPACT_MIN_WINDOW) * 1000) / 10 };
134	}
135	
136	function validateAgents(raw) {
137	  if (raw == null) return { agents: null };
138	  if (typeof raw !== "object" || Array.isArray(raw)) return { error: "Invalid agents (object expected)" };
139	  const names = Object.keys(raw);
140	  if (names.length > 100) return { error: "Too many agents" };
141	  const out = {};
142	  for (const name of names) {
143	    const a = raw[name];
144	    if (!AGENT_NAME_RE.test(name)) return { error: `Invalid agent name: ${name}` };
145	    if (!a || typeof a !== "object") return { error: `Invalid agent: ${name}` };
146	    if (typeof a.description !== "string" || !a.description.trim() || a.description.length > 4000) return { error: `Agent ${name}: invalid description` };
147	    if (typeof a.prompt !== "string" || !a.prompt.trim() || a.prompt.length > 100_000) return { error: `Agent ${name}: invalid prompt` };
148	    const def = { description: a.description, prompt: a.prompt };
149	    if (a.tools != null) {
150	      if (!Array.isArray(a.tools) || a.tools.length > 100 || !a.tools.every((t) => typeof t === "string" && TOOL_NAME_RE.test(t)))
151	        return { error: `Agent ${name}: invalid tools` };
152	      def.tools = a.tools;
153	    }
154	    if (a.model != null && a.model !== "") {
155	      if (typeof a.model !== "string" || !AGENT_MODEL_RE.test(a.model)) return { error: `Agent ${name}: invalid model` };
156	      def.model = a.model;
157	    }
158	    out[name] = def;
159	  }
160	  return { agents: out };
161	}
162	
163	function buildPrompt(prompt, attachments) {
164	  let out = prompt || "";
165	  if (attachments && attachments.length) {
166	    const lines = attachments.map((a) => `[Attached file: ${a} — use Read tool]`);
167	    out = out ? `${out}\n\n${lines.join("\n")}` : lines.join("\n");
168	  }
169	  return out;
170	}
171	
172	/** Lean mode: requested per run (`lean: true`); the LEAN_MODE=0 env of claudebox is a global kill switch. */
173	function isLean(opts, config = {}) {
174	  return !!opts.lean && config.leanMode !== false;
175	}
176	
177	/** MAX_THINKING_TOKENS only matters for budget-thinking models (Haiku 4.5); Opus/Sonnet 5.x think adaptively. */
178	function usesThinkingBudget(model) {
179	  return !!model && /haiku/i.test(model);
180	}
181	
182	function buildChildEnv(baseEnv, opts, config = {}) {
183	  const env = { ...baseEnv };
184	  delete env.CLAUDEBOX_API_KEY;
185	  delete env.PORT; // never leak the API server's PORT to Claude's shell
186	  if (opts.authToken) {
187	    if (opts.authToken.startsWith("sk-ant-api")) {
188	      env.ANTHROPIC_API_KEY = opts.authToken;
189	      delete env.CLAUDE_CODE_OAUTH_TOKEN;
190	    } else {
191	      env.CLAUDE_CODE_OAUTH_TOKEN = opts.authToken;
192	      delete env.ANTHROPIC_API_KEY;
193	    }
194	  }
195	  delete env.MAX_THINKING_TOKENS;
196	  if (opts.thinking && THINKING[opts.thinking] !== undefined && usesThinkingBudget(opts.model)) env.MAX_THINKING_TOKENS = THINKING[opts.thinking];
197	  if (isLean(opts, config)) Object.assign(env, LEAN_ENV);
198	  const ac = autocompactPlan(opts.autocompactTokens);
199	  if (ac && ac.pct != null) env.CLAUDE_AUTOCOMPACT_PCT_OVERRIDE = String(ac.pct);
200	  else delete env.CLAUDE_AUTOCOMPACT_PCT_OVERRIDE;
201	  if (opts.previewPort) {
202	    env.PORT = String(opts.previewPort);
203	    env.HOST = "0.0.0.0";
204	    env.BASE_PATH = `/preview/${opts.previewKey || opts.projectSlug}/`;
205	    env.NXEON_PREVIEW_PORT = String(opts.previewPort);
206	  }
207	  env.NXEON_PROJECT_SLUG = opts.projectSlug;
208	  env.NXEON_RUN_ID = opts.runId;
209	  return env;
210	}
