212	/**
213	 * Copy by creating a NEW file (not copyfile(), which carries the source's group/mode over): the copy then
214	 * inherits the setgid group + default ACLs of the sandbox home, i.e. it is readable by that sandbox only.
215	 */
216	function copyIntoSandbox(src, dest) {
217	  const tmp = `${dest}.part-${process.pid}`;
218	  const inFd = fs.openSync(src, "r");
219	  let outFd = null;
220	  try {
221	    outFd = fs.openSync(tmp, "w", 0o640);
222	    const buf = Buffer.allocUnsafe(1024 * 1024);
223	    for (;;) {
224	      const n = fs.readSync(inFd, buf, 0, buf.length, null);
225	      if (!n) break;
226	      fs.writeSync(outFd, buf, 0, n);
227	    }
228	    fs.closeSync(outFd);
229	    outFd = null;
230	    fs.renameSync(tmp, dest);
231	  } finally {
232	    fs.closeSync(inFd);
233	    if (outFd !== null) fs.closeSync(outFd);
234	    fs.rmSync(tmp, { force: true });
235	  }
236	}
