238	/** Project slugs of a Nexus run's addDirs (main checkouts and .branches/<slug>/<worktree>). */
239	function nexusSlugs(addDirs, projectsDir) {
240	  const out = new Set();
241	  for (const d of addDirs || []) {
242	    const seg = path.relative(projectsDir, d).split(path.sep);
243	    const slug = seg[0] === ".branches" ? seg[1] : seg[0];
244	    if (slug && SLUG_RE.test(slug)) out.add(slug);
245	  }
246	  return [...out];
247	}
