249	class RunManager {
250	  constructor(config) {
251	    this.config = {
252	      claudeBin: "claude",
253	      projectsDir: "/workspace/projects",
254	      uploadsDir: "/workspace/uploads",
255	      maxConcurrent: 4,
256	      retentionMs: 30 * 60 * 1000,
257	      maxEventsPerRun: 50000,
258	      killGraceMs: 4000,
259	      heartbeatMs: 15000,
260	      previewPortMin: 4100,
261	      previewPortMax: 4199,
262	      autoPermissionMode: "bypassPermissions",
263	      thinkingDisplay: "summarized",
264	      forwardSubagentText: true,
265	      log: () => {},
266	      features: () => ({}),
267	      env: process.env,
268	      ...config,
269	    };
270	    this.runs = new Map();
271	    this.queue = [];
272	    this.running = 0;
273	    this._gc = setInterval(() => this.gc(), 60 * 1000);
274	    this._gc.unref();
275	  }
276	
277	  close() {
278	    clearInterval(this._gc);
279	    for (const run of this.runs.values()) {
280	      for (const sub of run.subscribers) clearInterval(sub.hb);
281	      if (run.status === "running") this._kill(run, "SIGKILL", { sync: true });
282	    }
283	  }
284	
285	  /** Validate a /v2/run body. Returns {opts} or {error}. */
286	  validate(body) {
287	    const c = this.config;
288	    if (!body || typeof body !== "object") return { error: "Body must be a JSON object" };
289	    const runId = body.runId == null ? crypto.randomUUID() : body.runId;
290	    if (typeof runId !== "string" || !RUN_ID_RE.test(runId)) return { error: "Invalid runId" };
291	    if (typeof body.prompt !== "string") return { error: "Missing 'prompt' (string)" };
292	    if (body.prompt.length > 1_000_000) return { error: "Prompt too large" };
293	    if (typeof body.projectSlug !== "string" || !SLUG_RE.test(body.projectSlug))
294	      return { error: "Invalid projectSlug (must match ^[a-z0-9][a-z0-9-]{0,47}$)" };
295	    const sessionId = body.sessionId == null || body.sessionId === "" ? null : body.sessionId;
296	    if (sessionId !== null && (typeof sessionId !== "string" || !SESSION_ID_RE.test(sessionId))) return { error: "Invalid sessionId" };
297	    const model = body.model == null || body.model === "" ? null : body.model;
298	    if (model !== null && (typeof model !== "string" || !MODEL_RE.test(model))) return { error: "Invalid model" };
299	    const mode = body.mode == null ? "auto" : body.mode;
300	    if (!MODES.has(mode)) return { error: "Invalid mode (auto|edit|plan|ask)" };
301	    const thinking = body.thinking == null ? null : body.thinking;
302	    if (thinking !== null && THINKING[thinking] === undefined) return { error: "Invalid thinking (off|normal|max)" };
303	    const effort = body.effort == null ? null : body.effort;
304	    if (effort !== null && !EFFORTS.has(effort)) return { error: "Invalid effort" };
305	    let maxTurns = null;
306	    if (body.maxTurns != null) {
307	      maxTurns = Number(body.maxTurns);
308	      if (!Number.isInteger(maxTurns) || maxTurns < 1 || maxTurns > 1000) return { error: "Invalid maxTurns" };
309	    }
310	    let maxBudgetUsd = null;
311	    if (body.maxBudgetUsd != null && body.maxBudgetUsd !== 0) {
312	      maxBudgetUsd = Number(body.maxBudgetUsd);
313	      if (!Number.isFinite(maxBudgetUsd) || maxBudgetUsd < 0.01 || maxBudgetUsd > 100) return { error: "Invalid maxBudgetUsd (0.01-100)" };
314	    }
315	    if (body.lean != null && typeof body.lean !== "boolean") return { error: "Invalid lean (boolean)" };
316	    const lean = body.lean === true;
317	    let previewPort = null;
318	    if (body.previewPort != null) {
319	      previewPort = Number(body.previewPort);
320	      if (!Number.isInteger(previewPort) || previewPort < c.previewPortMin || previewPort > c.previewPortMax)
321	        return { error: `Invalid previewPort (${c.previewPortMin}-${c.previewPortMax})` };
322	    }
323	    const appendSystemPrompt = body.appendSystemPrompt == null ? null : body.appendSystemPrompt;
324	    if (appendSystemPrompt !== null && (typeof appendSystemPrompt !== "string" || appendSystemPrompt.length > 200_000))
325	      return { error: "Invalid appendSystemPrompt" };
326	    const authToken = body.authToken == null || body.authToken === "" ? null : body.authToken;
327	    if (authToken !== null && (typeof authToken !== "string" || authToken.length > 8192 || /[\r\n\0]/.test(authToken)))
328	      return { error: "Invalid authToken" };
329	
330	    let autocompactTokens = null;
331	    if (body.autocompactTokens != null && body.autocompactTokens !== 0) {
332	      autocompactTokens = Number(body.autocompactTokens);
333	      if (!Number.isInteger(autocompactTokens) || autocompactTokens < 10_000 || autocompactTokens > AUTOCOMPACT_MAX_WINDOW - AUTOCOMPACT_BUFFER)
334	        return { error: "Invalid autocompactTokens (0 or 10000-987000)" };
335	    }
336	    const va = validateAgents(body.agents);
337	    if (va.error) return { error: va.error };
338	    const agents = va.agents && Object.keys(va.agents).length ? va.agents : null;
339	    const agent = body.agent == null || body.agent === "" ? null : body.agent;
340	    if (agent !== null && (typeof agent !== "string" || !AGENT_NAME_RE.test(agent))) return { error: "Invalid agent" };
341	    if (agent !== null && agents && !agents[agent]) return { error: `Lead agent "${agent}" is not in agents` };
342	
343	    // Branch runs execute in the branch's git worktree (.branches/<slug>/<worktree>); preview key <slug>--<worktree>.
344	    const worktree = body.worktree == null || body.worktree === "" ? null : body.worktree;
345	    if (worktree !== null && (typeof worktree !== "string" || !WORKTREE_RE.test(worktree))) return { error: "Invalid worktree" };
346	    let cwd = worktree ? path.join(c.projectsDir, ".branches", body.projectSlug, worktree) : path.join(c.projectsDir, body.projectSlug);
347	    if (worktree && !fs.existsSync(cwd)) return { error: `Branch worktree '${worktree}' not found` };
348	
349	    // ---- sandbox identity (computed by the app; only ranges/paths are validated here) ----
350	    const sb = c.sandbox || null;
351	    let sandbox = null;
352	    let nexus = false;
353	    const addDirs = [];
354	    if (sb) {
355	      const v = sb.validateSpec(body.sandbox);
356	      if (v.error) return { error: v.error };
357	      sandbox = v.spec;
358	      if (body.cwd != null && body.cwd !== "") {
359	        // Multi-project ("Nexus") runs: cwd is a per-user scratch dir; projects are reached via groups + addDirs.
360	        const nx = sb.config.nexusDir;
361	        if (!sandbox) return { error: "cwd requires a sandbox spec" };
362	        if (typeof body.cwd !== "string" || !NEXUS_CWD_RE.test(body.cwd) || body.cwd.split("/").some((x) => x === ".." || x === ".") || !isInside(body.cwd, nx) || body.cwd === nx)
363	          return { error: `cwd must be inside ${nx}` };
364	        cwd = path.resolve(body.cwd);
365	        nexus = true;
366	      } else if (!sandbox) {
367	        sandbox = sb.specFromDir(body.projectSlug);
368	      } else {
369	        const fromDir = sb.specFromDir(body.projectSlug);
370	        if (fromDir && !sandbox.groups.includes(fromDir.gid)) return { error: `Sandbox has no access to project '${body.projectSlug}'` };
371	      }
372	      if (body.addDirs != null) {
373	        if (!Array.isArray(body.addDirs) || body.addDirs.length > 64) return { error: "Invalid addDirs" };
374	        for (const d of body.addDirs) {
375	          if (typeof d !== "string" || !NEXUS_CWD_RE.test(d) || d.split("/").some((x) => x === ".." || x === ".")) return { error: `Invalid addDir: ${d}` };
376	          const r = path.resolve(d);
377	          if (!isInside(r, c.projectsDir) || r === c.projectsDir || path.relative(c.projectsDir, r).startsWith(".trash")) return { error: `addDirs must be project dirs: ${d}` };
378	          addDirs.push(r);
379	        }
380	      }
381	      if (sb.strict && !sandbox) return { error: "Project sandbox is not set up (pass `sandbox` or run /v2/sandbox/setup)", status: 409 };
382	    } else if (body.cwd != null && body.cwd !== "") {
383	      return { error: "cwd is only supported with sandboxing" };
384	    }
385	    const previewKey = worktree ? `${body.projectSlug}--${worktree}` : body.projectSlug;
386	    const attachments = [];
387	    if (body.attachments != null) {
388	      if (!Array.isArray(body.attachments) || body.attachments.length > 100) return { error: "Invalid attachments" };
389	      for (const a of body.attachments) {
390	        if (typeof a !== "string" || /[\r\n\0]/.test(a)) return { error: "Invalid attachment path" };
391	        const resolved = path.resolve(a);
392	        if (!isInside(resolved, c.uploadsDir) && !isInside(resolved, cwd))
393	          return { error: `Attachment must be under ${c.uploadsDir} or the project dir: ${a}` };
394	        attachments.push(resolved);
395	      }
396	    }
397	    if (!body.prompt.trim() && !attachments.length) return { error: "Empty prompt" };
