  '- Few tool calls: batch independent calls in one turn; read only the files you need, each once (offset/limit for big files); never re-read what you just wrote; no exploratory commands; no subagents for small tasks.',
  '- Edit existing files with Edit (targeted changes); use Write only for new files.',
  '- Pipe long command output through `| tail -n 40` or grep; never dump logs or lockfiles.',
  '- No builds, tests or type-checks for trivial changes unless asked.',
  '- Final reply: 1-4 lines on what changed. Never paste code or file contents into the reply.',
  '- Create/update README.md only when you create the project or change how it is run.',
  'You have internet access (npm, pip, git, web).',
];
const FULL_SUGGESTIONS = [
  'At the very end of EVERY final reply, append 2-3 short actionable follow-up suggestions for the user in exactly this format (valid JSON array on one line, no code fences):',
  '<nx-suggestions>[{"label":"Short button text","prompt":"The full prompt to send if clicked","kind":"next"}]</nx-suggestions>',
  'kind must be one of: next, fix, test, deploy, explain. The block is hidden from the user and rendered as clickable chips. Never mention it.',
];


export class RunManager {
  private active = new Map<string, ActiveRun>();
  private flushTimer: NodeJS.Timeout | null = null;
  private lastPulse = new Map<string, number>();
  private insertEvent;
  private updateRunTotals;

  constructor(
    private db: DB,
    private hub: Hub,
    private cb: Claudebox,
    private cfg: Config,
    private settings: Settings,
    private log: FastifyBaseLogger,
  ) {
    this.insertEvent = db.prepare(`INSERT OR IGNORE INTO run_events(run_id, seq, type, data, ts) VALUES (?,?,?,?,?)`);
    this.updateRunTotals = db.prepare(
      `UPDATE runs SET input_tokens=?, output_tokens=?, cache_read=?, cache_write=?, cost_usd=?, upstream_seq=? WHERE id=?`,
    );
  }

  isActive(runId: string) {
    return this.active.has(runId);
  }
  activeIds() {
    return [...this.active.keys()];
  }
  activeForConversation(conversationId: string): string | null {
    for (const r of this.active.values()) if (r.conversationId === conversationId) return r.id;
    return null;
  }

  /** Events from DB + in-memory pending, seq >= fromSeq. Synchronous so the caller can subscribe without gaps. */
  replay(runId: string, fromSeq: number): StoredEvent[] {
    const rows = this.db
      .prepare(`SELECT seq, type, data, ts FROM run_events WHERE run_id = ? AND seq >= ? ORDER BY seq`)
      .all(runId, fromSeq) as { seq: number; type: string; data: string; ts: number }[];
    const out: StoredEvent[] = rows.map((r) => ({ seq: r.seq, type: r.type, data: parseJson(r.data, null), ts: r.ts }));
    const a = this.active.get(runId);
    if (a) {
      const maxDb = out.length ? out[out.length - 1]!.seq : fromSeq - 1;
      for (const e of a.pending) if (e.seq > maxDb && e.seq >= fromSeq) out.push(e);
    }
    return out;
  }

  // ---------------- lifecycle ----------------

  start(p: {
    runId: string;
    conversationId: string;
    projectId: string | null;
    userId: string;
    assistantMessageId: string;
    body: V2RunBody;
    kind?: 'compact' | null;
    branch?: string | null;
    nexus?: NexusRunScope | null;
  }) {
    const run = this.newState(p.runId, p.conversationId, p.projectId, p.userId, p.assistantMessageId, p.body);
    run.kind = p.kind ?? null;
    run.branch = p.branch ?? null;
    run.mode = p.body.mode;
    if (p.nexus) run.nexus = { ...p.nexus, touched: new Set() };
    this.active.set(run.id, run);
    void this.drive(run, false);
  }

  private newState(
    id: string,
    conversationId: string,
    projectId: string | null,
    userId: string | null,
    assistantMessageId: string,
    body: V2RunBody | null,
  ): ActiveRun {
    return {
      id, conversationId, projectId, userId, assistantMessageId, body,
      seq: 0, upstreamSeq: 0, pending: [], fullText: '', emittedLen: 0, needSep: false,
      usage: { inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0 },
      costUsd: 0, sessionCostUsd: null, durationMs: null, sawResult: false, resultIsError: false, resultText: '', sawError: false,
      lastError: null, exitCode: undefined, abortRequested: false, ended: false, controller: new AbortController(),
      startedAt: now(),
      kind: null,
      branch: null,
      nexus: null,
      mode: null,
      limit: null,
    };
  }

  private setStatus(run: ActiveRun, status: RunStatus) {
    this.db.prepare(`UPDATE runs SET status = ? WHERE id = ?`).run(status, run.id);
    this.broadcastStatus(run, status);
  }

  /** Project runs: everyone who may view the project; Nexus runs: only the owner. */
  private broadcastStatus(run: ActiveRun, status: RunStatus) {
    if (run.projectId) {

    if (run.projectId) {
      this.hub.broadcastViewers(run.projectId, { t: 'run_status', runId: run.id, conversationId: run.conversationId, projectId: run.projectId, status, branch: run.branch });
    } else if (run.userId) {
      this.hub.broadcastUser(run.userId, { t: 'run_status', runId: run.id, conversationId: run.conversationId, projectId: null, status, nexus: true });
    }
  }

  /** Connects (or re-attaches) to claudebox and consumes the stream until `done` or give-up. */
  private async drive(run: ActiveRun, recovering: boolean) {
    if (!recovering) {
      this.setStatus(run, 'running');
      if (run.projectId) this.db.prepare(`UPDATE projects SET last_active_at = ? WHERE id = ?`).run(now(), run.projectId);
    }
    let attempt = 0;
    let first = !recovering;
    while (!run.ended) {
      if (run.abortRequested && first) {
        this.synthEnd(run, null);
        return;
      }
      let res: Dispatcher.ResponseData;
      try {
        res = first ? await this.cb.startRun(run.body!, run.controller.signal) : await this.cb.attach(run.id, run.upstreamSeq + 1, run.controller.signal);
      } catch (err) {
        if (run.ended) return;
        if (run.abortRequested) {
          this.synthEnd(run, null);
          return;
        }
        if (first) {
          this.emit(run, 'error', { message: `Cannot reach claudebox: ${(err as Error).message}` });
          this.synthEnd(run, null);
          return;
        }
        if (++attempt > (recovering ? 2 : MAX_REATTACH)) {
          this.emit(run, 'error', { message: 'Lost connection to the Claude runner.' });
          this.synthEnd(run, null);
          return;
        }
        await sleep(Math.min(8000, 500 * 2 ** attempt));
        continue;
      }
      const wasFirst = first;
      first = false;
      if (res.statusCode !== 200) {
        const text = (await res.body.text().catch(() => '')).slice(0, 500);
        if (run.ended) return;
        if (!wasFirst && res.statusCode === 404) {
          this.emit(run, 'error', { message: recovering ? 'The run was lost while the server restarted.' : 'Lost connection to the Claude runner (run no longer available).' });
        } else {
          let msg = text;
          try {
            const j = JSON.parse(text) as { error?: unknown; message?: unknown };
            const e = j.error ?? j.message;
            msg = typeof e === 'string' ? e : (e as { message?: string })?.message ?? text;
          } catch {
            /* plain text */
          }
          this.emit(run, 'error', { message: `Claude runner error (${res.statusCode}): ${msg || 'unknown error'}` });
        }
        this.synthEnd(run, null);
        return;
      }
      attempt = 0;
      try {
        await this.consume(run, res.body);
      } catch (err) {
        if (run.ended) return;
        this.log.warn({ runId: run.id, err: (err as Error).message }, 'run stream interrupted');
      }
      if (run.ended) return;
      if (run.abortRequested && run.controller.signal.aborted) {
        this.synthEnd(run, null);
        return;
      }
      // Stream ended without `done` → reattach with backoff.
      if (++attempt > MAX_REATTACH) {
        this.emit(run, 'error', { message: 'Lost connection to the Claude runner.' });
        this.synthEnd(run, null);
        return;
      }
      await sleep(Math.min(8000, 300 * 2 ** attempt));
    }
  }

  private async consume(run: ActiveRun, body: Dispatcher.ResponseData['body']) {
    const parser = new SseParser();
    body.setEncoding('utf8');
    for await (const chunk of body) {
      for (const m of parser.push(chunk as string)) {
        this.handleUpstream(run, m);
        if (run.ended) {
          body.destroy();
          return;
        }
      }
    }
  }

  handleUpstream(run: ActiveRun, m: SseMessage) {
    if (m.id !== undefined && /^\d+$/.test(m.id)) {
      const id = Number(m.id);
      if (id <= run.upstreamSeq) return; // duplicate after reattach
      run.upstreamSeq = id;
    }
    const type = m.event as RunEventType;
    if (!KNOWN_TYPES.has(type)) return;
    let data: Record<string, unknown>;
    try {
      data = (m.data ? JSON.parse(m.data) : {}) as Record<string, unknown>;
    } catch {
      return;
    }
    switch (type) {
      case 'init': {
        const sid = typeof data.sessionId === 'string' ? data.sessionId : null;
        if (sid) this.db.prepare(`UPDATE conversations SET claude_session_id = ? WHERE id = ?`).run(sid, run.conversationId);
        this.emit(run, 'init', data);
        break;
      }
      case 'text': {
        if (typeof data.parentId === 'string') {
          // forwarded subagent text: shown under the delegating tool, never part of the answer
          this.emit(run, 'text', data);
          break;
        }
        let delta = typeof data.delta === 'string' ? data.delta : '';
        if (!delta) return;
        if (run.needSep && run.fullText.length && !/\n\s*$/.test(run.fullText)) delta = '\n\n' + delta;
        run.needSep = false;
        run.fullText += delta;
        this.emitVisible(run, true);
        break;
      }
      case 'block_end': {
        if (data.kind === 'text') {
          this.emitVisible(run, false);
          run.needSep = true;
        }
        this.emit(run, 'block_end', data);
        break;
      }
      case 'usage': {
        const u = data as Partial<Usage>;
        run.usage.inputTokens += num(u.inputTokens);
        run.usage.outputTokens += num(u.outputTokens);
        run.usage.cacheReadTokens += num(u.cacheReadTokens);
        run.usage.cacheWriteTokens += num(u.cacheWriteTokens);
        if (!data.parentId && num(data.contextTokens) > 0) this.setContextTokens(run, num(data.contextTokens));
        this.emit(run, 'usage', data);
        break;
      }
      case 'compact': {
        this.setContextTokens(run, num(data.postTokens));
        this.emit(run, 'compact', data);
        break;
      }
      case 'result': {
        run.sawResult = true;
        run.resultIsError = !!data.isError;
        run.resultText = typeof data.result === 'string' ? data.result : '';
        const u = data.usage as Partial<Usage> | undefined;
        if (u && typeof u === 'object') {
          // result.usage covers the main thread only; the summed usage events also include subagents
          // (parentId) and estimated compaction usage — keep whichever is larger per field.
          run.usage = {
            inputTokens: Math.max(num(u.inputTokens), run.usage.inputTokens),
            outputTokens: Math.max(num(u.outputTokens), run.usage.outputTokens),
            cacheReadTokens: Math.max(num(u.cacheReadTokens), run.usage.cacheReadTokens),
            cacheWriteTokens: Math.max(num(u.cacheWriteTokens), run.usage.cacheWriteTokens),
          };
        }
        if (typeof data.costUsd === 'number') {
          // total_cost_usd is cumulative for the resumed session: charge this run only the increase. A "Continue fresh"
          // run starts a new session, so only runs since the latest fresh start count as the baseline.
          const prev = (this.db
            .prepare(
              `SELECT COALESCE(MAX(session_cost_usd), 0) AS v FROM runs WHERE conversation_id = ? AND id != ? AND started_at <= ?
                 AND started_at >= (SELECT COALESCE(MAX(started_at), 0) FROM runs WHERE conversation_id = ? AND resume_choice = 'fresh' AND started_at <= ?)`,
            )
            .get(run.conversationId, run.id, run.startedAt, run.conversationId, run.startedAt) as { v: number }).v;
          run.sessionCostUsd = data.costUsd;
          run.costUsd = data.costUsd >= prev ? data.costUsd - prev : data.costUsd;
        }
        if (typeof data.durationMs === 'number') run.durationMs = data.durationMs;
        if (typeof data.sessionId === 'string' && data.sessionId)
          this.db.prepare(`UPDATE conversations SET claude_session_id = ? WHERE id = ?`).run(data.sessionId, run.conversationId);
        if (run.resultIsError && run.resultText && !run.lastError) run.lastError = run.resultText;
        // The suggestions block lives in the final text; don't leak it through the result payload.
        // costUsd = this run's share (the CLI reports the cumulative session cost; kept as sessionCostUsd)
        this.emit(run, 'result', {
          ...data, result: finalContent(run.resultText),
          ...(typeof data.costUsd === 'number' ? { costUsd: run.costUsd, sessionCostUsd: data.costUsd } : {}),
        });
        break;
      }
      case 'error': {
        run.sawError = true;
        if (data.code === 'authentication_failed') {
          data = { ...data, detail: data.message, message: AUTH_HINT };
        }
        const stop = limitStop(data.code, { maxTurns: run.body?.maxTurns, maxBudgetUsd: run.body?.maxBudgetUsd });
        if (stop) {
          run.limit = stop.kind;
          data = { ...data, detail: data.message, message: stop.message, limit: stop.kind };
        }
        run.lastError = typeof data.message === 'string' ? data.message : 'error';
        this.emit(run, 'error', data);
        break;
      }
      case 'tool_use': {
        this.emit(run, 'tool_use', data);
        if (run.nexus && typeof data.name === 'string' && isWriteTool(data.name, data.input)) {
          for (const t of touchedPaths(this.cfg.claudeboxProjectsDir, data.name, data.input)) {
            const sp = run.nexus.projects.find((x) => x.slug === t.slug && (t.worktree ? x.worktree === t.worktree : true));
            if (sp) this.nexusTouch(run, sp.id, t.worktree ? sp.branch : null);
          }
        }
        break;
      }
      case 'done': {
        this.emitVisible(run, false);
        run.exitCode = typeof data.exitCode === 'number' ? data.exitCode : null;
        if (data.aborted === true) run.abortRequested = true;
        this.emit(run, 'done', { ...data, exitCode: run.exitCode });
        this.finalize(run);
        break;
      }
      default:
        this.emit(run, type, data);
    }
  }

  private setContextTokens(run: ActiveRun, n: number) {
    if (!(n >= 0)) return;
    this.db.prepare(`UPDATE conversations SET context_tokens = ? WHERE id = ?`).run(Math.round(n), run.conversationId);
  }

  private emitVisible(run: ActiveRun, holdPartial: boolean) {
    const vis = visibleText(run.fullText, holdPartial);
    if (vis.length > run.emittedLen) {
      this.emit(run, 'text', { delta: vis.slice(run.emittedLen) });
      run.emittedLen = vis.length;
    }
  }

  private emit(run: ActiveRun, type: string, data: unknown) {
    const seq = ++run.seq;
    const ts = now();
    const ev: StoredEvent = { seq, type, data, ts };
    run.pending.push(ev);
    // `ts` is an additive field (not in protocol.ts) used by the UI for "Thought for Xs".
    this.hub.broadcastRun(run.id, { t: 'run_event', runId: run.id, seq, type, data, ts } as never);
    if (run.projectId) this.pulse(run.projectId, PULSE[type as RunEventType] ?? 0.2, run.branch);
    if (!this.flushTimer) this.flushTimer = setTimeout(() => this.flushAll(), FLUSH_MS);
  }

  private pulse(projectId: string, intensity: number, branch: string | null = null, source?: 'nexus') {
    const t = Date.now();
    const k = `${projectId}|${branch ?? ''}|${source ?? ''}`;
    if (intensity < 0.8 && t - (this.lastPulse.get(k) ?? 0) < 250) return;
    if (source && t - (this.lastPulse.get(k) ?? 0) < 400) return;
    this.lastPulse.set(k, t);
    this.hub.broadcastViewers(projectId, { t: 'graph_pulse', projectId, intensity, branch, ...(source ? { source } : {}) });
  }

  /** A Nexus run wrote to a project: light its strand from the core; record it (live `nexus` run event). */
  private nexusTouch(run: ActiveRun, projectId: string, branch: string | null) {
    if (!run.nexus || run.ended) return;
    this.pulse(projectId, 0.9, branch, 'nexus');
    if (run.nexus.touched.has(projectId)) return;
    run.nexus.touched.add(projectId);
    this.emit(run, 'nexus', { touched: [...run.nexus.touched] });
  }

  /** File watcher hook: changes in a project checkout during an active Nexus run that has it in scope. */
  noteFileChange(projectId: string, branch: string | null) {
    for (const run of this.active.values()) {
      if (!run.nexus || run.ended) continue;
      if (run.nexus.projects.some((x) => x.id === projectId && x.branch === branch)) this.nexusTouch(run, projectId, branch);
    }
  }

  flushAll() {
    if (this.flushTimer) {
      clearTimeout(this.flushTimer);
      this.flushTimer = null;
    }
    const tx = this.db.transaction(() => {
      for (const run of this.active.values()) this.flushRun(run);
    });
    try {
      tx();
    } catch (err) {
      this.log.error({ err }, 'flush run events failed');
    }
  }

  private flushRun(run: ActiveRun) {
    if (!run.pending.length) return;
    for (const e of run.pending) this.insertEvent.run(run.id, e.seq, e.type, JSON.stringify(e.data ?? null), e.ts);
    run.pending = [];
    this.updateRunTotals.run(
      run.usage.inputTokens, run.usage.outputTokens, run.usage.cacheReadTokens, run.usage.cacheWriteTokens,
      run.costUsd, run.upstreamSeq, run.id,
    );
  }

  /** Emit a synthetic `done` and finalize (used on errors / aborts without upstream completion). */
  private synthEnd(run: ActiveRun, exitCode: number | null) {
    if (run.ended) return;
    this.emitVisible(run, false);
    run.exitCode = exitCode;
    this.emit(run, 'done', { exitCode });
    this.finalize(run);
  }

  private finalize(run: ActiveRun) {
    if (run.ended) return;
    run.ended = true;
    run.controller.abort();
    let status: RunStatus;
    if (run.abortRequested) status = 'aborted';
    else if (run.sawResult) status = run.resultIsError ? 'error' : 'done';
    else if (run.sawError) status = 'error';
    else status = run.exitCode === 0 ? 'done' : 'error';

    let suggestions: Suggestion[] = parseSuggestions(run.fullText);
    if (!suggestions.length && run.resultText) suggestions = parseSuggestions(run.resultText);
    // stopped by a guardrail: one click resumes the session where it stopped
    if (run.limit && !run.abortRequested) suggestions = [{ label: 'Continue', prompt: 'continue', kind: 'next' }, ...suggestions.filter((x) => x.prompt !== 'continue').slice(0, 2)];
    // No reported cost (abort, crash, lost result): estimate it from the summed usage so spend is never under-reported.
    const anyUsage = run.usage.inputTokens + run.usage.outputTokens + run.usage.cacheReadTokens + run.usage.cacheWriteTokens > 0;
    let costEstimated = false;
    if (anyUsage && !(run.costUsd > 0) && (!run.sawResult || run.sessionCostUsd == null)) {
      const model = run.body?.model ?? (this.db.prepare(`SELECT model FROM runs WHERE id = ?`).get(run.id) as { model: string } | undefined)?.model;
      run.costUsd = usageCost(run.usage, priceFor(this.settings.get(), model));
      costEstimated = true;
    }
    let handoffs: Handoff[] = [];
    if (run.nexus) {
      const slugs = new Set(run.nexus.projects.map((x) => x.slug));
      handoffs = parseHandoffs(run.fullText, slugs);
      if (!handoffs.length && run.resultText) handoffs = parseHandoffs(run.resultText, slugs);
    }
    let content = finalContent(run.fullText);
    if (!content && run.resultText) content = finalContent(run.resultText);
    const t = now();
    const durationMs = run.durationMs ?? t - run.startedAt;

    this.db.transaction(() => {
      this.flushRun(run);
      this.updateRunTotals.run(
        run.usage.inputTokens, run.usage.outputTokens, run.usage.cacheReadTokens, run.usage.cacheWriteTokens,
        run.costUsd, run.upstreamSeq, run.id,
      );
      this.db
        .prepare(`UPDATE runs SET status = ?, ended_at = ?, duration_ms = ?, error = ?, session_cost_usd = ?, cost_estimated = ? WHERE id = ?`)
        .run(status, t, durationMs, status === 'error' ? (run.lastError ?? 'Run failed').slice(0, 2000) : null, run.sessionCostUsd, costEstimated ? 1 : 0, run.id);
      // prompt-cache warmth: only runs that actually talked to the API refresh it
      if (anyUsage || run.sawResult) this.db.prepare(`UPDATE conversations SET last_activity_at = ? WHERE id = ?`).run(t, run.conversationId);
      this.db
        .prepare(`UPDATE messages SET content = ?, suggestions = ?, handoffs = ? WHERE id = ?`)
        .run(content, suggestions.length ? JSON.stringify(suggestions) : null, handoffs.length ? JSON.stringify(handoffs) : null, run.assistantMessageId);
      this.db.prepare(`UPDATE conversations SET updated_at = ? WHERE id = ?`).run(t, run.conversationId);
      if (run.projectId) this.db.prepare(`UPDATE projects SET last_active_at = ? WHERE id = ?`).run(t, run.projectId);
    })();
    this.active.delete(run.id);
    if (suggestions.length) this.hub.broadcastRun(run.id, { t: 'suggestions', runId: run.id, items: suggestions });
    this.broadcastStatus(run, status);
    if (run.projectId) {
      this.pulse(run.projectId, 1, run.branch);
      if (status === 'done' && run.kind !== 'compact') {
        const pid = run.projectId;
        void this.checkpoint(run).finally(() => this.autoStartPreview(pid, run.branch));
      }
    } else if (run.nexus) {
      const writes = status === 'done' && run.kind !== 'compact' && run.mode !== 'ask' && run.mode !== 'plan';
      void (writes ? this.nexusCheckpoint(run) : Promise.resolve([] as NexusCommit[])).then((commits) => {
        this.markCheckpointed(run);
        if (run.userId)
          this.hub.broadcastUser(run.userId, {
            t: 'nexus_run', runId: run.id, conversationId: run.conversationId, touched: [...run.nexus!.touched], commits,
            handoffs: handoffs as NexusHandoff[], checkpointed: true,
          });
      });
    }
  }

  private markCheckpointed(run: ActiveRun) {
    if (!run.nexus) return;
    const { touched: _t, ...scope } = run.nexus;
    this.db.prepare(`UPDATE runs SET nexus_scope = ? WHERE id = ?`).run(JSON.stringify({ ...scope, checkpointed: true }), run.id);
  }

  /**
   * Nexus runs: commit a checkpoint in every in-scope checkout that changed ("git add -A" + commit only when dirty),
   * record them in nexus_run_commits (→ "Undo this run" across projects) and light up those projects.
   * Checkouts with an active project run are skipped (that run's own checkpoint will include the changes).
   */
  async nexusCheckpoint(run: ActiveRun): Promise<NexusCommit[]> {
    const scope = run.nexus;
    if (!scope) return [];
    const prompt = run.body?.prompt
      ?? (this.db.prepare(`SELECT content FROM messages WHERE run_id = ? AND role = 'user'`).get(run.id) as { content: string } | undefined)?.content
      ?? '';
    const line = prompt.replace(/\s+/g, ' ').trim().slice(0, 60) || 'run';
    const out: NexusCommit[] = [];
    const dirty = new Set(scope.dirty ?? []);
    const mixed: string[] = [];
    scope.mixed = mixed;
    // already-dirty, unfocused checkouts are only committed when the run demonstrably wrote there
    const queue = scope.projects.filter((x) => x.branch || !dirty.has(x.id) || scope.touched.has(x.id));
    const worker = async () => {
      for (let x = queue.shift(); x; x = queue.shift()) {
        try {
          const p = this.db.prepare(`SELECT * FROM projects WHERE id = ?`).get(x.id) as ProjectRow | undefined;
          if (!p || p.archived) continue;
          const b = x.branch ? getBranch(this.db, p.id, x.branch) : null;
          if (x.branch && !b) continue;
          const busy = this.db.prepare(`SELECT 1 FROM runs WHERE project_id = ? AND branch IS ? AND status IN ('queued','running')`).get(p.id, x.branch);
          if (busy) continue;
          const main = await ensureGit({ db: this.db, cb: this.cb, log: this.log }, p);
          const r = await this.cb.git<{ sha: string | null; files?: number; skipped?: string }>('checkpoint', {
            projectSlug: p.slug, ...(b ? { worktree: b.dir } : {}), message: `nxeon (nexus): ${line}`, expectBranch: b ? b.name : main,
          }, 30_000);
          if (r.skipped) this.log.warn({ runId: run.id, project: p.slug, skipped: r.skipped }, 'nexus checkpoint skipped');
          if (!r.sha) continue;
          if (!x.branch && dirty.has(p.id)) mixed.push(p.id);
          this.db
            .prepare(`INSERT OR REPLACE INTO nexus_run_commits(run_id, project_id, branch, sha, files, created_at) VALUES (?,?,?,?,?,?)`)
            .run(run.id, p.id, x.branch, r.sha, r.files ?? 0, now());
          this.db.prepare(`UPDATE projects SET last_active_at = ? WHERE id = ?`).run(now(), p.id);
          out.push({
            projectId: p.id, slug: p.slug, name: p.name, color: p.color, branch: x.branch, sha: r.sha, files: r.files ?? 0, undone: false,
            ...(!x.branch && dirty.has(p.id) ? { mixed: true } : {}),
          });
          scope.touched.add(p.id);
          this.hub.broadcastProject(p.id, { t: 'project_changed', projectId: p.id, what: 'history', branch: x.branch });
          this.pulse(p.id, 1, x.branch, 'nexus');
          void this.autoStartPreview(p.id, x.branch);
        } catch (err) {
          this.log.warn({ err: (err as Error).message, runId: run.id, project: x.slug }, 'nexus checkpoint failed');
        }
      }
    };
    await Promise.all(Array.from({ length: Math.min(4, queue.length) }, worker));
    return out;
  }

  /** Auto-checkpoint: commit everything in the run's checkout as "nxeon: <prompt>" and record the sha on the run. */
  private async checkpoint(run: ActiveRun) {
    try {
      const p = this.db.prepare(`SELECT * FROM projects WHERE id = ?`).get(run.projectId) as ProjectRow | undefined;
      if (!p) return;
      const b = run.branch ? getBranch(this.db, p.id, run.branch) : null;
      if (run.branch && !b) return;
      const main = await ensureGit({ db: this.db, cb: this.cb, log: this.log }, p);
      const prompt = run.body?.prompt
        ?? (this.db.prepare(`SELECT content FROM messages WHERE run_id = ? AND role = 'user'`).get(run.id) as { content: string } | undefined)?.content
        ?? '';
      const line = prompt.replace(/\s+/g, ' ').trim().slice(0, 60) || 'run';
      const r = await this.cb.git<{ sha: string | null; skipped?: string }>('checkpoint', {
        projectSlug: p.slug, ...(b ? { worktree: b.dir } : {}), message: `nxeon: ${line}`, expectBranch: b ? b.name : main,
      });
      if (r.skipped) this.log.warn({ runId: run.id, skipped: r.skipped }, 'checkpoint skipped');
      if (r.sha) {
        this.db.prepare(`UPDATE runs SET commit_sha = ? WHERE id = ?`).run(r.sha, run.id);
        this.hub.broadcastProject(p.id, { t: 'project_changed', projectId: p.id, what: 'history', branch: run.branch });
      }
      if (b) {
        const st = await this.cb.git<{ branches: { worktree: string; ahead?: number; behind?: number; filesChanged?: number }[] }>('status', {
          projectSlug: p.slug, branches: [{ worktree: b.dir, base: b.base }],
        });
        const x = st.branches?.[0];
        if (x && x.filesChanged != null)
          this.db.prepare(`UPDATE branches SET ahead = ?, behind = ?, files_changed = ?, stat_at = ? WHERE id = ?`).run(x.ahead ?? 0, x.behind ?? 0, x.filesChanged, now(), b.id);
      }
    } catch (err) {
      this.log.warn({ err: (err as Error).message, runId: run.id }, 'auto-checkpoint failed');
    }
  }

  /** Start the preview after a successful run if the checkout looks servable and nothing is running yet. */
  async autoStartPreview(projectId: string, branch: string | null = null) {
    try {
      const p = this.db.prepare(`SELECT * FROM projects WHERE id = ?`).get(projectId) as ProjectRow | undefined;
      if (!p) return;
      const b = branch ? getBranch(this.db, p.id, branch) : null;
      if (branch && !b) return;
      const dir = b ? worktreePath(this.cfg, p.slug, b.dir) : path.join(this.cfg.projectsDir, p.slug);
      const port = b ? b.preview_port : p.preview_port;
      if (!['index.html', 'package.json'].some((f) => fs.existsSync(path.join(dir, f)))) return;
      const cur = await this.cb.previewStatus(p.slug, port, b?.dir);
      if (cur.running) return;
      const s = await this.cb.previewStart(p.slug, port, p.preview_command, b?.dir);
      this.hub.broadcastProject(p.id, { t: 'preview_status', projectId: p.id, running: !!s.running, port: s.port ?? port, branch });
    } catch (err) {
      this.log.warn({ err: (err as Error).message, projectId, branch }, 'preview auto-start failed');
    }
  }

  // ---------------- abort ----------------

  async abort(runId: string): Promise<boolean> {
    const run = this.active.get(runId);
    if (!run) {
      // orphan (e.g. not driven by this process): mark aborted directly
      const r = this.db.prepare(`SELECT status FROM runs WHERE id = ?`).get(runId) as { status: RunStatus } | undefined;
      if (r && (r.status === 'running' || r.status === 'queued')) {
        this.db.prepare(`UPDATE runs SET status = 'aborted', ended_at = ? WHERE id = ?`).run(now(), runId);
        return true;
      }
      return false;
    }
    if (run.ended) return false;
    run.abortRequested = true;
    try {
      await this.cb.abort(runId);
    } catch (err) {
      this.log.warn({ runId, err: (err as Error).message }, 'claudebox abort failed');
    }
    setTimeout(() => {
      if (!run.ended) {
        run.controller.abort();
        this.synthEnd(run, null);
      }
    }, ABORT_GRACE_MS).unref();
    return true;
  }

  // ---------------- recovery ----------------

  /** On startup: re-attach to runs left running by a previous process, or mark them as errored. */
  recoverOrphans() {
    const rows = this.db
      .prepare(
        `SELECT r.id, r.conversation_id, r.project_id, r.user_id, r.upstream_seq, r.input_tokens, r.output_tokens, r.cache_read,
                r.cache_write, r.cost_usd, r.started_at, r.branch, r.mode, r.nexus_scope, m.id AS message_id
         FROM runs r LEFT JOIN messages m ON m.run_id = r.id AND m.role = 'assistant'
         WHERE r.status IN ('queued','running')`,
      )
      .all() as {
      id: string; conversation_id: string; project_id: string | null; user_id: string | null; upstream_seq: number;
      input_tokens: number; output_tokens: number; cache_read: number; cache_write: number; cost_usd: number;
      started_at: number; branch: string | null; mode: string; nexus_scope: string | null; message_id: string | null;
    }[];
    for (const r of rows) {
      if (this.active.has(r.id)) continue;
      const run = this.newState(r.id, r.conversation_id, r.project_id, r.user_id, r.message_id ?? '', null);
      run.startedAt = r.started_at;
      run.branch = r.branch;
      run.mode = r.mode;
      if (!r.project_id) {
        const sc = parseJson<NexusRunScope | null>(r.nexus_scope, null);
        run.nexus = { projects: sc?.projects ?? [], focus: sc?.focus ?? [], dirty: sc?.dirty ?? [], touched: new Set() };
      }
      run.upstreamSeq = r.upstream_seq;
      run.usage = { inputTokens: r.input_tokens, outputTokens: r.output_tokens, cacheReadTokens: r.cache_read, cacheWriteTokens: r.cache_write };
      run.costUsd = r.cost_usd;
      const evs = this.db.prepare(`SELECT seq, type, data FROM run_events WHERE run_id = ? ORDER BY seq`).all(r.id) as {
        seq: number; type: string; data: string;
      }[];
      for (const e of evs) {
        run.seq = e.seq;
        const d = parseJson<Record<string, unknown>>(e.data, {});
        if (e.type === 'text' && typeof d.delta === 'string' && !d.parentId) {
          run.fullText += d.delta;
          run.needSep = false;
        } else if (e.type === 'block_end' && d.kind === 'text') run.needSep = true;
        else if (e.type === 'nexus' && run.nexus && Array.isArray(d.touched)) {
          for (const id of d.touched) if (typeof id === 'string') run.nexus.touched.add(id);
        } else if (e.type === 'error') {
          run.sawError = true;
          run.lastError = String(d.message ?? 'error');
        }
      }
      run.emittedLen = run.fullText.length;
      this.active.set(run.id, run);
      this.log.info({ runId: r.id }, 'recovering orphaned run');
      void this.drive(run, true);
    }
  }

  /** Graceful shutdown: flush pending events; leave runs as running so the next start can re-attach. */
  shutdown() {
    this.flushAll();
    for (const run of this.active.values()) {
      run.ended = true; // stop drive loops without finalizing
      run.controller.abort();
    }
  }
}

