64	    .replace(/^-+|-+$/g, '')
65	    .slice(0, 40)
66	    .replace(/-+$/g, '');
67	  return s && SLUG_RE.test(s) ? s : `project-${crypto.randomBytes(3).toString('hex')}`;
68	}
