70	export function uniqueSlug(ctx: Ctx, base: string): string {
71	  const exists = (s: string) =>
72	    !!ctx.db.prepare(`SELECT 1 FROM projects WHERE slug = ?`).get(s) || fs.existsSync(path.join(ctx.cfg.projectsDir, s));
73	  if (!exists(base)) return base;
74	  for (let i = 2; i < 1000; i++) {
75	    const s = `${base.slice(0, 44)}-${i}`;
76	    if (!exists(s)) return s;
77	  }
78	  return `${base.slice(0, 40)}-${crypto.randomBytes(3).toString('hex')}`;
79	}
