86	export function visibleProjects(ctx: Ctx, user: UserRow, includeArchived: boolean): { p: ProjectRow; role: EffectiveRole }[] {
87	  const arch = includeArchived ? '' : 'AND p.archived = 0';
88	  if (user.role === 'admin') {
89	    return (ctx.db.prepare(`SELECT p.* FROM projects p WHERE 1=1 ${arch} ORDER BY COALESCE(p.last_active_at, p.created_at) DESC`).all() as ProjectRow[]).map(
90	      (p) => ({ p, role: 'admin' as const }),
91	    );
92	  }
93	  return (
94	    ctx.db
95	      .prepare(
96	        `SELECT p.*, m.role AS member_role, pm.role AS parent_role FROM projects p
97	         LEFT JOIN project_members m ON m.project_id = p.id AND m.user_id = ?
98	         LEFT JOIN project_members pm ON p.parent_id IS NOT NULL AND pm.project_id = p.parent_id AND pm.user_id = ?
99	         WHERE (m.role IS NOT NULL OR pm.role IS NOT NULL) ${arch} ORDER BY COALESCE(p.last_active_at, p.created_at) DESC`,
100	      )
101	      .all(user.id, user.id) as (ProjectRow & { member_role: ProjectRole | null; parent_role: ProjectRole | null })[]
