105	/** Background: refresh cached ahead/behind/changed-files of branches whose stats are older than a minute. */
106	const statsInFlight = new Set<string>();
107	function refreshBranchStats(ctx: Ctx, rows: BranchRow[], projects: Map<string, ProjectRow>) {
108	  const stale = new Map<string, BranchRow[]>();
109	  for (const b of rows) {
110	    if (b.stat_at && now() - b.stat_at < 60_000) continue;
111	    if (statsInFlight.has(b.project_id)) continue;
112	    const arr = stale.get(b.project_id) ?? [];
113	    arr.push(b);
114	    stale.set(b.project_id, arr);
115	  }
116	  for (const [pid, list] of stale) {
117	    const p = projects.get(pid);
118	    if (!p) continue;
119	    statsInFlight.add(pid);
120	    void (async () => {
121	      try {
122	        const main = p.git_main ?? 'main';
123	        const r = await ctx.cb.git<{ branches: { worktree: string; ahead?: number; behind?: number; filesChanged?: number }[] }>('status', {
124	          projectSlug: p.slug, branches: list.map((b) => ({ worktree: b.dir, base: rows.some((x) => x.project_id === pid && x.name === b.base) || b.base === main ? b.base : main })),
125	        }, 20_000);
126	        const upd = ctx.db.prepare(`UPDATE branches SET ahead = ?, behind = ?, files_changed = ?, stat_at = ? WHERE project_id = ? AND dir = ? AND status = 'active'`);
127	        for (const x of r.branches ?? []) if (x.filesChanged != null) upd.run(x.ahead ?? 0, x.behind ?? 0, x.filesChanged, now(), pid, x.worktree);
128	      } catch {
129	        /* claudebox busy/down */
130	      } finally {
131	        statsInFlight.delete(pid);
132	      }
133	    })();
134	  }
135	}
