137	/** Stop previews, abort runs, drop the DB rows and move the files (incl. branch worktrees) to .trash. */
138	export async function deleteProject(ctx: Ctx, project: ProjectRow) {
139	  const { db, cfg } = ctx;
140	  const active = db.prepare(`SELECT id FROM runs WHERE project_id = ? AND status IN ('queued','running')`).all(project.id) as { id: string }[];
141	  for (const r of active) await ctx.runs.abort(r.id);
142	  const branches = activeBranches(db, project.id);
143	  for (const target of [null, ...branches] as (BranchRow | null)[]) {
144	    try {
145	      await ctx.cb.previewStop(project.slug, target ? target.preview_port : project.preview_port, target?.dir);
146	    } catch {
147	      /* claudebox may be down; ignore */
148	    }
149	  }
150	  ctx.watchers.stop(project.id);
151	  db.transaction(() => {
152	    db.prepare(`DELETE FROM run_events WHERE run_id IN (SELECT id FROM runs WHERE project_id = ?)`).run(project.id);
153	    db.prepare(`DELETE FROM projects WHERE id = ?`).run(project.id);
154	  })();
155	  forgetGit(project.id);
156	  // Keep files recoverable: move the directory (and branch worktrees) into a hidden trash folder.
157	  const trash = path.join(cfg.projectsDir, '.trash');
158	  const stamp = Date.now();
159	  for (const [src, name] of [[path.join(cfg.projectsDir, project.slug), `${project.slug}-${stamp}`], [branchesRoot(cfg, project.slug), `${project.slug}-${stamp}.branches`]] as const) {
160	    if (!fs.existsSync(src)) continue;
161	    fs.mkdirSync(trash, { recursive: true });
162	    try {
163	      fs.renameSync(src, path.join(trash, name));
164	    } catch (err) {
165	      ctx.log.warn({ err: (err as Error).message }, 'failed to move project dir to trash');
166	    }
167	  }
168	}
