217	    /**
218	     * Spider-web graph. Project nodes (kind 'project' | 'subproject' with parentId) + links (core / link / affinity / child).
219	     * `?satellites=1` adds branch and topic nodes (kind 'branch' | 'topic', parentId = project id) and their links;
220	     * without it the response keeps the legacy shape (plus the additive kind/parentId fields).
221	     */
222	    app.get('/api/projects/graph', async (req) => {
223	      const u = requireUser(req);
224	      const withSatellites = ['1', 'true'].includes(String((req.query as { satellites?: string }).satellites ?? ''));
225	      const projects = visibleProjects(ctx, u, false);
226	      const ids = projects.map(({ p }) => p.id);
227	      const idSet = new Set(ids);
228	      const running = new Set<string>();
229	      const runningBranch = new Set<string>(); // `${projectId}|${branch}`
230	      const lastStatus = new Map<string, string>();
231	      if (ids.length) {
232	        const ph = ids.map(() => '?').join(',');
233	        for (const r of db
234	          .prepare(`SELECT DISTINCT project_id, branch FROM runs WHERE status IN ('queued','running') AND project_id IN (${ph})`)
235	          .all(...ids) as { project_id: string; branch: string | null }[]) {
236	          running.add(r.project_id);
237	          if (r.branch) runningBranch.add(`${r.project_id}|${r.branch}`);
238	        }
239	        for (const r of db
240	          .prepare(
241	            `SELECT r.project_id, r.status FROM runs r JOIN (SELECT project_id, MAX(started_at) AS m FROM runs WHERE project_id IN (${ph}) GROUP BY project_id) x
242	             ON x.project_id = r.project_id AND x.m = r.started_at`,
243	          )
244	          .all(...ids) as { project_id: string; status: string }[])
245	          lastStatus.set(r.project_id, r.status);
246	      }
247	      const t = now();
248	      const activityOf = (last: number, isRunning: boolean) => (isRunning ? 1 : Math.round(Math.exp(-(t - last) / 3600_000 / 24) * 100) / 100);
249	      const nodes: Record<string, unknown>[] = [{ id: 'core', kind: 'core', name: 'Nxeon Core', color: '#ff3e8a', icon: 'cpu', status: running.size ? 'running' : 'idle', activity: running.size ? 1 : 0.3, lastActiveAt: null }];
250	      for (const { p } of projects) {
251	        const last = p.last_active_at ?? p.created_at;
252	        const isRunning = running.has(p.id);
253	        const child = !!p.parent_id && idSet.has(p.parent_id);
254	        nodes.push({
255	          id: p.id, kind: child ? 'subproject' : 'project', parentId: child ? p.parent_id : null,
256	          slug: p.slug, name: p.name, color: p.color, icon: p.icon, description: p.description.slice(0, 200),
257	          status: isRunning ? 'running' : lastStatus.get(p.id) === 'error' ? 'error' : 'idle',
258	          activity: activityOf(last, isRunning),
259	          lastActiveAt: iso(last),
260	        });
261	      }
262	      const links: { source: string; target: string; kind: string }[] = [];
263	      for (const { p } of projects) {
264	        if (p.parent_id && idSet.has(p.parent_id)) links.push({ source: p.parent_id, target: p.id, kind: 'child' });
265	        else links.push({ source: 'core', target: p.id, kind: 'core' });
266	      }
267	      const seen = new Set<string>();
268	      const key = (a: string, b: string) => (a < b ? `${a}|${b}` : `${b}|${a}`);
269	      for (const l of links) seen.add(key(l.source, l.target));
270	      for (const { p } of projects) {
271	        for (const other of parseJson<string[]>(p.links, [])) {
272	          if (!idSet.has(other) || other === p.id || seen.has(key(p.id, other))) continue;
273	          seen.add(key(p.id, other));
274	          links.push({ source: p.id, target: other, kind: 'link' });
275	        }
276	      }
277	      // shared-member affinity between top-level projects: keep each node's 2 strongest (Jaccard) neighbours
278	      const top = projects.filter(({ p }) => !(p.parent_id && idSet.has(p.parent_id))).map(({ p }) => p.id);
279	      if (top.length > 1) {
280	        const ph = top.map(() => '?').join(',');
281	        const members = new Map<string, Set<string>>();
282	        for (const r of db.prepare(`SELECT project_id, user_id FROM project_members WHERE project_id IN (${ph})`).all(...top) as {
283	          project_id: string; user_id: string;
284	        }[]) {
285	          let st = members.get(r.project_id);
286	          if (!st) members.set(r.project_id, (st = new Set()));
287	          st.add(r.user_id);
288	        }
289	        const best = new Map<string, { other: string; score: number }[]>();
290	        for (let i = 0; i < top.length; i++)
291	          for (let j = i + 1; j < top.length; j++) {
292	            const a = members.get(top[i]!) ?? new Set<string>();
293	            const b = members.get(top[j]!) ?? new Set<string>();
294	            let inter = 0;
295	            for (const x of a) if (b.has(x)) inter++;
296	            if (!inter) continue;
297	            const score = inter / (a.size + b.size - inter);
298	            for (const [x, y] of [[top[i]!, top[j]!], [top[j]!, top[i]!]] as const) {
299	              const l = best.get(x) ?? [];
300	              l.push({ other: y, score });
301	              best.set(x, l);
302	            }
303	          }
304	        for (const [id, l] of best) {
305	          l.sort((a, b) => b.score - a.score);
306	          for (const { other } of l.slice(0, 2)) {
307	            const k = key(id, other);
308	            if (seen.has(k)) continue;
309	            seen.add(k);
310	            links.push({ source: id, target: other, kind: 'affinity' });
311	          }
312	        }
313	      }
314	
315	      if (withSatellites && ids.length) {
316	        const ph = ids.map(() => '?').join(',');
317	        const bySlug = new Map(projects.map(({ p }) => [p.id, p]));
318	        // managed previews currently alive (one cheap call; failures just mean "unknown")
319	        const livePreviews = new Set<string>();
320	        try {
321	          for (const pv of (await ctx.cb.previews(1200)).previews ?? []) if (pv.running && pv.projectSlug) livePreviews.add(pv.projectSlug);
322	        } catch {
323	          /* claudebox down */
324	        }
325	        const lastBranchRun = new Map<string, number>();
326	        for (const r of db
327	          .prepare(`SELECT project_id, branch, MAX(started_at) AS m FROM runs WHERE branch IS NOT NULL AND project_id IN (${ph}) GROUP BY project_id, branch`)
328	          .all(...ids) as { project_id: string; branch: string; m: number }[])
329	          lastBranchRun.set(`${r.project_id}|${r.branch}`, r.m);
330	        const activeBranchRows = db.prepare(`SELECT * FROM branches WHERE status = 'active' AND project_id IN (${ph}) ORDER BY created_at`).all(...ids) as BranchRow[];
331	        refreshBranchStats(ctx, activeBranchRows, bySlug);
332	        for (const b of activeBranchRows) {
333	          const p = bySlug.get(b.project_id)!;
334	          const isRunning = runningBranch.has(`${b.project_id}|${b.name}`);
335	          const last = lastBranchRun.get(`${b.project_id}|${b.name}`) ?? b.created_at;
336	          nodes.push({
337	            id: `branch:${b.id}`, kind: 'branch', parentId: b.project_id, slug: p.slug, branch: b.name, name: b.name, color: p.color,
338	            status: isRunning ? 'running' : 'idle', activity: activityOf(last, isRunning), lastActiveAt: iso(last),
339	            base: b.base, ahead: b.ahead, behind: b.behind, filesChanged: b.files_changed,
340	            previewRunning: livePreviews.has(previewKey(p.slug, b)),
341	          });
342	          links.push({ source: b.project_id, target: `branch:${b.id}`, kind: 'branch' });
343	        }
344	        for (const tp of db
345	          .prepare(
346	            `SELECT t.*, (SELECT COUNT(*) FROM conversations c WHERE c.topic_id = t.id) AS n FROM topics t WHERE t.project_id IN (${ph}) ORDER BY t.sort, t.created_at`,
347	          )
348	          .all(...ids) as { id: string; project_id: string; name: string; color: string; n: number }[]) {
349	          const p = bySlug.get(tp.project_id)!;
350	          nodes.push({
351	            id: `topic:${tp.id}`, kind: 'topic', parentId: tp.project_id, slug: p.slug, topicId: tp.id, name: tp.name, color: tp.color,
352	            status: 'idle', activity: 0, conversations: tp.n,
353	          });
354	          links.push({ source: tp.project_id, target: `topic:${tp.id}`, kind: 'topic' });
355	        }
356	        for (const { p } of projects) {
357	          if (!livePreviews.has(p.slug)) continue;
358	          const n = nodes.find((x) => x.id === p.id);
359	          if (n) n.previewRunning = true;
360	        }
361	      }
362	      return { nodes, links };
363	    });
