const server = http.createServer(async (req, res) => {
  let url;
  try {
    url = new URL(req.url, "http://localhost");
  } catch {
    sendJSON(res, 400, { error: "Bad URL" });
    return;
  }

  try {
    // --- Health check ---
    if (req.method === "GET" && url.pathname === "/health") {
