        sandboxMode: SANDBOX_MODE,
        sandboxAvailable: sandbox.strict ? sandbox.available() : null,
        autoPermissionMode: AUTO_PERMISSION_MODE,
      });
      return;
    }

    if (url.pathname.startsWith("/v2/")) {
      await handleV2(req, res, url);
      return;
    }
  } catch (err) {
    if (err instanceof SandboxError) {
      if (!res.headersSent) sendJSON(res, err.status, { error: err.message, code: "sandbox" });
      return;
    }
    log("error", "request failed", { path: url.pathname, error: err.message });
    if (!res.headersSent) sendJSON(res, 500, { error: err.message });
    else res.end();
    return;
  }

