import { request } from 'undici';
import type { Config } from './config.js';
import type { SandboxSpec } from './lib/sandbox.js';

export interface V2RunBody {
  runId: string;
  prompt: string;
  projectSlug: string;
  sessionId: string | null;
  model: string;
  mode: string;
  thinking: string;
  attachments: string[];
  appendSystemPrompt: string;
  maxTurns: number;
  /** `--max-budget-usd` (this invocation's spend only); absent = no cap */
  maxBudgetUsd?: number;
  /** explicit `--effort` (otherwise claudebox maps `thinking`) */
  effort?: 'low' | 'medium' | 'high';
  /** lean mode: trimmed base context + tool-output caps (claudebox LEAN_* lists) */
  lean?: boolean;
  /** absent for Nexus runs (no preview port) */
  previewPort?: number;
  /** Branch runs: worktree dir under .branches/<slug>/ (cwd + preview key <slug>--<worktree>). */
  worktree?: string;
  authToken?: string;
  /** Context size at which to auto-compact (0/absent = CLI default). */
  autocompactTokens?: number;
  /** Custom subagents → `--agents`. */
  agents?: Record<string, { description: string; prompt: string; tools?: string[]; model?: string }>;
  /** Lead agent → `--agent` (must be a key of `agents`). */
  agent?: string;
  /** Sandbox identity (claudebox SANDBOX_MODE=strict). Attached automatically from projectSlug when absent. */
  sandbox?: SandboxSpec;
  /** Multi-project runs only: cwd under /workspace/.nexus (requires `sandbox`) + project dirs for --add-dir. */
  cwd?: string;
  addDirs?: string[];
}

export interface PreviewStatusUpstream {
  projectSlug?: string;
  running: boolean;
  managed?: boolean;
  listening?: boolean;
  port: number | null;
  pid?: number | null;
  kind?: string | null;
  command?: string | null;
  startedAt?: number | null;
  exitCode?: number | null;
  logTail?: string[] | string;
}

export class ClaudeboxError extends Error {
  constructor(public statusCode: number, message: string, public body: unknown = null) {
    super(message);
  }
}

export class Claudebox {
  /** Project slug → sandbox spec (set by the app from the DB); attached to every project-scoped call. */
  sandboxFor: (projectSlug: string) => SandboxSpec | null = () => null;

  constructor(private cfg: Config) {}

  private withSandbox<T extends Record<string, unknown>>(body: T): T {
    if (body.sandbox !== undefined || typeof body.projectSlug !== 'string') return body;
    const sandbox = this.sandboxFor(body.projectSlug);
    return sandbox ? { ...body, sandbox } : body;
  }

  private headers(extra: Record<string, string> = {}) {
    return {
      authorization: `Bearer ${this.cfg.claudeboxApiKey}`,
      ...extra,
    };
  }

  /** Start a run; returns the raw undici response (SSE body). */
  startRun(body: V2RunBody, signal: AbortSignal) {
    return request(`${this.cfg.claudeboxUrl}/v2/run`, {
      method: 'POST',
      headers: this.headers({ 'content-type': 'application/json', accept: 'text/event-stream' }),
      body: JSON.stringify(this.withSandbox(body as unknown as Record<string, unknown>)),
      signal,
      headersTimeout: 60_000,
      bodyTimeout: 0,
    });
  }

  /** Re-attach to a run's buffered event stream. */
  attach(runId: string, fromSeq: number, signal: AbortSignal) {
    return request(`${this.cfg.claudeboxUrl}/v2/run/${encodeURIComponent(runId)}/events?fromSeq=${fromSeq}`, {
      method: 'GET',
      headers: this.headers({ accept: 'text/event-stream' }),
      signal,
      headersTimeout: 30_000,
      bodyTimeout: 0,
    });
  }

  private async json<T>(method: 'GET' | 'POST', path: string, body?: unknown, timeoutMs = 15_000): Promise<T> {
    const res = await request(`${this.cfg.claudeboxUrl}${path}`, {
      method,
      headers: this.headers(body !== undefined ? { 'content-type': 'application/json' } : {}),
      body: body !== undefined ? JSON.stringify(body) : undefined,
      headersTimeout: timeoutMs,
      bodyTimeout: timeoutMs,
    });
    const text = await res.body.text();
    let data: unknown = text;
    try {
      data = JSON.parse(text);
    } catch {
      /* not json */
    }
    if (res.statusCode >= 400) {
      const msg =
        (data as { error?: string | { message?: string } })?.error ?? (typeof data === 'string' ? data : `HTTP ${res.statusCode}`);
      throw new ClaudeboxError(res.statusCode, typeof msg === 'string' ? msg : msg?.message ?? `HTTP ${res.statusCode}`, data);
    }
    return data as T;
  }

  abort(runId: string) {
    return this.json<unknown>('POST', '/v2/abort', { runId });
  }
  previewStart(projectSlug: string, port: number, command?: string | null, worktree?: string | null) {
    return this.json<PreviewStatusUpstream>(
      'POST', '/v2/preview/start', this.withSandbox({ projectSlug, port, ...(command ? { command } : {}), ...(worktree ? { worktree } : {}) }), 120_000,
    );
  }
  previewStop(projectSlug: string, port?: number, worktree?: string | null) {
    return this.json<PreviewStatusUpstream & { stopped?: boolean }>('POST', '/v2/preview/stop', this.withSandbox({
      projectSlug, ...(port ? { port } : {}), ...(worktree ? { worktree } : {}),
    }));
  }
  previewStatus(projectSlug: string, port?: number, worktree?: string | null) {
    return this.json<PreviewStatusUpstream>(
      'GET',
      `/v2/preview/status?projectSlug=${encodeURIComponent(projectSlug)}${port ? `&port=${port}` : ''}${worktree ? `&worktree=${encodeURIComponent(worktree)}` : ''}`,
    );
  }
  previews(timeoutMs = 2000) {
    return this.json<{ previews: PreviewStatusUpstream[] }>('GET', '/v2/previews', undefined, timeoutMs);
  }
  /** POST /v2/git/<op> (see claudebox/lib/git.js). */
  git<T = Record<string, unknown>>(op: string, body: Record<string, unknown>, timeoutMs = 130_000) {
    return this.json<T>('POST', `/v2/git/${op}`, this.withSandbox(body), timeoutMs);
  }
  /** Create/repair a project's sandbox (dir ownership + ACLs, home, one-time session migration). Idempotent. */
  sandboxSetup(projectSlug: string, force = false) {
    return this.json<{ ok?: boolean; heavy?: boolean; skipped?: boolean; mode?: string }>(
      'POST', '/v2/sandbox/setup', this.withSandbox({ projectSlug, ...(force ? { force: true } : {}) }), 600_000,
    );
  }
  health() {
    return this.json<Record<string, unknown>>('GET', '/health', undefined, 5000);
  }
}

