export interface ModelSetting {
  id: string;
  label: string;
}

export type ModelFamily = 'opus' | 'sonnet' | 'haiku';
/** $ per million tokens. cacheWrite = 1-hour TTL write (2x input; what a subscription's main thread gets). */
export interface ModelPrice {
  input: number;
  output: number;
  cacheWrite: number;
  cacheRead: number;
}

export interface AppSettings {
  models: ModelSetting[];
  defaultModel: string;
  /** Global daily token cap across all users (input+output tokens). null = unlimited. */
  globalDailyTokens: number | null;
  /** Default per-user daily token budget when the user has none set. null = unlimited. */
  defaultUserDailyTokens: number | null;
  maxTurns: number;
  /** Context size (tokens) at which Claude auto-compacts the conversation. 0 = CLI default ("auto"). */
  autoCompactTokens: number;
  // ---- efficiency (Admin → Settings → Efficiency; docs/research/token-efficiency.md) ----
  /** Master switch: trimmed base context, tool-output caps, effort per mode, frugal prompt rules. */
  leanMode: boolean;
  /** Ask before resuming an idle (cache-cold) large conversation: resume vs. fresh session with a free summary. */
  coldResumeGuard: boolean;
  coldResumeMinutes: number;
  coldResumeMinTokens: number;
  /** Per-run `--max-budget-usd` by model family (0 = no cap). */
  maxBudgetUsd: Record<ModelFamily, number>;
  /** Context size at which the UI suggests starting a new chat. 0 = never. */
  newChatHintTokens: number;
  /** API-equivalent prices ($/MTok) used for estimates and for runs that end without a reported cost. */
  prices: Record<ModelFamily, ModelPrice>;
}

