  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.5rem;
  --space-6: 2rem;
  --space-7: 3rem;
  --space-8: 4rem;
  --space-9: 6rem;
  --space-10: 8rem;
  --section-pad: clamp(var(--space-8), 8vw, var(--space-10));
  --container: min(1140px, 92vw);

  /* shape + depth */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 16px;
  --radius-pill: 999px;
  --shadow-sm: 0 1px 2px rgb(20 16 12 / 0.06);
  --shadow-md: 0 4px 14px rgb(20 16 12 / 0.08);
