    copyLicense(dir, path.join(OUT, 'LICENSES', 'fonts', `${f.id}.txt`));
    const meta = { id: f.id, family, role: f.role, tags: f.tags, variable: f.variable, weights: [...weights], styles: [...styles], license: pj.license, source: `${f.pkg}@${f.version}`, files: fs.readdirSync(dest).filter((x) => x.endsWith('.woff2')) };
    fs.writeFileSync(path.join(dest, 'meta.json'), JSON.stringify(meta, null, 1) + '\n');
