#!/usr/bin/env node
// Builds the Nxeon asset library (data/library) from library/manifest.json + the sources in library/.
// Usage: node scripts/build.mjs [--out DIR] [--cache DIR] [--offline] [--update-checksums]
// Reproducible: npm packages are pinned (npm verifies registry integrity; tarball sha256 is recorded too),
// URL downloads (illustrations, HyperUI tarball, vendored licence) are pinned by sha256 in manifest.checksums.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { brandCss, contrast } from './brand.mjs';

const SRC = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const args = process.argv.slice(2);
const opt = (name, def) => {
  const i = args.indexOf(name);
  return i >= 0 ? args[i + 1] : def;
};
const FINAL = path.resolve(opt('--out', path.join(SRC, '..', 'data', 'library')));
const CACHE = path.resolve(opt('--cache', path.join(SRC, '..', 'data', '.library-cache')));
const UPDATE = args.includes('--update-checksums');
const OUT = `${FINAL}.new`;
const manifestPath = path.join(SRC, 'manifest.json');
const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
manifest.checksums ??= {};
const ALLOWED = new Set(manifest.allowedLicenses);
let checksumsChanged = false;
const catalog = []; // [kind, set, id, tags, path, license]
const summary = {};
const log = (...a) => console.log('[library]', ...a);

const sha256 = (buf) => crypto.createHash('sha256').update(buf).digest('hex');
const mkdir = (d) => fs.mkdirSync(d, { recursive: true });
const clean = (s) => String(s ?? '').replace(/[\t\r\n]+/g, ' ').replace(/\s+/g, ' ').trim().toLowerCase();
function row(kind, set, id, tags, p, license) {
  catalog.push([kind, set, id, clean(tags), p, license]);
  summary[`${kind}/${set}`] = (summary[`${kind}/${set}`] || 0) + 1;
}
function checkLicense(name, license) {
  const parts = String(license).split(/\s+(?:OR|AND)\s+|[()]/).map((s) => s.trim()).filter(Boolean);
  if (!parts.length || !parts.every((p) => ALLOWED.has(p))) throw new Error(`licence not allowed for ${name}: ${license}`);
}
function verify(key, buf) {
  const h = sha256(buf);
  const want = manifest.checksums[key];
  if (want && want !== h && !UPDATE) throw new Error(`checksum mismatch for ${key}: ${h} != ${want}`);
  if (want !== h) {
    manifest.checksums[key] = h;
    checksumsChanged = true;
  }
}

async function download(url, key) {
  mkdir(path.join(CACHE, 'url'));
  const f = path.join(CACHE, 'url', sha256(url).slice(0, 24));
  let buf;
  if (fs.existsSync(f)) buf = fs.readFileSync(f);
  else {
    for (let i = 0; i < 3 && !buf; i++) {
      try {
        const r = await fetch(url);
        if (!r.ok) throw new Error(`HTTP ${r.status}`);
        buf = Buffer.from(await r.arrayBuffer());
      } catch (e) {
        if (i === 2) throw new Error(`download failed ${url}: ${e.message}`);
      }
    }
    fs.writeFileSync(f, buf);
  }
  verify(key, buf);
  return buf;
}

/** npm pack (cached) + extract → dir containing package/. */
function npmPkg(pkg, version) {
  const dir = path.join(CACHE, 'npm', `${pkg.replace('/', '__')}@${version}`);
  if (!fs.existsSync(path.join(dir, 'package'))) {
    mkdir(dir);
    const out = execFileSync('npm', ['pack', `${pkg}@${version}`, '--pack-destination', dir, '--json', '--silent'], { encoding: 'utf8' });
    const file = JSON.parse(out)[0].filename.replace(/^@/, '').replace('/', '-');
    const tgz = fs.readdirSync(dir).find((x) => x.endsWith('.tgz')) || file;
    execFileSync('tar', ['xzf', path.join(dir, tgz), '-C', dir]);
  }
  const tgz = fs.readdirSync(dir).find((x) => x.endsWith('.tgz'));
  verify(`npm:${pkg}@${version}`, fs.readFileSync(path.join(dir, tgz)));
  const pj = JSON.parse(fs.readFileSync(path.join(dir, 'package', 'package.json'), 'utf8'));
  if (pj.version !== version) throw new Error(`${pkg}: got ${pj.version}, want ${version}`);
  return { dir, pj };
}
function copyLicense(dir, dest) {
  const f = ['LICENSE', 'LICENSE.md', 'LICENSE.txt', 'license', 'LICENCE'].map((x) => path.join(dir, 'package', x)).find((x) => fs.existsSync(x));
  mkdir(path.dirname(dest));
  if (f) fs.copyFileSync(f, dest);
  return !!f;
}
function copyDir(src, dest, filter = () => true) {
  mkdir(dest);
  for (const e of fs.readdirSync(src, { withFileTypes: true })) {
    const s = path.join(src, e.name);
    const d = path.join(dest, e.name);
    if (!filter(s, e)) continue;
    if (e.isDirectory()) copyDir(s, d, filter);
    else if (e.isFile()) fs.copyFileSync(s, d);
  }
}

// ------------------------------------------------------------------ icons
async function icons() {
  for (const set of manifest.icons) {
    const { dir, pj } = npmPkg(set.pkg, set.version);
    checkLicense(set.pkg, pj.license);
    copyLicense(dir, path.join(OUT, 'LICENSES', `icons-${set.set}.txt`));
    let tags = {};
    if (set.set === 'lucide') tags = Object.fromEntries(Object.entries(JSON.parse(fs.readFileSync(path.join(dir, set.tags)))).map(([k, v]) => [k, v.join(' ')]));
    if (set.set === 'tabler')
      tags = Object.fromEntries(Object.values(JSON.parse(fs.readFileSync(path.join(dir, set.tags)))).map((i) => [i.name, `${i.category || ''} ${(i.tags || []).join(' ')}`]));
    if (set.set === 'phosphor') {
      const mod = await import(pathToFileURL(path.join(dir, set.tags)).href);
      const list = mod.icons || mod.default?.icons || [];
      tags = Object.fromEntries(list.map((i) => [i.name, `${(i.categories || []).join(' ')} ${(i.tags || []).filter((t) => !t.startsWith('*')).join(' ')}`]));
    }
    if (set.set === 'simple-icons') {
      const data = JSON.parse(fs.readFileSync(path.join(dir, set.tags)));
      const arr = Array.isArray(data) ? data : data.icons;
      tags = Object.fromEntries(arr.map((i) => [i.slug || i.title.toLowerCase().replace(/[^a-z0-9]/g, ''), `${i.title} brand logo ${(i.aliases?.aka || []).join(' ')}`]));
    }
    const names = new Set();
    for (const [variant, rel] of Object.entries(set.variants)) {
      const src = path.join(dir, rel);
      const dest = path.join(OUT, 'icons', set.set, ...(variant ? [variant] : []));
      mkdir(dest);
      for (const f of fs.readdirSync(src)) {
        if (!f.endsWith('.svg')) continue;
        fs.copyFileSync(path.join(src, f), path.join(dest, f));
        if (!variant) names.add(f.slice(0, -4));
      }
    }
    const variants = Object.keys(set.variants).filter(Boolean);
    for (const n of [...names].sort()) {
      row('icon', set.set, n, `${n.replace(/-/g, ' ')} ${tags[n] || ''}${variants.length ? ` variants:${variants.join(',')}` : ''}`, `icons/${set.set}/${n}.svg`, pj.license);
    }
    log(`icons ${set.set}: ${names.size}`);
  }
}

// ------------------------------------------------------------------ fonts
const SUBSETS = new Set(['latin', 'latin-ext']);
function fontFaces(css) {
  const out = [];
  for (const m of css.matchAll(/\/\*\s*([^*]+?)\s*\*\/\s*@font-face\s*\{([^}]*)\}/g)) {
    const body = m[2];
    const fam = /font-family:\s*'([^']+)'/.exec(body)?.[1];
    const url = /url\(\.\/files\/([^)]+\.woff2)\)/.exec(body)?.[1];
    if (!fam || !url) continue;
    const subset = /-(latin-ext|latin|cyrillic-ext|cyrillic|greek-ext|greek|vietnamese|[a-z-]+?)-(?:[0-9]+|wght|full|standard|opsz|soft|wonk|wdth)-(?:normal|italic)\.woff2$/.exec(url)?.[1];
    if (!SUBSETS.has(subset)) continue;
    out.push({ fam, url, body });
  }
  return out;
}
function fonts() {
  const metas = {};
  for (const f of manifest.fonts) {
    const { dir, pj } = npmPkg(f.pkg, f.version);
    checkLicense(f.pkg, pj.license);
    const pdir = path.join(dir, 'package');
    const cssFiles = f.variable
      ? ['index.css', 'wght-italic.css'].filter((x) => fs.existsSync(path.join(pdir, x)))
      : ['400.css', '400-italic.css', '500.css', '600.css', '700.css', '700-italic.css'].filter((x) => fs.existsSync(path.join(pdir, x)));
    const dest = path.join(OUT, 'fonts', f.id);
    mkdir(dest);
    const faces = [];
    let family = null;
    const weights = new Set();
    const styles = new Set();
    for (const cf of cssFiles) {
      for (const face of fontFaces(fs.readFileSync(path.join(pdir, cf), 'utf8'))) {
        family = face.fam.replace(/ Variable$/, '');
        fs.copyFileSync(path.join(pdir, 'files', face.url), path.join(dest, face.url));
        const w = /font-weight:\s*([^;]+);/.exec(face.body)?.[1]?.trim();
        const s = /font-style:\s*([^;]+);/.exec(face.body)?.[1]?.trim();
        if (w) weights.add(w);
        if (s) styles.add(s);
        faces.push(
          `/* ${face.url.replace('.woff2', '')} */\n@font-face {` +
            face.body.replace(/font-family:\s*'[^']+'/, `font-family: '${family}'`).replace(/url\(\.\/files\//, 'url(./').replace(/\s+/g, ' ').replace(/;\s*/g, ';\n  ').replace(/^\s*/, '\n  ').replace(/\s*$/, '\n') +
            '}',
        );
      }
    }
    if (!faces.length) throw new Error(`no latin faces for ${f.id}`);
    fs.writeFileSync(path.join(dest, 'font-face.css'), `/* ${family} — ${pj.license}, from ${f.pkg}@${f.version} (Fontsource). Copy this file + the woff2 files into the project (nx-font does it). */\n${faces.join('\n')}\n`);
    copyLicense(dir, path.join(OUT, 'LICENSES', 'fonts', `${f.id}.txt`));
    const meta = { id: f.id, family, role: f.role, tags: f.tags, variable: f.variable, weights: [...weights], styles: [...styles], license: pj.license, source: `${f.pkg}@${f.version}`, files: fs.readdirSync(dest).filter((x) => x.endsWith('.woff2')) };
    fs.writeFileSync(path.join(dest, 'meta.json'), JSON.stringify(meta, null, 1) + '\n');
    metas[f.id] = meta;
    row('font', 'fontsource', f.id, `${family} ${f.tags} ${f.variable ? 'variable' : `weights:${[...weights].join(',')}`}`, `fonts/${f.id}/`, pj.license);
  }
  fs.copyFileSync(path.join(SRC, 'fonts', 'pairings.json'), path.join(OUT, 'fonts', 'pairings.json'));
  const pairs = JSON.parse(fs.readFileSync(path.join(SRC, 'fonts', 'pairings.json'))).pairs;
  for (const p of pairs) {
    if (!metas[p.display] || !metas[p.body]) throw new Error(`pairing references unknown font: ${p.display}/${p.body}`);
    row('pairing', 'nxeon', `${p.display}+${p.body}`, `${p.mood} ${p.use} scale:${p.scale}`, 'fonts/pairings.json', 'MIT(nxeon)');
  }
  log(`fonts: ${Object.keys(metas).length}, pairings: ${pairs.length}`);
  return metas;
}

// ------------------------------------------------------------------ css libs
function cssLibs() {
  for (const c of manifest.css) {
    const { dir, pj } = npmPkg(c.pkg, c.version);
    checkLicense(c.pkg, pj.license);
    mkdir(path.join(OUT, 'css'));
    for (const [name, rel] of Object.entries(c.files)) {
      fs.copyFileSync(path.join(dir, rel), path.join(OUT, 'css', name));
      row('css', c.pkg.replace(/^@[^/]+\//, ''), name.replace(/\.(min\.)?(css|js)$/, ''), `${pj.description || ''}`, `css/${name}`, pj.license);
    }
    copyLicense(dir, path.join(OUT, 'LICENSES', `css-${c.pkg.replace(/[@/]/g, '_')}.txt`));
  }
}

// ------------------------------------------------------------------ HyperUI
async function hyperui() {
  const h = manifest.hyperui;
  checkLicense('hyperui', h.license);
  const buf = await download(`https://codeload.github.com/${h.repo}/tar.gz/${h.commit}`, `hyperui@${h.commit}`);
  const tmp = path.join(CACHE, `hyperui-${h.commit}`);
  if (!fs.existsSync(tmp)) {
    mkdir(tmp);
    const tgz = path.join(tmp, 'src.tgz');
    fs.writeFileSync(tgz, buf);
    execFileSync('tar', ['xzf', tgz, '-C', tmp, '--wildcards', `*/${h.path}/*`, '*/LICENSE*']);
  }
  const root = path.join(tmp, fs.readdirSync(tmp).find((x) => x.startsWith('hyperui-')));
  const lic = fs.readdirSync(root).find((x) => x.startsWith('LICENSE'));
  fs.copyFileSync(path.join(root, lic), path.join(OUT, 'LICENSES', 'hyperui.txt'));
  const src = path.join(root, h.path);
  let n = 0;
  const walk = (d) => {
    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
      const p = path.join(d, e.name);
      if (e.isDirectory()) walk(p);
      else if (e.name.endsWith('.html')) {
        const rel = path.relative(src, p);
        const dest = path.join(OUT, 'hyperui', rel);
        mkdir(path.dirname(dest));
        fs.copyFileSync(p, dest);
        const parts = rel.replace(/\.html$/, '').split(path.sep);
        row('ui', 'hyperui', parts.join('-'), `${parts.join(' ').replace(/-/g, ' ')} tailwind`, `hyperui/${rel}`, 'MIT');
        n++;
      }
    }
  };
  walk(src);
  log(`hyperui: ${n}`);
}

// ------------------------------------------------------------------ illustrations + avatars
async function illustrations() {
  for (const s of manifest.illustrations) {
    checkLicense(s.set, s.license);
    const dest = path.join(OUT, 'illustrations', s.set);
    mkdir(dest);
    for (const f of s.files) {
      const buf = await download(f.url, `${s.set}/${f.name}`);
      if (!/^\s*(<\?xml[^>]*>\s*)?(<!--[\s\S]*?-->\s*)*<svg[\s>]/.test(buf.toString('utf8', 0, 2000))) throw new Error(`not an svg: ${f.url}`);
      fs.writeFileSync(path.join(dest, `${f.name}.svg`), buf);
      row('illus', s.set, f.name, `${f.name.replace(/[-_]/g, ' ')} ${s.set.replace('-', ' ')} people illustration hand drawn`, `illustrations/${s.set}/${f.name}.svg`, s.license);
    }
    fs.writeFileSync(path.join(OUT, 'LICENSES', `illustrations-${s.set}.txt`), `${s.set} by ${s.author} — ${s.source}\nLicence: CC0 1.0 Universal (public domain dedication), https://creativecommons.org/publicdomain/zero/1.0/\nNo attribution required; credit appreciated.\n`);
    log(`illustrations ${s.set}: ${s.files.length}`);
  }
  // DiceBear Open Peeps avatars (CC0 design), generated deterministically.
  const a = manifest.avatars;
  const work = path.join(CACHE, `dicebear-${a.version}`);
  if (!fs.existsSync(path.join(work, 'node_modules', '@dicebear', 'core'))) {
    mkdir(work);
    fs.writeFileSync(path.join(work, 'package.json'), '{"private":true,"type":"module"}');
    execFileSync('npm', ['install', '--no-audit', '--no-fund', '--silent', `${a.pkg}@${a.version}`, `${a.style}@${a.styleVersion}`], { cwd: work, stdio: 'inherit' });
  }
  const core = await import(pathToFileURL(path.join(work, 'node_modules', '@dicebear', 'core', 'lib', 'index.js')).href);
  const style = await import(pathToFileURL(path.join(work, 'node_modules', '@dicebear', 'open-peeps', 'lib', 'index.js')).href);
  const dest = path.join(OUT, 'illustrations', 'avatars');
  mkdir(dest);
  const seeds = ['ada', 'bo', 'cleo', 'dev', 'eli', 'fay', 'gus', 'hana', 'ivo', 'jun', 'kai', 'lea', 'mo', 'nia', 'oz', 'pia', 'quin', 'rui', 'sol', 'tess', 'uma', 'vik', 'wen', 'yara'].slice(0, a.count);
  for (const seed of seeds) {
    const svg = core.createAvatar(style, { seed, backgroundColor: ['transparent'] }).toString();
    fs.writeFileSync(path.join(dest, `peep-avatar-${seed}.svg`), svg);
    row('illus', 'avatars', `peep-avatar-${seed}`, 'avatar person face portrait open peeps placeholder testimonial team', `illustrations/avatars/peep-avatar-${seed}.svg`, 'CC0-1.0');
  }
  copyLicense({ dir: path.join(work, 'node_modules', '@dicebear', 'open-peeps', '..', '..', '..') }.dir ? path.join(work, 'node_modules', '@dicebear', 'open-peeps', '..') : work, path.join(OUT, 'LICENSES', 'dicebear-unused.txt'));
  fs.rmSync(path.join(OUT, 'LICENSES', 'dicebear-unused.txt'), { force: true });
  fs.copyFileSync(path.join(work, 'node_modules', '@dicebear', 'open-peeps', 'LICENSE'), path.join(OUT, 'LICENSES', 'avatars-dicebear-open-peeps.txt'));
  log(`avatars: ${seeds.length}`);
}

// ------------------------------------------------------------------ own sources
function own(fontMetas) {
  for (const d of ['base', 'sections', 'templates', 'checklists', 'patterns', 'plugin']) {
    if (fs.existsSync(path.join(SRC, d))) copyDir(path.join(SRC, d), path.join(OUT, d), (p) => !/node_modules|\.DS_Store/.test(p));
  }
  fs.copyFileSync(path.join(SRC, 'README.library.md'), path.join(OUT, 'README.md'));
  mkdir(path.join(OUT, 'scripts'));
  fs.copyFileSync(path.join(SRC, 'scripts', 'brand.mjs'), path.join(OUT, 'scripts', 'brand.mjs'));
  // presets: JSON + generated CSS (contrast-checked)
  mkdir(path.join(OUT, 'presets'));
  for (const f of fs.readdirSync(path.join(SRC, 'presets')).filter((x) => x.endsWith('.json')).sort()) {
    const p = JSON.parse(fs.readFileSync(path.join(SRC, 'presets', f), 'utf8'));
    const c = p.palette;
    const checks = { text: [c.text, c.bg, 7], muted: [c.muted, c.bg, 4.5], button: [c.primaryContrast, c.primary, 4.5], link: [c.primary, c.bg, 4.5], accent: [c.accent, c.bg, 3] };
    for (const [k, [a, b, min]] of Object.entries(checks)) if (contrast(a, b) < min) throw new Error(`preset ${p.id}: ${k} contrast ${contrast(a, b).toFixed(2)} < ${min}`);
    for (const k of ['display', 'body', 'mono']) if (!fontMetas[p.fonts[k]]) throw new Error(`preset ${p.id}: unknown font ${p.fonts[k]}`);
    fs.copyFileSync(path.join(SRC, 'presets', f), path.join(OUT, 'presets', f));
    fs.writeFileSync(path.join(OUT, 'presets', `${p.id}.css`), brandCss(p, (id) => fontMetas[id] || null));
    row('preset', 'nxeon', p.id, `${p.name} ${p.mood} ${p.tags} fonts:${p.fonts.display}+${p.fonts.body}`, `presets/${p.id}.json`, 'MIT(nxeon)');
  }
  // sections
  const sidx = path.join(SRC, 'sections', 'index.tsv');
  if (fs.existsSync(sidx)) {
    for (const line of fs.readFileSync(sidx, 'utf8').trim().split('\n').slice(1)) {
      const [id, kind, tags, use] = line.split('\t');
      if (!fs.existsSync(path.join(SRC, 'sections', `${id}.html`))) throw new Error(`section missing: ${id}`);
      row('section', 'nxeon', id, `${kind} ${tags} ${use || ''}`, `sections/${id}.html`, 'MIT(nxeon)');
    }
  }
  // templates
  for (const t of fs.existsSync(path.join(SRC, 'templates')) ? fs.readdirSync(path.join(SRC, 'templates')) : []) {
    const tj = path.join(SRC, 'templates', t, 'template.json');
    if (!fs.existsSync(tj)) continue;
    const m = JSON.parse(fs.readFileSync(tj, 'utf8'));
    row('template', 'nxeon', m.id, `${m.title} ${m.when} ${(m.stack || []).join(' ')}`, `templates/${m.id}/`, 'MIT(nxeon)');
  }
  for (const line of fs.readFileSync(path.join(SRC, 'patterns', 'index.tsv'), 'utf8').trim().split('\n').slice(1)) {
    const [id, tags] = line.split('\t');
    row('pattern', 'nxeon', id, tags, `patterns/${id}.css`, 'MIT(nxeon)');
  }
  for (const f of fs.readdirSync(path.join(SRC, 'checklists'))) row('checklist', 'nxeon', f.replace('.md', ''), `${f.replace('.md', '')} checklist quality`, `checklists/${f}`, 'MIT(nxeon)');
}

async function vendored() {
  const url = 'https://raw.githubusercontent.com/anthropics/skills/41bbe19d1a1a7eaab5e7bb9050a417e5c6cffc8f/skills/frontend-design/LICENSE.txt';
  const buf = await download(url, 'frontend-design/LICENSE.txt');
  fs.writeFileSync(path.join(OUT, 'LICENSES', 'frontend-design-LICENSE.txt'), buf);
  fs.writeFileSync(path.join(OUT, 'plugin', 'skills', 'web-design', 'LICENSE.txt'), buf);
}

// ------------------------------------------------------------------ main
async function main() {
  fs.rmSync(OUT, { recursive: true, force: true });
  mkdir(path.join(OUT, 'LICENSES'));
  const t0 = Date.now();
  await icons();
  const fontMetas = fonts();
  cssLibs();
  await hyperui();
  await illustrations();
  own(fontMetas);
  await vendored();
  fs.copyFileSync(path.join(SRC, 'NOTICE'), path.join(OUT, 'LICENSES', 'NOTICE'));

  catalog.sort((a, b) => a[0].localeCompare(b[0]) || a[1].localeCompare(b[1]) || a[2].localeCompare(b[2]));
  fs.writeFileSync(path.join(OUT, 'catalog.tsv'), ['kind\tset\tid\ttags\tpath\tlicense', ...catalog.map((r) => r.join('\t'))].join('\n') + '\n');
  const version = `${manifest.version}+${new Date().toISOString().slice(0, 10)}`;
  fs.writeFileSync(path.join(OUT, 'catalog.json'), JSON.stringify({ version, counts: summary, total: catalog.length }, null, 1) + '\n');
  fs.writeFileSync(path.join(OUT, 'VERSION'), version + '\n');
  execFileSync('chmod', ['-R', 'u+rwX,go+rX,go-w', OUT]);

  if (checksumsChanged) {
    fs.writeFileSync(manifestPath, JSON.stringify(manifest, null, 1) + '\n');
    log('manifest.checksums updated (first download or --update-checksums)');
  }
  // In-place sync keeps the bind-mounted directory inode (running containers see the new tree).
  mkdir(FINAL);
  execFileSync('rsync', ['-a', '--delete', `${OUT}/`, `${FINAL}/`]);
  execFileSync('chmod', ['u+rwX,go+rX,go-w', FINAL]);
  fs.rmSync(OUT, { recursive: true, force: true });
  const du = execFileSync('du', ['-sh', FINAL], { encoding: 'utf8' }).trim();
  log(`done in ${Math.round((Date.now() - t0) / 1000)}s: ${catalog.length} catalog rows, ${du}`);
  log(JSON.stringify(summary));
}

main().catch((e) => {
  console.error('[library] FAILED:', e.message);
  process.exit(1);
});

