"use strict";
// Shared helpers for the nx-* CLIs (run as the sandbox uid inside Claude runs, or by claudebox for /v2/check).
const fs = require("fs");
const net = require("net");
const path = require("path");

const LIB = process.env.NXEON_LIBRARY_DIR || "/workspace/library";
process.env.PLAYWRIGHT_BROWSERS_PATH ||= "/opt/ms-playwright";
const TOOLS_NODE_MODULES = path.join(__dirname, "..", "node_modules");

/** Minimal argv parser: positionals + --flag / --key value (known boolean flags in `bools`). */
function parseArgs(argv, bools = []) {
  const out = { _: [] };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a.startsWith("--")) {
      const k = a.slice(2);
      if (k.includes("=")) {
        const [kk, ...v] = k.split("=");
        out[kk] = v.join("=");
      } else if (bools.includes(k) || i + 1 >= argv.length || argv[i + 1].startsWith("--")) out[k] = true;
      else out[k] = argv[++i];
    } else out._.push(a);
  }
  return out;
}

function die(msg, code = 1) {
  process.stderr.write(`${msg}\n`);
  process.exit(code);
}

function requireTool(name) {
  try {
    return require(path.join(TOOLS_NODE_MODULES, name));
  } catch {
    return require(name);
  }
}

/** true if something accepts TCP connections on 127.0.0.1:port */
function probe(port, timeoutMs = 600) {
  return new Promise((resolve) => {
    const s = net.connect({ host: "127.0.0.1", port, timeout: timeoutMs });
    const done = (ok) => {
      s.destroy();
      resolve(ok);
    };
    s.on("connect", () => done(true));
    s.on("error", () => done(false));
    s.on("timeout", () => done(false));
  });
}

/** Static root of a project dir: index.html in ., dist/, public/ or build/. */
function staticRoot(dir) {
  for (const d of [".", "dist", "public", "build", "out"]) {
    const r = path.resolve(dir, d);
    if (fs.existsSync(path.join(r, "index.html"))) return r;
  }
  return null;
}

/**
 * Resolve a CLI target → {kind:'url', url} | {kind:'dir', root, url, page} | {error}.
 * No target: the run's preview (NXEON_PREVIEW_PORT + BASE_PATH) if it is listening, else the cwd as static files.
 */
async function resolveTarget(target) {
  if (target && /^https?:\/\//i.test(target)) {
    const u = new URL(target);
    if (!["127.0.0.1", "localhost", "::1", "[::1]", "0.0.0.0"].includes(u.hostname) && process.env.NX_ALLOW_REMOTE !== "1")
      return { error: "only local URLs (127.0.0.1 previews) or project files can be checked" };
    if (u.hostname === "0.0.0.0" || u.hostname === "localhost") u.hostname = "127.0.0.1";
    return { kind: "url", url: u.toString() };
  }
  if (!target) {
    const port = Number(process.env.NXEON_PREVIEW_PORT || 0);
    if (port && (await probe(port))) return { kind: "url", url: `http://127.0.0.1:${port}${process.env.BASE_PATH || "/"}` };
    target = ".";
  }
  const abs = path.resolve(target);
  if (!fs.existsSync(abs)) return { error: `not found: ${target}` };
  let root;
  let page = "index.html";
  if (fs.statSync(abs).isDirectory()) {
    root = staticRoot(abs);
    if (!root) return { error: `no index.html in ${target} (or dist/, public/). Pass the preview URL instead, e.g. http://127.0.0.1:${process.env.NXEON_PREVIEW_PORT || "<port>"}${process.env.BASE_PATH || "/"}` };
  } else {
    root = path.dirname(abs);
    page = path.basename(abs);
  }
  return { kind: "dir", root, page, url: `http://nx.local/${encodeURI(page)}` };
}

const MIME = {
  ".html": "text/html; charset=utf-8", ".htm": "text/html; charset=utf-8", ".css": "text/css", ".js": "text/javascript", ".mjs": "text/javascript",
  ".json": "application/json", ".svg": "image/svg+xml", ".png": "image/png", ".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".gif": "image/gif",
  ".webp": "image/webp", ".avif": "image/avif", ".ico": "image/x-icon", ".woff2": "font/woff2", ".woff": "font/woff", ".ttf": "font/ttf",
  ".txt": "text/plain", ".xml": "application/xml", ".webmanifest": "application/manifest+json", ".mp4": "video/mp4", ".webm": "video/webm",
};

/** Serve http://nx.local/* from `root` (no network port needed); everything else goes to the network. */
async function routeStatic(context, root) {
  const realRoot = fs.realpathSync(root);
  await context.route("http://nx.local/**", async (route) => {
    const u = new URL(route.request().url());
    let rel = decodeURIComponent(u.pathname).replace(/^\/+/, "");
    let file = path.resolve(realRoot, rel);
    try {
      if (fs.existsSync(file) && fs.statSync(file).isDirectory()) file = path.join(file, "index.html");
      const real = fs.realpathSync(file);
      if (real !== realRoot && !real.startsWith(realRoot + path.sep)) throw new Error("outside");
      return route.fulfill({ status: 200, body: fs.readFileSync(real), contentType: MIME[path.extname(real).toLowerCase()] || "application/octet-stream" });
    } catch {
      return route.fulfill({ status: 404, body: "not found", contentType: "text/plain" });
    }
  });
}

async function launch() {
  const { chromium } = requireTool("playwright-core");
  try {
    return await chromium.launch({
      headless: true,
      args: ["--no-sandbox", "--disable-dev-shm-usage", "--disable-gpu", "--no-first-run", "--disable-extensions", "--mute-audio"],
    });
  } catch (err) {
    die(`nx: headless Chromium is not available (${String(err.message).split("\n")[0]})`, 3);
  }
}

/** Project-local scratch dir that is never committed (.nxeon/<sub>, with .nxeon/.gitignore). */
function scratchDir(sub) {
  const base = path.resolve(".nxeon");
  fs.mkdirSync(path.join(base, sub), { recursive: true });
  const gi = path.join(base, ".gitignore");
  let cur = "";
  try {
    cur = fs.readFileSync(gi, "utf8");
  } catch {
    /* none */
  }
  if (!cur.split("\n").includes(`${sub}/`)) fs.writeFileSync(gi, `${cur}${cur && !cur.endsWith("\n") ? "\n" : ""}${sub}/\n`);
  return path.join(base, sub);
}

module.exports = { LIB, parseArgs, die, requireTool, probe, staticRoot, resolveTarget, routeStatic, launch, scratchDir, MIME };

