#!/usr/bin/env node
"use strict";
// nx-shot [url|dir|file] [--mobile|--desktop] [--out DIR] [--wait MS]
// Two small viewport JPEGs (desktop 1280x800 ≈1.3k tokens, mobile 390x844 ≈0.4k tokens when read). Never full-page.
const fs = require("fs");
const path = require("path");
const { parseArgs, die, resolveTarget, routeStatic, launch, scratchDir } = require("./lib/common");

const HELP = `usage: nx-shot [url|dir|file] [--mobile | --desktop] [--out DIR] [--wait MS]
  default target: this run's preview (if listening) else ./index.html; local URLs only.
  writes JPEGs to .nxeon/shots/ (git-ignored) and prints their paths. Reading an image costs tokens:
  desktop ≈1.3k, mobile ≈0.4k. Take screenshots only when asked or in a design review.`;

(async () => {
  const a = parseArgs(process.argv.slice(2), ["mobile", "desktop", "help"]);
  if (a.help) return console.log(HELP);
  const t = await resolveTarget(a._[0]);
  if (t.error) die(`nx-shot: ${t.error}`);
  const views = [];
  if (!a.mobile) views.push({ name: "desktop", width: 1280, height: 800, mobile: false });
  if (!a.desktop) views.push({ name: "mobile", width: 390, height: 844, mobile: true });
  const out = a.out ? path.resolve(a.out) : scratchDir("shots");
  fs.mkdirSync(out, { recursive: true });
  const browser = await launch();
  const lines = [];
  let errors = 0;
  try {
    for (const v of views) {
      const ctx = await browser.newContext({
        viewport: { width: v.width, height: v.height }, deviceScaleFactor: 1, isMobile: v.mobile, hasTouch: v.mobile, reducedMotion: "reduce",
      });
      if (t.kind === "dir") await routeStatic(ctx, t.root);
      const page = await ctx.newPage();
      page.on("pageerror", () => errors++);
      page.on("console", (m) => m.type() === "error" && errors++);
      try {
        await page.goto(t.url, { waitUntil: "load", timeout: 20000 });
        await page.waitForLoadState("networkidle", { timeout: 4000 }).catch(() => {});
      } catch (err) {
        die(`nx-shot: cannot load ${t.url}: ${String(err.message).split("\n")[0]}`, 2);
      }
      await page.waitForTimeout(Number(a.wait) || 300);
      const file = path.join(out, `${v.name}.jpg`);
      await page.screenshot({ path: file, type: "jpeg", quality: 70, fullPage: false });
      const tokens = Math.ceil(v.width / 28) * Math.ceil(v.height / 28);
      lines.push(`${v.name}: ${path.relative(process.cwd(), file) || file} (${v.width}x${v.height}, ~${(tokens / 1000).toFixed(1)}k tokens to view)`);
      await ctx.close();
    }
  } finally {
    await browser.close();
  }
  console.log([`nx-shot ${t.kind === "dir" ? path.relative(process.cwd(), path.join(t.root, t.page)) || t.page : t.url}`, ...lines, `console/page errors: ${errors}`].join("\n"));
})().catch((e) => die(`nx-shot: ${e.message}`));

