// nx-check [url|dir|file] [--json] [--static] [--max N]
// Zero-LLM quality checks: axe-core (WCAG 2.2 AA), console/page errors, failed requests, broken links/images,
// horizontal overflow at 390px, meta/title/OG/favicon/lang, external CDN/font use, cheap perf hints.
// Text output ≤ ~40 lines: "SEV rule — where — fix". --json for machines ({score, issues, stats}).
const fs = require("fs");
const path = require("path");
const { parseArgs, die, resolveTarget, routeStatic, launch, requireTool, staticRoot } = require("./lib/common");

const HELP = `usage: nx-check [url|dir|file] [--json] [--static] [--max N]
  default target: this run's preview (if listening) else ./index.html. Local URLs only. Costs no tokens beyond its output.`;
const SEV_W = { high: 8, med: 3, low: 1 };
const CDN_RE = /(^|\.)(fonts\.googleapis\.com|fonts\.gstatic\.com|cdn\.jsdelivr\.net|unpkg\.com|cdnjs\.cloudflare\.com|cdn\.tailwindcss\.com|use\.fontawesome\.com|kit\.fontawesome\.com|code\.jquery\.com|stackpath\.bootstrapcdn\.com|maxcdn\.bootstrapcdn\.com|ajax\.googleapis\.com|use\.typekit\.net|esm\.sh|cdn\.skypack\.dev)$/i;
const ALLOWED_EXTERNAL = /(^|\.)(images\.unsplash\.com|plus\.unsplash\.com)$/i;

function score(issues) {
  return Math.max(0, 100 - issues.reduce((s, i) => s + (SEV_W[i.sev] || 1) * Math.min(i.count || 1, 3), 0));
}
const short = (s, n = 90) => (s && s.length > n ? `${s.slice(0, n - 1)}…` : s || "");

// ------------------------------------------------------------------ static (file) analysis
function htmlFiles(root, max = 40) {
  const out = [];
  const walk = (d, depth) => {
    if (depth > 4 || out.length >= max) return;
    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
      if (e.name.startsWith(".") || e.name === "node_modules") continue;
      const p = path.join(d, e.name);
      if (e.isDirectory()) walk(p, depth + 1);
      else if (/\.html?$/i.test(e.name)) out.push(p);
    }
  };
  walk(root, 0);
  return out;
}

function staticChecks(root, issues, opts = {}) {
  const files = htmlFiles(root);
  for (const f of files) {
    const rel = path.relative(process.cwd(), f) || path.basename(f);
    const html = fs.readFileSync(f, "utf8");
    const isDoc = /<html[\s>]/i.test(html);
    if (isDoc && !opts.browser) {
      if (!/<html[^>]*\slang=["'][^"']+/i.test(html)) issues.push({ sev: "high", rule: "html-lang", where: rel, fix: 'add <html lang="en"> (the page language)' });
      if (!/<meta[^>]+name=["']viewport/i.test(html)) issues.push({ sev: "high", rule: "meta-viewport", where: rel, fix: 'add <meta name="viewport" content="width=device-width, initial-scale=1">' });
      if (!/<title>[^<]+<\/title>/i.test(html)) issues.push({ sev: "high", rule: "title", where: rel, fix: "add a descriptive <title>" });
      if (!/<meta[^>]+name=["']description/i.test(html)) issues.push({ sev: "low", rule: "meta-description", where: rel, fix: "add <meta name=\"description\">" });
      const noAlt = (html.match(/<img\b(?![^>]*\balt=)[^>]*>/gi) || []).length;
      if (noAlt) issues.push({ sev: "high", rule: "image-alt", where: rel, count: noAlt, fix: 'add alt text to every <img> (alt="" if decorative)' });
    }
    const ext = new Set();
    for (const m of html.matchAll(/\b(?:href|src)=["'](https?:)?\/\/([^/"']+)/gi)) if (CDN_RE.test(m[2])) ext.add(m[2]);
    for (const m of html.matchAll(/@import\s+url\(["']?https?:\/\/([^/"')]+)/gi)) if (CDN_RE.test(m[1])) ext.add(m[1]);
    for (const h of ext)
      issues.push({ sev: "med", rule: /fonts\.(googleapis|gstatic)/.test(h) ? "google-fonts" : "external-cdn", where: `${rel} → ${h}`, fix: /fonts\./.test(h) ? "self-host fonts: nx-font <family> (GDPR, no runtime CDNs)" : "copy the asset into the project (no runtime CDNs)" });
    if (/[\u{1F300}-\u{1FAFF}]/u.test(html.replace(/<script[\s\S]*?<\/script>/gi, "")) && /<(?:span|i|div)[^>]*class=["'][^"']*icon/i.test(html))
      issues.push({ sev: "low", rule: "emoji-icons", where: rel, fix: "use SVG icons (nx-icon lucide <name>) instead of emoji" });
    if (/lorem ipsum/i.test(html)) issues.push({ sev: "med", rule: "placeholder-copy", where: rel, fix: "replace lorem ipsum with real copy" });
  }
  // CSS files: Google Fonts imports
  const cssDirs = [root];
  for (const d of cssDirs) {
    const walk = (dir, depth) => {
      if (depth > 4) return;
      for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
        if (e.name.startsWith(".") || e.name === "node_modules") continue;
        const p = path.join(dir, e.name);
        if (e.isDirectory()) walk(p, depth + 1);
        else if (/\.(css|scss)$/i.test(e.name)) {
          const css = fs.readFileSync(p, "utf8");
          if (/fonts\.googleapis\.com|fonts\.gstatic\.com/.test(css))
            issues.push({ sev: "med", rule: "google-fonts", where: path.relative(process.cwd(), p), fix: "self-host fonts: nx-font <family>" });
