  const axeSource = fs.readFileSync(require.resolve(path.join(path.dirname(require.resolve(path.join(__dirname, "node_modules", "axe-core", "package.json"), { paths: [__dirname] })), "axe.min.js")), "utf8");
  try {
    // ---- desktop pass: axe, console, requests, meta, links
    const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 }, reducedMotion: "reduce" });
    if (t.kind === "dir") await routeStatic(ctx, t.root);
    const page = await ctx.newPage();
    const origin = new URL(t.url).origin;
    const consoleErrors = [];
    const failed = [];
    const external = new Map();
    let bytes = 0;
    let requests = 0;
    const bigImages = [];
    page.on("console", (m) => {
      if (m.type() === "error") consoleErrors.push(short(m.text(), 120));
    });
    page.on("pageerror", (e) => consoleErrors.push(short(`uncaught: ${e.message}`, 120)));
    page.on("requestfailed", (r) => {
      if (!/favicon\.ico$/.test(r.url())) failed.push(`${short(r.url().replace(origin, ""), 80)} (${r.failure()?.errorText || "failed"})`);
    });
    page.on("response", async (r) => {
      requests++;
      const u = new URL(r.url());
      if (u.origin !== origin && /^https?:/.test(u.protocol)) external.set(u.hostname, (external.get(u.hostname) || 0) + 1);
      if (r.status() >= 400 && u.origin === origin && !/favicon\.ico$/.test(u.pathname)) failed.push(`${short(u.pathname, 80)} (HTTP ${r.status()})`);
      const len = Number(r.headers()["content-length"] || 0);
      bytes += len;
      if (r.request().resourceType() === "image" && len > 500 * 1024) bigImages.push(`${short(u.pathname, 60)} ${(len / 1024) | 0}KB`);
    });
    try {
      await page.goto(t.url, { waitUntil: "load", timeout: 25000 });
      await page.waitForLoadState("networkidle", { timeout: 5000 }).catch(() => {});
    } catch (err) {
      issues.push({ sev: "high", rule: "page-load", where: t.url, fix: `page did not load: ${short(String(err.message).split("\n")[0], 100)}` });
      return;
    }
    await page.addScriptTag({ content: axeSource });
    const axe = await page.evaluate(async () => {
      const r = await window.axe.run(document, { runOnly: { type: "tag", values: ["wcag2a", "wcag2aa", "wcag21a", "wcag21aa", "wcag22aa", "best-practice"] }, resultTypes: ["violations"] });
      return r.violations.map((v) => ({ id: v.id, impact: v.impact, help: v.help, n: v.nodes.length, target: (v.nodes[0]?.target || []).join(" ") }));
    });
    for (const v of axe) {
      const sev = v.impact === "critical" || v.impact === "serious" ? "high" : v.impact === "moderate" ? "med" : "low";
      issues.push({ sev, rule: `a11y:${v.id}`, where: short(v.target, 70), count: v.n, fix: v.help });
    }
    const meta = await page.evaluate(() => {
      const q = (s) => document.querySelector(s);
      const imgs = [...document.images];
      const vh = innerHeight;
      return {
        title: document.title.trim(),
        description: !!q('meta[name="description"]')?.content,
        viewport: !!q('meta[name="viewport"]'),
        lang: document.documentElement.lang || "",
        og: !!q('meta[property="og:title"]') && !!q('meta[property="og:image"]'),
        favicon: !!q('link[rel~="icon"]'),
        h1: document.querySelectorAll("h1").length,
        brokenImages: imgs.filter((i) => i.complete && i.naturalWidth === 0 && i.currentSrc).map((i) => i.getAttribute("src")).slice(0, 5),
        noDims: imgs.filter((i) => !i.getAttribute("width") || !i.getAttribute("height")).length,
        lazyMissing: imgs.filter((i) => i.getBoundingClientRect().top > vh * 1.5 && i.loading !== "lazy").length,
        blockingScripts: [...document.head.querySelectorAll("script[src]:not([defer]):not([async]):not([type=module])")].length,
        emojiIcons: [...document.querySelectorAll("button, a, li, span, h2, h3")].filter((e) => e.children.length === 0 && /^\p{Extended_Pictographic}/u.test(e.textContent.trim())).length,
        links: [...document.querySelectorAll("a[href]")].map((a) => a.href).filter((h) => h.startsWith(location.origin)),
      };
    });
    if (!meta.title) issues.push({ sev: "high", rule: "title", where: "<head>", fix: "add a descriptive <title>" });
    if (!meta.viewport) issues.push({ sev: "high", rule: "meta-viewport", where: "<head>", fix: 'add <meta name="viewport" content="width=device-width, initial-scale=1">' });
    if (!meta.lang) issues.push({ sev: "high", rule: "html-lang", where: "<html>", fix: 'add lang="…" to <html>' });
    if (meta.h1 !== 1) issues.push({ sev: "med", rule: "single-h1", where: `${meta.h1} h1 elements`, fix: "use exactly one <h1> per page" });
    if (!meta.description) issues.push({ sev: "low", rule: "meta-description", where: "<head>", fix: 'add <meta name="description" content="…">' });
    if (!meta.og) issues.push({ sev: "low", rule: "open-graph", where: "<head>", fix: "add og:title, og:description, og:image" });
    if (!meta.favicon) issues.push({ sev: "low", rule: "favicon", where: "<head>", fix: 'add <link rel="icon" href="favicon.svg">' });
    for (const src of meta.brokenImages) issues.push({ sev: "high", rule: "broken-image", where: short(src, 70), fix: "fix the image path (relative to the page/base path)" });
    if (meta.noDims) issues.push({ sev: "low", rule: "img-dimensions", where: `${meta.noDims} <img>`, count: meta.noDims, fix: "set width/height on images (prevents layout shift)" });
    if (meta.lazyMissing) issues.push({ sev: "low", rule: "img-lazy", where: `${meta.lazyMissing} below-the-fold <img>`, fix: 'add loading="lazy"' });
    if (meta.blockingScripts) issues.push({ sev: "low", rule: "render-blocking-js", where: `${meta.blockingScripts} <script> in <head>`, fix: "add defer or type=module" });
    if (meta.emojiIcons > 2) issues.push({ sev: "low", rule: "emoji-icons", where: `${meta.emojiIcons} elements`, fix: "use one SVG icon set (nx-icon) instead of emoji" });
    for (const e of [...new Set(consoleErrors)].slice(0, 4)) issues.push({ sev: "high", rule: "console-error", where: e, fix: "fix the script error" });
    for (const f of [...new Set(failed)].slice(0, 5)) issues.push({ sev: "high", rule: "failed-request", where: f, fix: "fix the URL/path (remember the base path)" });
    for (const [h, n] of external) {
      if (ALLOWED_EXTERNAL.test(h)) continue;
      const font = /fonts\.(googleapis|gstatic)\.com/.test(h);
      issues.push({ sev: CDN_RE.test(h) ? "med" : "low", rule: font ? "google-fonts" : "external-request", where: `${h} ×${n}`, fix: font ? "self-host fonts with nx-font (GDPR, no runtime CDNs)" : "self-host it (copy into the project)" });
    }
    for (const b of bigImages.slice(0, 3)) issues.push({ sev: "low", rule: "large-image", where: b, fix: "resize/compress (≤ 300KB, WebP/AVIF, srcset)" });
    // broken same-origin links (≤ 25 unique, HEAD via the page context so routes apply)
    const links = [...new Set(meta.links.map((h) => h.split("#")[0]))].filter((h) => h && h !== t.url).slice(0, 25);
    for (const l of links) {
      try {
        const r = await ctx.request.get(l, { timeout: 5000, maxRedirects: 3 });
        if (r.status() >= 400) issues.push({ sev: "high", rule: "broken-link", where: short(l.replace(origin, ""), 70), fix: `link returns HTTP ${r.status()}` });
      } catch {
        /* ignore */
      }
    }
    stats.requests = requests;
    stats.kb = Math.round(bytes / 1024);
    stats.console = consoleErrors.length;
    stats.axe = axe.length;
    await ctx.close();

    // ---- mobile pass: horizontal overflow at 390px
    const m = await browser.newContext({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, reducedMotion: "reduce" });
    if (t.kind === "dir") await routeStatic(m, t.root);
    const mp = await m.newPage();
    await mp.goto(t.url, { waitUntil: "load", timeout: 25000 }).catch(() => {});
    await mp.waitForTimeout(300);
    const ov = await mp.evaluate(() => {
      const vw = document.documentElement.clientWidth;
      const sw = document.scrollingElement.scrollWidth;
      if (sw <= vw + 1) return null;
      const cul = [];
      for (const el of document.body.querySelectorAll("*")) {
        const r = el.getBoundingClientRect();
        if (r.right > vw + 1 && r.width > 0 && getComputedStyle(el).position !== "fixed") {
          let p = el.parentElement;
          let nested = false;
          while (p && p !== document.body) {
            if (cul.includes(p)) nested = true;
            p = p.parentElement;
          }
          if (!nested) cul.push(el);
        }
        if (cul.length >= 3) break;
      }
      const sel = (el) => el.tagName.toLowerCase() + (el.id ? `#${el.id}` : "") + (el.classList.length ? `.${[...el.classList].slice(0, 2).join(".")}` : "");
      return { sw, vw, els: cul.map((e) => `${sel(e)} (right ${Math.round(e.getBoundingClientRect().right)}px)`) };
    });
    if (ov) issues.push({ sev: "high", rule: "mobile-overflow", where: `${ov.els.join(", ") || "page"} at 390px (scrollWidth ${ov.sw})`, fix: "constrain widths (max-width:100%, min-width:0 on flex/grid children, wrap long words)" });
    stats.mobileOverflow = !!ov;
    await m.close();
  } finally {
    await browser.close();
  }
}

(async () => {
  const a = parseArgs(process.argv.slice(2), ["json", "static", "help"]);
  if (a.help) return console.log(HELP);
  const issues = [];
  const stats = {};
  let label;
  let mode = "browser";
  const t = await resolveTarget(a._[0]);
  if (t.error) {
    // No servable page (e.g. a framework source tree without a running preview): static file scan only.
    const dir = path.resolve(a._[0] || ".");
    if (!fs.existsSync(dir) || !fs.statSync(dir).isDirectory()) die(`nx-check: ${t.error}`);
    mode = "static";
    label = path.relative(process.cwd(), dir) || ".";
    stats.files = staticChecks(dir, issues);
  } else {
    label = t.kind === "dir" ? path.relative(process.cwd(), path.join(t.root, t.page)) || t.page : t.url;
    if (t.kind === "dir") stats.files = staticChecks(t.root, issues, { browser: !a.static });
    else if (staticRoot(".")) stats.files = staticChecks(".", issues, { browser: true });
    if (a.static) mode = "static";
    else await browserChecks(t, issues, stats);
  }
  // de-duplicate (rule + where)
  const seen = new Set();
  const uniq = issues.filter((i) => {
    const k = `${i.rule}|${i.where}`;
    if (seen.has(k)) return false;
    seen.add(k);
    return true;
  });
  const order = { high: 0, med: 1, low: 2 };
  uniq.sort((x, y) => order[x.sev] - order[y.sev]);
  const sc = score(uniq);
  if (a.json) {
    process.stdout.write(JSON.stringify({ target: label, mode, score: sc, issues: uniq, stats }) + "\n");
    return;
  }
  const max = Number(a.max) || 30;
  const counts = { high: 0, med: 0, low: 0 };
  for (const i of uniq) counts[i.sev]++;
  const out = [`nx-check ${label} (${mode}) score ${sc}/100 — ${counts.high} high, ${counts.med} med, ${counts.low} low`];
  for (const i of uniq.slice(0, max)) out.push(`${i.sev.toUpperCase().padEnd(4)} ${i.rule}${i.count > 1 ? ` ×${i.count}` : ""} — ${i.where} — ${i.fix}`);
  if (uniq.length > max) out.push(`… ${uniq.length - max} more (use --max)`);
  if (stats.requests != null) out.push(`stats: ${stats.requests} requests, ~${stats.kb}KB, console errors ${stats.console}, mobile overflow ${stats.mobileOverflow ? "yes" : "no"}`);
  if (!uniq.length) out.push("PASS — no issues found");
  console.log(out.join("\n"));
})().catch((e) => die(`nx-check: ${e.message}`));

