#!/usr/bin/env node
"use strict";
// nx-new <template> [dir] [--name "Project Name"] | nx-new --list
// Copies a starter template from the asset library; never overwrites existing files.
const fs = require("fs");
const path = require("path");
const { LIB, parseArgs, die } = require("./lib/common");

const TPL = path.join(LIB, "templates");
const TEXT = /\.(html?|css|js|mjs|cjs|jsx|ts|tsx|json|md|astro|txt|svg|yml|yaml|toml|env|example|gitignore)$/i;

function list() {
  if (!fs.existsSync(TPL)) die("nx-new: template library not mounted (/workspace/library/templates)");
  const rows = [];
  for (const id of fs.readdirSync(TPL).sort()) {
    try {
      const m = JSON.parse(fs.readFileSync(path.join(TPL, id, "template.json"), "utf8"));
      rows.push(`${m.id.padEnd(14)} ${m.when}`);
    } catch {
      /* not a template */
    }
  }
  return rows;
}

function slugify(s) {
  return String(s).toLowerCase().normalize("NFKD").replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 48) || "site";
}

function main() {
  const a = parseArgs(process.argv.slice(2), ["list", "help", "force"]);
  if (a.help || (!a._.length && !a.list)) {
    console.log(`usage: nx-new <template> [dir] [--name "Name"]   (copies into dir, default ., never overwrites)\ntemplates:\n${list().join("\n")}`);
    return;
  }
  if (a.list) return console.log(list().join("\n"));
  const id = a._[0];
  if (!/^[a-z0-9-]+$/.test(id) || !fs.existsSync(path.join(TPL, id, "template.json"))) die(`nx-new: unknown template '${id}'. Available:\n${list().join("\n")}`);
  const meta = JSON.parse(fs.readFileSync(path.join(TPL, id, "template.json"), "utf8"));
  const dest = path.resolve(a._[1] || ".");
  fs.mkdirSync(dest, { recursive: true });
  const name = a.name || process.env.NXEON_PROJECT_NAME || (a._[1] ? path.basename(dest) : process.env.NXEON_PROJECT_SLUG || path.basename(dest));
  const vars = { name: String(name).replace(/-/g, a.name ? "-" : " ").replace(/^\w/, (c) => c.toUpperCase()), slug: slugify(a._[1] ? path.basename(dest) : process.env.NXEON_PROJECT_SLUG || name) };
  const created = [];
  const skipped = [];
  const walk = (src, rel) => {
    for (const e of fs.readdirSync(src, { withFileTypes: true })) {
      if (!rel && e.name === "template.json") continue;
      const s = path.join(src, e.name);
      const r = path.join(rel, e.name);
      const d = path.join(dest, r);
      if (e.isDirectory()) {
        fs.mkdirSync(d, { recursive: true });
        walk(s, r);
      } else if (e.isFile()) {
        if (fs.existsSync(d) && !a.force) {
          skipped.push(r);
          continue;
        }
        if (TEXT.test(e.name) || e.name === ".gitignore") {
          const txt = fs.readFileSync(s, "utf8").replace(/\{\{name\}\}/g, vars.name).replace(/\{\{slug\}\}/g, vars.slug);
          fs.writeFileSync(d, txt);
        } else fs.copyFileSync(s, d);
        created.push(r);
      }
    }
  };
  walk(path.join(TPL, id), "");
  const out = [`nx-new ${id} → ${path.relative(process.cwd(), dest) || "."}: ${created.length} files created${skipped.length ? `, ${skipped.length} kept (already existed: ${skipped.slice(0, 6).join(", ")}${skipped.length > 6 ? ", …" : ""})` : ""}`];
  out.push(`stack: ${(meta.stack || []).join(", ")} · conventions: CLAUDE.md`);
  if (meta.preview === "static") out.push("preview: static files are served automatically (relative URLs only).");
  else out.push("preview: the workspace runs `npm install` + the dev server with PORT/BASE_PATH automatically — don't start it yourself.");
  out.push("tokens: edit the CSS custom properties (tokens.css) or apply a preset/brand kit; keep the token names.");
  console.log(out.join("\n"));
}

try {
  main();
} catch (e) {
  die(`nx-new: ${e.message}`);
}

