#!/usr/bin/env node
"use strict";
// nx-font <family-or-id>... [--out assets/fonts] | nx-font --list [term]
// Copies self-hosted woff2 files (latin + latin-ext) from the library and appends @font-face rules to <out>/fonts.css.
const fs = require("fs");
const path = require("path");
const { LIB, parseArgs, die } = require("./lib/common");

const FONTS = path.join(LIB, "fonts");
const FALLBACK = { sans: "system-ui, sans-serif", serif: "Georgia, serif", display: "system-ui, sans-serif", mono: "ui-monospace, monospace", script: "cursive" };

function metas() {
  if (!fs.existsSync(FONTS)) die("nx-font: font library not mounted (/workspace/library/fonts)");
  return fs.readdirSync(FONTS).filter((d) => fs.existsSync(path.join(FONTS, d, "meta.json"))).map((d) => JSON.parse(fs.readFileSync(path.join(FONTS, d, "meta.json"), "utf8")));
}

function main() {
  const a = parseArgs(process.argv.slice(2), ["list", "help"]);
  const all = metas();
  if (a.help || (!a._.length && !a.list)) {
    console.log("usage: nx-font <family|id>... [--out assets/fonts]   e.g. nx-font fraunces \"DM Sans\"\n       nx-font --list [term]   (pairings: /workspace/library/fonts/pairings.json)");
    return;
  }
  if (a.list) {
    const term = (a._[0] || "").toLowerCase();
    console.log(all.filter((m) => !term || `${m.id} ${m.family} ${m.tags}`.toLowerCase().includes(term)).map((m) => `${m.id.padEnd(20)} ${m.family} — ${m.tags}`).join("\n"));
    return;
  }
  const out = path.resolve(a.out || "assets/fonts");
  fs.mkdirSync(out, { recursive: true });
  const cssFile = path.join(out, "fonts.css");
  let css = fs.existsSync(cssFile) ? fs.readFileSync(cssFile, "utf8") : "/* Self-hosted fonts (OFL-1.1, via Fontsource) — generated by nx-font */\n";
  const lines = [];
  for (const q of a._) {
    const key = q.toLowerCase().trim().replace(/\s+/g, "-");
    const m = all.find((x) => x.id === key || x.family.toLowerCase() === q.toLowerCase().trim());
    if (!m) {
      const near = all.filter((x) => x.id.includes(key.split("-")[0])).map((x) => x.id);
      die(`nx-font: '${q}' is not in the library${near.length ? ` (did you mean: ${near.join(", ")}?)` : ""}. nx-font --list shows all 42.`);
    }
    for (const f of m.files) fs.copyFileSync(path.join(FONTS, m.id, f), path.join(out, f));
    fs.copyFileSync(path.join(LIB, "LICENSES", "fonts", `${m.id}.txt`), path.join(out, `${m.id}-OFL.txt`));
    if (!css.includes(`font-family: '${m.family}'`)) {
      const face = fs.readFileSync(path.join(FONTS, m.id, "font-face.css"), "utf8").replace(/^\/\*[^\n]*\*\/\n/, "");
      css += `\n/* ${m.family} */\n${face}`;
    }
