#!/usr/bin/env node
"use strict";
// nx-icon <set> <name>... [--variant V] [--out assets/icons] [--inline] | nx-icon --search <term> [set]
// Sets: lucide (default UI), tabler (variant filled), phosphor (bold|fill|duotone), heroicons (solid|mini), simple-icons (brands).
const fs = require("fs");
const path = require("path");
const { LIB, parseArgs, die } = require("./lib/common");

const SETS = ["lucide", "tabler", "phosphor", "heroicons", "simple-icons"];

function search(term, set) {
  const cat = path.join(LIB, "catalog.tsv");
  if (!fs.existsSync(cat)) die("nx-icon: library not mounted");
  const t = term.toLowerCase();
  const rows = [];
  for (const line of fs.readFileSync(cat, "utf8").split("\n")) {
    if (!line.startsWith("icon\t")) continue;
    const [, s, id, tags] = line.split("\t");
    if (set && s !== set) continue;
    if (id === t) rows.unshift(`${s} ${id}`);
    else if (id.includes(t) || ` ${tags} `.includes(` ${t} `)) rows.push(`${s} ${id}`);
  }
  return rows;
}

function inline(svg, set) {
  let s = svg.replace(/<\?xml[^>]*>|<!--[\s\S]*?-->/g, "").replace(/\s*\n\s*/g, " ").replace(/>\s+</g, "><").trim();
  s = s.replace(/<svg\b([^>]*)>/, (m, attrs) => {
    let at = attrs.replace(/\s(width|height|class)="[^"]*"/g, "");
    if (!/aria-hidden/.test(at)) at += ' aria-hidden="true"';
    if (set === "simple-icons" && !/fill=/.test(at)) at += ' fill="currentColor"';
    return `<svg class="icon"${at}>`;
  });
  return s.replace(/<title>[^<]*<\/title>/, "");
}

function main() {
  const a = parseArgs(process.argv.slice(2), ["inline", "help"]);
  if (a.search) {
    const r = search(String(a.search), a._[0]);
    console.log(r.slice(0, 25).join("\n") || "no match");
    return;
  }
  if (a.help || a._.length < 2) {
    console.log("usage: nx-icon <set> <name>... [--variant filled|bold|fill|duotone|solid|mini] [--out assets/icons] [--inline]\n       nx-icon --search <term> [set]\nsets: " + SETS.join(", ") + " (one set per site; inline SVGs use currentColor; class=\"icon\" sizes to 1.25em)");
    return;
  }
  const [set, ...names] = a._;
  if (!SETS.includes(set)) die(`nx-icon: unknown set '${set}' (${SETS.join(", ")})`);
  if (set === "simple-icons") process.stderr.write("note: Simple Icons are brand trademarks — use a logo only to refer to that brand.\n");
  const dir = path.join(LIB, "icons", set, ...(a.variant ? [String(a.variant)] : []));
  if (!fs.existsSync(dir)) die(`nx-icon: no variant '${a.variant}' for ${set}`);
  const out = a.inline ? null : path.resolve(a.out || "assets/icons");
  if (out) fs.mkdirSync(out, { recursive: true });
  const res = [];
  for (const n of names) {
    const f = path.join(dir, `${n}.svg`);
    if (!/^[a-z0-9-]+$/.test(n) || !fs.existsSync(f)) {
      const near = search(n.split("-")[0], set).slice(0, 6).map((x) => x.split(" ")[1]);
      die(`nx-icon: ${set}/${n} not found${near.length ? ` — try: ${near.join(", ")}` : ""}`);
    }
    const svg = fs.readFileSync(f, "utf8");
    if (a.inline) res.push(inline(svg, set));
    else {
      fs.writeFileSync(path.join(out, `${n}.svg`), svg);
      res.push(path.relative(process.cwd(), path.join(out, `${n}.svg`)));
    }
  }
  console.log(res.join("\n"));
}

try {
  main();
} catch (e) {
  die(`nx-icon: ${e.message}`);
}

