#!/usr/bin/env node
"use strict";
// nx-photo "query" [--orientation landscape|portrait|squarish] [--count 1-4] [--color C]
// Unsplash photos through the workspace's proxy (the API key never enters this sandbox). Prints ready-to-paste
// <img> + credit HTML. Images are hotlinked from images.unsplash.com and the credit line is REQUIRED.
const http = require("http");
const { parseArgs, die } = require("./lib/common");

const QUOTA_MSG = "photo quota reached; use illustrations/gradients instead (rg -i illus /workspace/library/catalog.tsv)";
const esc = (s) => String(s ?? "").replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

function post(body) {
  const token = process.env.NXEON_PHOTO_TOKEN;
  if (!token) die("nx-photo: not available here (no run token). Use illustrations or CSS patterns from /workspace/library.", 2);
  const u = new URL(process.env.NXEON_PHOTO_URL || "http://127.0.0.1:3000/x/photo/search");
  const data = JSON.stringify(body);
  return new Promise((resolve, reject) => {
    const req = http.request(
      { host: u.hostname, port: u.port, path: u.pathname, method: "POST", timeout: 30000, headers: { "content-type": "application/json", "content-length": Buffer.byteLength(data), "x-nxeon-photo-token": token } },
      (res) => {
        let buf = "";
        res.setEncoding("utf8");
        res.on("data", (c) => (buf += c));
        res.on("end", () => {
          let j = null;
          try {
            j = JSON.parse(buf);
          } catch {
            /* not json */
          }
          resolve({ status: res.statusCode, body: j, raw: buf });
        });
      },
    );
    req.on("timeout", () => req.destroy(new Error("timeout")));
    req.on("error", reject);
    req.end(data);
  });
}

(async () => {
  const a = parseArgs(process.argv.slice(2), ["help", "json"]);
  const q = a._.join(" ").trim();
  if (a.help || !q) {
    console.log('usage: nx-photo "query" [--orientation landscape|portrait|squarish] [--count 1-4] [--color black_and_white|black|white|yellow|orange|red|purple|magenta|green|teal|blue]\n  prints <img> (hotlinked, keep the URL params) + the required credit line. Each photo you get counts as "used" (Unsplash download ping), so ask only for what you will place.');
    return;
  }
  const count = Math.min(4, Math.max(1, Number(a.count) || 1));
  let r;
  try {
    r = await post({ q, orientation: a.orientation || null, color: a.color || null, count });
  } catch (e) {
    die(`nx-photo: photo service unreachable (${e.message}); use illustrations/gradients instead`, 2);
  }
  if (r.status === 429 || r.status === 403 || r.body?.error?.code === "photo_quota") die(QUOTA_MSG, 2);
  if (r.status !== 200 || !r.body) die(`nx-photo: ${r.body?.error?.message || r.body?.error || `HTTP ${r.status}`}`, 2);
  const photos = r.body.photos || [];
  if (!photos.length) die(`nx-photo: no photos for "${q}" — try a simpler query (1-3 words)`, 1);
  if (a.json) return console.log(JSON.stringify(photos));
  const out = [];
  for (const p of photos) {
    const at = p.attribution;
    out.push(
      `<!-- ${esc(p.id)} · ${p.width}x${p.height} · smaller: replace w=${p.width} in the URL (keep ixid) -->`,
      `<img src="${esc(p.url)}" width="${p.width}" height="${p.height}" alt="${esc(p.alt)}" loading="lazy">`,
      `<p class="photo-credit">Photo by <a href="${esc(at.profileUrl)}">${esc(at.name)}</a> on <a href="${esc(at.unsplashUrl)}">Unsplash</a></p>`,
    );
  }
  out.push("Rules: hotlink these URLs (never download/re-host); keep the credit visible near the photo or in a credits section.");
  console.log(out.join("\n"));
})().catch((e) => die(`nx-photo: ${e.message}`));

