import path from 'node:path';

export interface Config {
  port: number;
  host: string;
  claudeboxUrl: string;
  claudeboxApiKey: string;
  /** Hostname used to reach preview ports (defaults to CLAUDEBOX_URL's hostname). */
  previewHost: string;
  whisperUrl: string;
  projectsDir: string;
  uploadsDir: string;
  dbPath: string;
  sessionSecret: string;
  adminEmail: string | null;
  adminPassword: string | null;
  adminName: string;
  trustProxy: string[];
  publicUrl: string;
  secureCookies: boolean;
  webDist: string;
  /** Paths as seen inside claudebox (attachments are passed using these). */
  claudeboxUploadsDir: string;
  claudeboxProjectsDir: string;
  logLevel: string;
  previewPortMin: number;
  previewPortMax: number;
  /** init/adopt git repos for all projects at startup (default true) */
  gitBootstrap?: boolean;
}

function env(name: string, def?: string): string {
  const v = process.env[name];
  if (v === undefined || v === '') {
    if (def === undefined) throw new Error(`Missing required env var ${name}`);
    return def;
  }
  return v;
}

export function loadConfig(overrides: Partial<Config> = {}): Config {
  const claudeboxUrl = env('CLAUDEBOX_URL', 'http://claudebox:3000').replace(/\/+$/, '');
  const publicUrl = env('PUBLIC_URL', 'http://localhost:8080').replace(/\/+$/, '');
  let sessionSecret = process.env.SESSION_SECRET || '';
  if (!sessionSecret) {
    // Dev fallback only; production must set SESSION_SECRET (sessions are invalidated on restart otherwise).
    sessionSecret = 'dev-insecure-session-secret';
    if (process.env.NODE_ENV === 'production') throw new Error('SESSION_SECRET is required in production');
  }
  const cfg: Config = {
    port: Number(env('PORT', '8080')),
    host: env('HOST', '0.0.0.0'),
    claudeboxUrl,
    claudeboxApiKey: env('CLAUDEBOX_API_KEY', ''),
    previewHost: env('PREVIEW_HOST', new URL(claudeboxUrl).hostname),
    whisperUrl: env('WHISPER_URL', 'http://whisper:9000').replace(/\/+$/, ''),
    projectsDir: path.resolve(env('PROJECTS_DIR', '/data/projects')),
    uploadsDir: path.resolve(env('UPLOADS_DIR', '/data/uploads')),
    dbPath: path.resolve(env('DB_PATH', '/data/db/nxeon.db')),
    sessionSecret,
    adminEmail: process.env.ADMIN_EMAIL || null,
    adminPassword: process.env.ADMIN_PASSWORD || null,
    adminName: env('ADMIN_NAME', 'Admin'),
    // Default: loopback + docker bridge ranges (Caddy on the host reaches the container via the bridge gateway).
    trustProxy: env('TRUST_PROXY', '127.0.0.1/8,::1/128,172.16.0.0/12')
      .split(',')
      .map((s) => s.trim())
      .filter(Boolean),
    publicUrl,
    secureCookies: publicUrl.startsWith('https://'),
    webDist: path.resolve(env('WEB_DIST', path.resolve(process.cwd(), '../web/dist'))),
    claudeboxUploadsDir: env('CLAUDEBOX_UPLOADS_DIR', '/workspace/.private/uploads'),
    claudeboxProjectsDir: env('CLAUDEBOX_PROJECTS_DIR', '/workspace/projects'),
    logLevel: env('LOG_LEVEL', 'info'),
    previewPortMin: Number(env('PREVIEW_PORT_MIN', '4100')),
    previewPortMax: Number(env('PREVIEW_PORT_MAX', '4199')),
  };
  return { ...cfg, ...overrides };
}

}, 3600_000);
reqLogTimer.unref();
trimTimer.unref();

// ---- hooks ----
app.addHook('onRequest', async (req, reply) => {
  req.clientIp = normalizeIp(req.ip);
  // /api/health stays reachable for container healthchecks even with an allowlist active.
  if (req.url !== '/api/health' && !ipRules.isAllowed(req.clientIp)) {
    reply.code(403).header('content-type', 'application/json').send({ error: { code: 'ip_blocked', message: 'Access denied from your IP address' } });
    return reply;
  }
  const token = req.cookies[SESSION_COOKIE];
  if (token) req.user = sessions.lookup(token);
  const url = req.url;
  if (url.startsWith('/api/') && !['GET', 'HEAD', 'OPTIONS'].includes(req.method)) {
    if (!req.headers['x-requested-with']) {
      reply.code(403).send({ error: { code: 'csrf', message: 'Missing X-Requested-With header' } });
      return reply;
    }
    const origin = req.headers.origin;
    if (origin && origin !== 'null' && !originAllowed(origin, req, cfg)) {
      reply.code(403).send({ error: { code: 'csrf', message: 'Cross-origin request rejected' } });
      return reply;
    }
  }
});

app.addHook('onSend', async (req, reply, payload) => {
  reply.header('X-Content-Type-Options', 'nosniff');
  reply.header('Referrer-Policy', 'same-origin');
  if (!req.url.startsWith('/preview/')) {
    if (!reply.hasHeader('Content-Security-Policy')) reply.header('Content-Security-Policy', APP_CSP);
    reply.header('X-Frame-Options', 'SAMEORIGIN');
    reply.header('Permissions-Policy', 'microphone=(self), camera=(), geolocation=(), payment=()');
    reply.header('Cross-Origin-Opener-Policy', 'same-origin');
  }
  if (req.url.startsWith('/api/') && !reply.hasHeader('Cache-Control')) reply.header('Cache-Control', 'no-store');
  return payload;
});

app.addHook('onResponse', async (req, reply) => {
  const path = req.url.split('?')[0]!;
  if (path === '/api/health' || path.startsWith('/assets/')) return;
  reqLogBuf.push([now(), req.clientIp, req.user?.id ?? null, req.method, path.slice(0, 300), reply.statusCode, Math.round(reply.elapsedTime * 10) / 10]);
  if (reqLogBuf.length > 500) flushReqLog();

