"use strict";
// POST /v2/check: zero-LLM quality gate. Runs `nx-check --json` as the project's sandbox uid (Chromium executes the
// project's own page JS, so it must never run as the server uid) against the running preview, else the static files.
const { spawn } = require("child_process");
const fs = require("fs");
const path = require("path");

const MAX_OUT = 512 * 1024;

class CheckManager {
  constructor(config) {
    this.config = { bin: "/usr/local/bin/nx-check", timeoutMs: 90_000, maxConcurrent: 2, log: () => {}, ...config };
    this.running = 0;
    this.waiters = [];
  }

  async _slot() {
    if (this.running < this.config.maxConcurrent) {
      this.running++;
      return;
    }
    await new Promise((r) => this.waiters.push(r));
    this.running++;
  }
  _release() {
    this.running--;
    const w = this.waiters.shift();
    if (w) w();
  }

  /** {projectSlug, worktree?, port?, strip?} → {score, issues, stats, target, mode} | {skipped} */
  async check({ projectSlug, worktree = null, port, strip = false, spec, previews }) {
    const c = this.config;
    const dir = worktree ? path.join(c.projectsDir, ".branches", projectSlug, worktree) : path.join(c.projectsDir, projectSlug);
    if (!fs.existsSync(dir)) return { skipped: "project dir missing" };
    if (!fs.existsSync(c.bin)) return { skipped: "nx-check is not installed" };
    const key = worktree ? `${projectSlug}--${worktree}` : projectSlug;
    let target = null;
    try {
      const st = await previews.status(key, port);
      if (st && st.running && st.port) target = `http://127.0.0.1:${st.port}${strip ? "/" : `/preview/${key}/`}`;
    } catch {
      /* no preview */
    }
    const args = ["--json", ...(target ? [target] : [])];
    const env = { PLAYWRIGHT_BROWSERS_PATH: process.env.PLAYWRIGHT_BROWSERS_PATH || "/opt/ms-playwright", NXEON_LIBRARY_DIR: c.libraryDir || "/workspace/library", LANG: "C.UTF-8" };
    await this._slot();
    try {
      return await this._exec(dir, args, env, spec);
    } finally {
      this._release();
    }
  }

  _exec(dir, args, env, spec) {
    const c = this.config;
    const sb = c.sandbox;
    let cmd = { bin: c.bin, args, env: { ...env, PATH: process.env.PATH, HOME: process.env.HOME }, envFile: null, cwd: dir };
    if (sb && sb.strict && spec) cmd = sb.command(spec, dir, c.bin, args, env);
    return new Promise((resolve, reject) => {
      const p = spawn(cmd.bin, cmd.args, { cwd: cmd.cwd, env: cmd.env, stdio: ["ignore", "pipe", "pipe"], detached: true });
      let out = "";
      let err = "";
      p.stdout.setEncoding("utf8");
      p.stderr.setEncoding("utf8");
      p.stdout.on("data", (d) => {
        if (out.length < MAX_OUT) out += d;
      });
      p.stderr.on("data", (d) => {
        err = (err + d).slice(-4000);
      });
      const kill = (sig) => {
        if (sb && sb.strict && spec) sb.kill(spec.uid, p.pid, sig);
        try {
          process.kill(-p.pid, sig);
        } catch {
          /* gone */
        }
      };
