// Brand kits: .nxeon/brand.json + generated .nxeon/brand.css in a project (docs/research/skills-and-assets.md §4.2).
// brandCss() mirrors library/scripts/brand.mjs (test: brand.test.ts compares both).
import fs from 'node:fs';
import path from 'node:path';

export const PRESET_ID_RE = /^[a-z0-9][a-z0-9-]{0,40}$/;

export interface Palette {
  bg: string; surface: string; surface2: string; text: string; muted: string; border: string;
  primary: string; primaryContrast: string; accent: string; success: string; danger: string;
}
export interface Brand {
  id?: string;
  name?: string;
  preset?: string;
  palette: Palette;
  fonts: { display: string; body: string; mono?: string };
  scale?: number;
  radius?: { sm: number; md: number; lg: number };
  density?: 'compact' | 'comfortable' | 'airy';
  motion?: 'none' | 'subtle' | 'lively';
  logo?: string | null;
  voice?: string;
  motifs?: string[];
  dont?: string[];
  mood?: string;
}
export interface FontMeta { family: string; role: string }

const ROLE_FALLBACK: Record<string, string> = {
  sans: 'system-ui, -apple-system, "Segoe UI", Roboto, sans-serif',
  serif: 'Georgia, "Times New Roman", serif',
  display: 'system-ui, sans-serif',
  mono: 'ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace',
  script: '"Segoe Print", cursive',
};
const DENSITY: Record<string, [string, string, string]> = {
  compact: ['3rem', '6vw', '5rem'], comfortable: ['4rem', '8vw', '7rem'], airy: ['5rem', '10vw', '9rem'],
};
const round = (n: number) => Math.round(n * 1000) / 1000;

export function typeStep(ratio: number, n: number): string {
  const min = Math.pow(Math.max(1.1, ratio - 0.08), n);
  const max = 1.125 * Math.pow(ratio, n);
  const slope = (max - min) / ((1240 - 360) / 16);
  const intercept = min - slope * (360 / 16);
  return `clamp(${round(min)}rem, ${round(intercept)}rem + ${round(slope * 100)}vw, ${round(max)}rem)`;
}

export function fontStack(meta: FontMeta | null): string {
  if (!meta) return ROLE_FALLBACK.sans!;
  return `"${meta.family}", ${ROLE_FALLBACK[meta.role] ?? ROLE_FALLBACK.sans}`;
}

export function brandCss(brand: Brand, fontMeta: (id: string | undefined) => FontMeta | null = () => null): string {
  const p = brand.palette;
  const f = brand.fonts || ({} as Brand['fonts']);
  const r = brand.radius || { sm: 4, md: 8, lg: 16 };
  const ratio = Number(brand.scale) || 1.25;
  const [pmin, pfluid, pmax] = DENSITY[brand.density ?? ''] ?? DENSITY.comfortable!;
  const lines = [
    `/* Generated from ${brand.id ? `preset "${brand.id}"` : 'brand.json'} — edit the JSON and regenerate, or edit values here consistently. */`,
    ':root {',
    `  --color-bg: ${p.bg};`,
    `  --color-surface: ${p.surface};`,
    `  --color-surface-2: ${p.surface2};`,
    `  --color-text: ${p.text};`,
    `  --color-muted: ${p.muted};`,
    `  --color-border: ${p.border};`,
    `  --color-primary: ${p.primary};`,
    `  --color-primary-contrast: ${p.primaryContrast};`,
    `  --color-accent: ${p.accent};`,
    `  --color-success: ${p.success};`,
    `  --color-danger: ${p.danger};`,
    `  --font-display: ${fontStack(fontMeta(f.display))};`,
    `  --font-body: ${fontStack(fontMeta(f.body))};`,
    `  --font-mono: ${fontStack(fontMeta(f.mono) || { family: 'JetBrains Mono', role: 'mono' })};`,
  ];
  for (let n = -1; n <= 5; n++) lines.push(`  --step-${n}: ${typeStep(ratio, n)};`);
  lines.push(
    `  --radius-sm: ${r.sm}px;`,
    `  --radius-md: ${r.md}px;`,
    `  --radius-lg: ${r.lg}px;`,
    `  --section-pad: clamp(${pmin}, ${pfluid}, ${pmax});`,
    `  --dur: ${brand.motion === 'none' ? '0ms' : brand.motion === 'lively' ? '260ms' : '200ms'};`,
    '}',
  );
  return lines.join('\n') + '\n';
}

export interface PresetInfo { id: string; name: string; mood: string; tags: string; swatches: string[]; fonts: string[] }

/** Presets available in the mounted library (for the New Project "Style" select). */
export function listPresets(libraryDir: string): PresetInfo[] {
  const dir = path.join(libraryDir, 'presets');
  let files: string[] = [];
  try {
    files = fs.readdirSync(dir).filter((f) => f.endsWith('.json')).sort();
  } catch {
    return [];
  }
  const out: PresetInfo[] = [];
  for (const f of files) {
    try {
      const p = JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8')) as Brand & { id: string; name: string; tags: string };
      const fm = (id: string) => readFontMeta(libraryDir, id)?.family ?? id;
      out.push({
        id: p.id, name: p.name, mood: p.mood ?? '', tags: p.tags ?? '',
        swatches: [p.palette.bg, p.palette.text, p.palette.primary, p.palette.accent],
        fonts: [fm(p.fonts.display), fm(p.fonts.body)],
      });
    } catch {
      /* skip broken preset */
    }
  }
  return out;
}

export function readFontMeta(libraryDir: string, id: string | undefined): FontMeta | null {
  if (!id || !PRESET_ID_RE.test(id)) return null;
  try {
    const m = JSON.parse(fs.readFileSync(path.join(libraryDir, 'fonts', id, 'meta.json'), 'utf8')) as FontMeta;
    return m.family ? { family: m.family, role: m.role } : null;
  } catch {
    return null;
  }
}

export function loadPreset(libraryDir: string, id: string): Brand | null {
  if (!PRESET_ID_RE.test(id)) return null;
  try {
    return JSON.parse(fs.readFileSync(path.join(libraryDir, 'presets', `${id}.json`), 'utf8')) as Brand;
  } catch {
    return null;
  }
}

/** Write .nxeon/brand.json + brand.css for a new project from a preset. Returns false if the preset is unknown. */
export function writeBrandKit(libraryDir: string, projectDir: string, presetId: string, projectName: string): boolean {
  const preset = loadPreset(libraryDir, presetId);
  if (!preset) return false;
  const { id, name: _presetName, mood, ...rest } = preset as Brand & { tags?: string; name?: string };
  delete (rest as { tags?: string }).tags;
  const brand: Brand = { name: projectName, preset: id, mood, ...rest, logo: null };
  const dir = path.join(projectDir, '.nxeon');
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, 'brand.json'), JSON.stringify(brand, null, 2) + '\n');
  fs.writeFileSync(path.join(dir, 'brand.css'), brandCss({ ...brand, id }, (fid) => readFontMeta(libraryDir, fid)));
  return true;
}

export function hasBrandKit(projectDir: string): boolean {
  return fs.existsSync(path.join(projectDir, '.nxeon', 'brand.json'));
}

