// Unsplash photo proxy (docs/research/skills-and-assets.md §3.2 option A).
// - The access key lives only in the app (env UNSPLASH_ACCESS_KEY); Claude runs reach this through claudebox with a
//   per-run token (nx-photo), the UI through the session cookie.
// - Results are cached in SQLite for 7 days; upstream calls are logged per scope (project / user) for quotas.
// - API guidelines: hotlink photo.urls (keep ixid), attribute photographer + Unsplash with utm params, and call the
//   photo's download_location when it is used.
import type { FastifyBaseLogger } from 'fastify';
import type { Config } from '../config.js';
import type { DB } from '../db.js';
import { now } from '../db.js';
import type { Settings } from '../settings.js';

const API = 'https://api.unsplash.com';
const TTL_MS = 7 * 24 * 3600_000;
const HOUR = 3600_000;
const DOWNLOAD_DEDUPE_MS = 24 * HOUR;
export const ORIENTATIONS = ['landscape', 'portrait', 'squarish'] as const;
export const COLORS = ['black_and_white', 'black', 'white', 'yellow', 'orange', 'red', 'purple', 'magenta', 'green', 'teal', 'blue'] as const;
export const QUOTA_MESSAGE = 'photo quota reached; use illustrations/gradients instead';

export class PhotoError extends Error {
  constructor(public status: number, public code: string, message: string) {
    super(message);
  }
}

interface UnsplashPhoto {
  id: string;
  width: number;
  height: number;
  color?: string | null;
  alt_description?: string | null;
  description?: string | null;
  urls: { raw: string; full: string; regular: string; small: string; thumb: string };
  links: { html: string; download_location: string };
  user: { name: string; username: string; links: { html: string } };
}

export interface Attribution { name: string; username: string; profileUrl: string; unsplashUrl: string; photoUrl: string }
export interface PhotoSummary { id: string; thumb: string; small: string; width: number; height: number; alt: string; color: string | null; attribution: Attribution }
export interface UsedPhoto { id: string; url: string; alt: string; width: number; height: number; color: string | null; attribution: Attribution }
export interface SearchOpts { q: string; orientation?: string | null; color?: string | null; page?: number; perPage?: number }

type FetchLike = (url: string, init?: { headers?: Record<string, string>; signal?: AbortSignal }) => Promise<{ status: number; headers: { get(n: string): string | null }; json(): Promise<unknown>; text(): Promise<string> }>;

export class PhotoService {
  /** Unsplash's own hourly budget, from the last X-Ratelimit-* headers. */
  private remaining: { n: number; at: number } | null = null;
  private blockedUntil = 0;
  /** hard ceiling for all upstream calls per hour (demo apps: 50/h), keeping `reserve` for the UI */
  hourlyLimit = Number(process.env.UNSPLASH_HOURLY_LIMIT || 50);
  reserve = 5;

  constructor(
    private db: DB,
    private cfg: Pick<Config, 'unsplashAccessKey' | 'unsplashAppName'>,
    private settings: Settings,
    private log: FastifyBaseLogger,
    private fetchImpl: FetchLike = fetch as unknown as FetchLike,
  ) {}

  enabled() {
