    for (const p of r.results.slice(0, count)) {
      try {
        out.push(await this.use(p.id, scope, false, o.q));
      } catch (err) {
        if (err instanceof PhotoError && err.code === 'photo_quota' && out.length) break;
        throw err;
      }
    }
    return out;
  }
}

