import type { FastifyBaseLogger, FastifyRequest } from 'fastify';
import type { Sessions } from './auth.js';
import type { Claudebox } from './claudebox.js';
import type { Config } from './config.js';
import type { DB } from './db.js';
import type { Hub } from './hub.js';
import type { RunManager } from './runs.js';
import type { Settings } from './settings.js';
import type { Watchers } from './watchers.js';
import type { IpRules } from './iprules.js';

export interface Ctx {
  cfg: Config;
  db: DB;
  log: FastifyBaseLogger;
  settings: Settings;
  sessions: Sessions;
  hub: Hub;
  runs: RunManager;
  watchers: Watchers;
  cb: Claudebox;
  ipRules: IpRules;
  audit: (req: FastifyRequest | null, action: string, target?: string | null, meta?: unknown, userId?: string | null) => void;
}
  const db = openDb(cfg.dbPath);
  const settings = new Settings(db);
  const sessions = new Sessions(db, cfg.sessionSecret);
  const hub = new Hub(db);
  const cb = new Claudebox(cfg);
  cb.sandboxFor = (slug) => {
    const row = db.prepare(`SELECT sandbox_id FROM projects WHERE slug = ?`).get(slug) as { sandbox_id: number | null } | undefined;
    return row ? projectSandbox(row) : null;
  };
  const ipRules = new IpRules(db);
  const runs = new RunManager(db, hub, cb, cfg, settings, app.log);
  const watchers = new Watchers(
    hub,
    (pid, branch) => {
      const slug = (db.prepare(`SELECT slug FROM projects WHERE id = ?`).get(pid) as { slug: string } | undefined)?.slug;
      if (!slug) return null;
      if (!branch) return path.join(cfg.projectsDir, slug);
      const b = getBranch(db, pid, branch);
      return b ? worktreePath(cfg, slug, b.dir) : null;
    },
    app.log,
  );
  watchers.onChange = (pid, branch) => runs.noteFileChange(pid, branch);
  hub.onWatchChange = (pid, branch, on) => (on ? watchers.start(pid, branch) : watchers.stop(pid, branch));

  const auditStmt = db.prepare(`INSERT INTO audit_log(user_id, ip, action, target, meta, ts) VALUES (?,?,?,?,?,?)`);
  const audit: Ctx['audit'] = (req, action, target = null, meta = null, userId) => {
    try {
      auditStmt.run(userId ?? req?.user?.id ?? null, req?.clientIp ?? null, action, target, meta == null ? null : JSON.stringify(meta), now());
    } catch (err) {
      app.log.error({ err }, 'audit insert failed');
