// Unsplash photo proxy endpoints (lib/photos.ts).
//   GET  /api/photos/search?q&orientation&color&page     (session auth)
//   POST /api/photos/:id/use                              (session auth) → hotlink URL + attribution
//   POST /api/internal/photos/claude                      (claudebox only: CLAUDEBOX_API_KEY bearer + the run's photo token)
import crypto from 'node:crypto';
import type { FastifyPluginAsync, FastifyRequest } from 'fastify';
import { z } from 'zod';
import { requireProject, requireUser } from '../auth.js';
import type { Config } from '../config.js';
import type { Ctx } from '../ctx.js';
import { HttpError } from '../lib/errors.js';
import { COLORS, ORIENTATIONS, PhotoError } from '../lib/photos.js';

const searchQuery = z.object({
  q: z.string().trim().min(1).max(100),
  orientation: z.enum(ORIENTATIONS).optional(),
  color: z.enum(COLORS).optional(),
  page: z.coerce.number().int().min(1).max(10).optional(),
});
const useBody = z.object({ projectId: z.string().max(64).optional() }).optional();
const claudeBody = z.object({
  token: z.string().min(32).max(128),
  runId: z.string().max(128),
  projectSlug: z.string().max(64).optional(),
  q: z.string().trim().min(1).max(100),
  orientation: z.enum(ORIENTATIONS).nullable().optional(),
  color: z.enum(COLORS).nullable().optional(),
  count: z.number().int().min(1).max(4).nullable().optional(),
});

/** claudebox → app calls carry `Authorization: Bearer $CLAUDEBOX_API_KEY` (constant-time compare). */
export function isInternalCall(req: FastifyRequest, cfg: Pick<Config, 'claudeboxApiKey'>): boolean {
  if (!req.url.startsWith('/api/internal/') || !cfg.claudeboxApiKey) return false;
  const got = Buffer.from(String(req.headers.authorization ?? ''));
  const want = Buffer.from(`Bearer ${cfg.claudeboxApiKey}`);
  return got.length === want.length && crypto.timingSafeEqual(got, want);
}

function photoError(err: unknown): never {
  if (err instanceof PhotoError) throw new HttpError(err.status, err.code, err.message);
  throw err;
}

export default (ctx: Ctx): FastifyPluginAsync =>
  async (app) => {
    const { photos } = ctx;

    app.get('/api/photos/search', { config: { rateLimit: { max: 60, timeWindow: '1 minute' } } }, async (req) => {
      const u = requireUser(req);
      const q = searchQuery.parse(req.query);
      try {
        return await photos.search({ q: q.q, orientation: q.orientation, color: q.color, page: q.page }, `user:${u.id}`);
      } catch (err) {
        photoError(err);
      }
    });

    app.post('/api/photos/:id/use', async (req) => {
      const u = requireUser(req);
      const body = useBody.parse(req.body ?? {});
      let scope = `user:${u.id}`;
      if (body?.projectId) scope = `project:${requireProject(ctx.db, u, body.projectId, 'editor').project.id}`;
      try {
        return await photos.use((req.params as { id: string }).id, scope, true);
      } catch (err) {
        photoError(err);
      }
    });

    app.post('/api/internal/photos/claude', async (req) => {
      if (!isInternalCall(req, ctx.cfg)) throw new HttpError(401, 'unauthorized', 'Internal endpoint');
      const body = claudeBody.parse(req.body);
      const run = ctx.runs.byPhotoToken(body.token);
      if (!run || run.id !== body.runId) throw new HttpError(401, 'photo_token', 'Invalid or expired photo token');
      const scope = run.projectId ? `project:${run.projectId}` : `user:${run.userId}`;
      try {
        const out = await photos.forClaude({ q: body.q, orientation: body.orientation, color: body.color, count: body.count ?? 1 }, scope);
        ctx.audit(null, 'photo_use', run.id, { scope, q: body.q, ids: out.map((p) => p.id) }, run.userId);
        return { photos: out };
      } catch (err) {
        photoError(err);
      }
    });
  };

