import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { cacheState, coldResumeCosts, estimateTurn, limitStop, modelFamily, priceFor, usageCost } from '../src/lib/cost.js';
import { formatSummary, relPath, SUMMARY_MAX_CHARS } from '../src/lib/summary.js';
import { DEFAULT_SETTINGS } from '../src/settings.js';
import { buildSystemPrompt } from '../src/runs.js';
import { api, createUser, login, makeEnv, type TestEnv } from './helpers.js';

const S = DEFAULT_SETTINGS;
const MIN = 60_000;

describe('efficiency: pure helpers', () => {
  it('settings defaults', () => {
    expect(S.leanMode).toBe(true);
    expect(S.coldResumeGuard).toBe(true);
    expect(S.maxTurns).toBe(30);
    expect(S.coldResumeMinutes).toBe(55);
    expect(S.coldResumeMinTokens).toBe(30_000);
    expect(S.maxBudgetUsd).toEqual({ opus: 2, sonnet: 1, haiku: 0.5 });
    expect(S.newChatHintTokens).toBe(60_000);
    expect(S.prices.sonnet).toEqual({ input: 2, output: 10, cacheWrite: 4, cacheRead: 0.2 });
    expect(S.prices.opus.output).toBe(20);
    expect(S.prices.haiku.input).toBe(1);
  });

  it('model family + usage cost (matches a measured Sonnet run)', () => {
