    expect(modelFamily('claude-haiku-4-5')).toBe('haiku');
    expect(modelFamily('sonnet')).toBe('sonnet');
    expect(modelFamily('something-else')).toBe('sonnet');
    // measured: 2 in, 95 out, 10350 read, 7334 write → $0.0324 reported by the CLI
    expect(usageCost({ inputTokens: 2, outputTokens: 95, cacheReadTokens: 10350, cacheWriteTokens: 7334 }, priceFor(S, 'sonnet'))).toBeCloseTo(0.03236, 5);
  });

  it('turn estimate: warm vs cold, ask mode has no tool round-trips', () => {
    const p = priceFor(S, 'sonnet');
    const warm = estimateTurn({ contextTokens: 80_000, warm: true, price: p, lean: true });
    const cold = estimateTurn({ contextTokens: 80_000, warm: false, price: p, lean: true });
    expect(warm.breakdown.context).toBeCloseTo(0.016, 5);
    expect(cold.breakdown.context).toBeCloseTo(0.32, 5);
    expect(cold.usd).toBeGreaterThan(warm.usd * 4);

};

export class FakeClaudebox {
  server: http.Server;
  url = '';
  projectsDir = '';
  private gitMgr: unknown = null;
  gitOps: string[] = [];
  gitBodies: Record<string, unknown>[] = [];
  sandboxSetups: Record<string, unknown>[] = [];
  /** preview starts/stops received: {projectSlug, worktree?, port} */
  previewCalls: Record<string, unknown>[] = [];
  runs = new Map<string, FakeRun>();
  aborts: string[] = [];
  bodies: Record<string, unknown>[] = [];
  previewRunning = false;

  constructor() {
    this.server = http.createServer((req, res) => void this.handle(req, res));
  }

  async start() {
    await new Promise<void>((r) => this.server.listen(0, '127.0.0.1', r));
    this.url = `http://127.0.0.1:${(this.server.address() as AddressInfo).port}`;
  }
  async stop() {
    this.server.closeAllConnections();
    await new Promise<void>((r) => this.server.close(() => r()));
  }

  private writeEvent(res: http.ServerResponse, seq: number, e: FakeEvent) {
    res.write(`id: ${seq}\nevent: ${e.event}\ndata: ${JSON.stringify(e.data)}\n\n`);
  }

  private async handle(req: http.IncomingMessage, res: http.ServerResponse) {
    if (req.headers.authorization !== 'Bearer test-key') {
      res.writeHead(401).end('{"error":"unauthorized"}');
      return;
    }
    const url = new URL(req.url!, 'http://x');
    let raw = '';
    for await (const c of req) raw += c;
    const body = raw ? (JSON.parse(raw) as Record<string, unknown>) : {};
    if (req.method === 'POST' && url.pathname === '/v2/run') {
      this.bodies.push(body);
      const prompt = String(body.prompt);
      if (prompt.includes('[fail]')) {
        res.writeHead(500, { 'content-type': 'application/json' }).end('{"error":"boom"}');
        return;
      }
      // "[touch:<file>]" simulates Claude editing a file in the run's cwd (main checkout or branch worktree)
      const touch = /\[touch:([\w.-]+)\]/.exec(prompt);
      for (const m of prompt.matchAll(/\[ntouch:([a-z0-9-]+)\/([\w.-]+)\]/g)) {
        // Nexus run: only dirs passed as addDirs are writable
        const dir = path.join(this.projectsDir, m[1]!);
        if (body.cwd && Array.isArray(body.addDirs) && body.addDirs.includes(`/workspace/projects/${m[1]}`) && fs.existsSync(dir))
          fs.writeFileSync(path.join(dir, m[2]!), `written by nexus run ${String(body.runId)}\n`);
      }
      if (touch && this.projectsDir && !body.cwd) {
        const cwd = body.worktree
          ? path.join(this.projectsDir, '.branches', String(body.projectSlug), String(body.worktree))
          : path.join(this.projectsDir, String(body.projectSlug));
        fs.writeFileSync(path.join(cwd, touch[1]!), `written by run ${String(body.runId)}\n`);
      }
      const run: FakeRun = { runId: String(body.runId), body, events: scriptFor(prompt), sent: 0, done: false, waiters: new Set(), hold: prompt.includes('[hold]') };
      this.runs.set(run.runId, run);
      res.writeHead(200, { 'content-type': 'text/event-stream' });
      const dropAt = prompt.includes('[drop]') ? 7 : -1;
      for (let i = 0; i < run.events.length; i++) {
        if (run.hold && i === 1) {
          // stay open until aborted
          run.waiters.add(res);
          return;
        }
        if (i === dropAt) {
          run.sent = i;
          res.destroy(); // simulate connection loss mid-run
          return;
        }
        this.writeEvent(res, i + 1, run.events[i]!);
        await new Promise((r) => setTimeout(r, 2));
      }
      run.done = true;
      res.end();
      return;
    }
    const m = /^\/v2\/run\/([^/]+)\/events$/.exec(url.pathname);
    if (req.method === 'GET' && m) {
      const run = this.runs.get(decodeURIComponent(m[1]!));
      if (!run) {
        res.writeHead(404).end('{"error":"not found"}');
        return;
      }
      const from = Number(url.searchParams.get('fromSeq') ?? '1');
      res.writeHead(200, { 'content-type': 'text/event-stream' });
      // replay from fromSeq (inclusive) to the end, including a duplicate of the previous event to test dedupe
      for (let i = Math.max(0, from - 2); i < run.events.length; i++) this.writeEvent(res, i + 1, run.events[i]!);
      run.done = true;
      res.end();
      return;
    }
    if (req.method === 'POST' && url.pathname === '/v2/abort') {
      this.aborts.push(String(body.runId));
      const run = this.runs.get(String(body.runId));
      if (run) {
        for (const w of run.waiters) {
          this.writeEvent(w, 2, { event: 'error', data: { message: 'aborted' } });
          this.writeEvent(w, 3, { event: 'done', data: { exitCode: null } });
          w.end();
        }
        run.waiters.clear();
      }
      res.writeHead(200, { 'content-type': 'application/json' }).end('{"ok":true}');
      return;
    }
    if (url.pathname === '/v2/sandbox/setup') {
      this.sandboxSetups.push(body);
      res.writeHead(200, { 'content-type': 'application/json' }).end(JSON.stringify({ ok: true, heavy: false }));
      return;
    }
    if (url.pathname.startsWith('/v2/git/')) {
      this.gitBodies.push(body);
      const op = url.pathname.slice('/v2/git/'.length);
      this.gitOps.push(op);
      this.gitMgr ??= new gitLib.GitManager({ projectsDir: this.projectsDir });
      try {

      try {
        const out = await gitLib.handleGit(this.gitMgr, op, body);
        res.writeHead(200, { 'content-type': 'application/json' }).end(JSON.stringify(out));
      } catch (err) {
        const e = err as { status?: number; message: string; extra?: Record<string, unknown> };
        res.writeHead(e.status ?? 500, { 'content-type': 'application/json' }).end(JSON.stringify({ error: e.message, ...(e.extra ?? {}) }));
      }
      return;
    }
    if (url.pathname === '/v2/previews') {
      res.writeHead(200, { 'content-type': 'application/json' }).end(JSON.stringify({ previews: this.previewRunning ? [{ projectSlug: 'x', running: true }] : [] }));
      return;
    }
    if (url.pathname === '/v2/preview/start') {
      this.previewCalls.push({ op: 'start', ...body });
      this.previewRunning = true;
      res.writeHead(200, { 'content-type': 'application/json' }).end(JSON.stringify({ running: true, port: body.port, pid: 42 }));
      return;
    }
    if (url.pathname === '/v2/preview/stop') {
      this.previewCalls.push({ op: 'stop', ...body });
      this.previewRunning = false;
      res.writeHead(200, { 'content-type': 'application/json' }).end('{"ok":true}');
      return;
    }
    if (url.pathname === '/v2/preview/status') {
      res.writeHead(200, { 'content-type': 'application/json' }).end(JSON.stringify({ projectSlug: url.searchParams.get('projectSlug'), running: this.previewRunning, managed: true, listening: this.previewRunning, port: Number(url.searchParams.get('port')) || null, pid: 42, kind: 'process', command: 'npm run dev', logTail: ['line1', 'line2'] }));
      return;
    }
    if (url.pathname === '/health') {
      res.writeHead(200, { 'content-type': 'application/json' }).end('{"status":"ok","version":"test"}');
      return;
    }
    res.writeHead(404).end();
  }
}

/** Tiny "dev server" upstream for preview proxy tests: echoes path + supports WebSocket. */
export async function startPreviewUpstream() {
  const server = http.createServer((req, res) => {
    if (req.url?.includes('redirect')) {
      res.writeHead(302, { location: `http://localhost:${(server.address() as AddressInfo).port}/preview/demo/next` }).end();
      return;
    }
    res.writeHead(200, { 'content-type': 'text/plain', 'x-frame-options': 'DENY' });
    res.end(`path=${req.url} host=${req.headers.host} cookie=${req.headers.cookie ?? ''}`);
  });
  const wss = new WebSocketServer({ server });
  wss.on('connection', (ws, req) => {
    ws.on('message', (m) => ws.send(`echo:${m.toString()}:${req.url}`));
  });
  await new Promise<void>((r) => server.listen(0, '127.0.0.1', r));
  const port = (server.address() as AddressInfo).port;
  return {
    port,
    close: async () => {
      wss.close();
      server.closeAllConnections();
      await new Promise<void>((r) => server.close(() => r()));
    },
  };
}

