// Quality kit: brand kits/presets, zero-token quality gate → `fix` chip, design review, photo proxy.
import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { brandCss, listPresets, writeBrandKit, type Brand } from '../src/lib/brand.js';
import { PhotoError, PhotoService } from '../src/lib/photos.js';
import { openDb } from '../src/db.js';
import { Settings } from '../src/settings.js';
import { BRAND_KIT_LINE, buildSystemPrompt, DESIGN_REVIEW_LINE, QUALITY_KIT_LINES, qualitySuggestion } from '../src/runs.js';
import { api, createUser, login, makeEnv, waitFor, type TestEnv } from './helpers.js';

const LIBRARY_SRC = path.resolve(__dirname, '..', '..', 'library');

describe('brand kits + presets', () => {
  it('server brandCss() matches library/scripts/brand.mjs for every preset', async () => {
    const mod = (await import(pathToFileURL(path.join(LIBRARY_SRC, 'scripts', 'brand.mjs')).href)) as { brandCss: (b: unknown, f: unknown) => string; contrast: (a: string, b: string) => number };
    const files = fs.readdirSync(path.join(LIBRARY_SRC, 'presets')).filter((f) => f.endsWith('.json'));
    expect(files.length).toBe(12);
    const fm = (id: string | undefined) => (id ? { family: id.toUpperCase(), role: id.includes('mono') ? 'mono' : 'sans' } : null);
    for (const f of files) {
      const p = JSON.parse(fs.readFileSync(path.join(LIBRARY_SRC, 'presets', f), 'utf8')) as Brand;
      expect(brandCss(p, fm)).toBe(mod.brandCss(p, fm));
      // accessible palettes: body text and buttons pass WCAG AA
      expect(mod.contrast(p.palette.text, p.palette.bg)).toBeGreaterThanOrEqual(7);
      expect(mod.contrast(p.palette.primaryContrast, p.palette.primary)).toBeGreaterThanOrEqual(4.5);
      expect(mod.contrast(p.palette.muted, p.palette.bg)).toBeGreaterThanOrEqual(4.5);
    }
  });

  it('writeBrandKit writes brand.json + brand.css; unknown presets are refused', () => {
    const dir = fs.mkdtempSync(path.join(require('node:os').tmpdir(), 'nx-brand-'));
    expect(writeBrandKit(LIBRARY_SRC, dir, 'warm-hearth', 'Bean There')).toBe(true);
    const j = JSON.parse(fs.readFileSync(path.join(dir, '.nxeon', 'brand.json'), 'utf8'));
    expect(j).toMatchObject({ name: 'Bean There', preset: 'warm-hearth', fonts: { display: 'young-serif', body: 'figtree' } });
    expect(j.palette.primary).toBe('#3f5d2a');
    const css = fs.readFileSync(path.join(dir, '.nxeon', 'brand.css'), 'utf8');
    expect(css).toContain('--color-primary: #3f5d2a;');
    expect(css).toContain('--step-5: clamp(');
    expect(writeBrandKit(LIBRARY_SRC, dir, 'no-such-style', 'x')).toBe(false);
    expect(writeBrandKit(LIBRARY_SRC, dir, '../etc', 'x')).toBe(false);
    fs.rmSync(dir, { recursive: true, force: true });
  });

  it('listPresets exposes swatches + fonts for the New Project select', () => {
    const ps = listPresets(LIBRARY_SRC);
    expect(ps.map((p) => p.id)).toContain('luxe-noir');
    expect(ps[0]!.swatches).toHaveLength(4);
    expect(listPresets('/nonexistent')).toEqual([]);
  });

  it('system prompt: kit lines only when enabled, brand line only when a kit exists, design review line', () => {
    const dir = fs.mkdtempSync(path.join(require('node:os').tmpdir(), 'nx-sp-'));
    fs.mkdirSync(path.join(dir, 'site'));
    const p = { name: 'Site', slug: 'site', description: '', preview_port: 4100, preview_strip: 0 } as never;
    const cfg = { publicUrl: 'https://x', claudeboxProjectsDir: '/workspace/projects', projectsDir: dir } as never;
    const off = buildSystemPrompt(p, cfg, [], null, true);
    expect(off).not.toContain('/workspace/library');
    const on = buildSystemPrompt(p, cfg, [], null, true, { qualityKit: true });
    for (const l of QUALITY_KIT_LINES) expect(on).toContain(l);
    expect(on).not.toContain(BRAND_KIT_LINE);
    expect(on).not.toContain(DESIGN_REVIEW_LINE);
    writeBrandKit(LIBRARY_SRC, path.join(dir, 'site'), 'studio-mono', 'Site');
    const withKit = buildSystemPrompt(p, cfg, [], null, true, { qualityKit: true, designReview: 'auto' });
    expect(withKit).toContain(BRAND_KIT_LINE);
    expect(withKit).toContain(DESIGN_REVIEW_LINE);
    // budget: the whole kit adds < 900 chars (~220 tokens) to the system prompt
    expect(withKit.length - off.length).toBeLessThan(900);
    fs.rmSync(dir, { recursive: true, force: true });
  });
});

describe('quality gate suggestion', () => {
  it('builds one fix chip from high/med issues only', () => {
    expect(qualitySuggestion({ score: 98, issues: [{ sev: 'low', rule: 'open-graph', where: '<head>', fix: 'add og' }] })).toBeNull();
    expect(qualitySuggestion({ skipped: 'nothing' })).toBeNull();
    const a11y = qualitySuggestion({
      score: 70,
      issues: [
        { sev: 'high', rule: 'a11y:color-contrast', where: '.hero p', fix: 'Elements must meet minimum color contrast', count: 2 },
        { sev: 'med', rule: 'a11y:region', where: 'body', fix: 'content in landmarks' },
        { sev: 'low', rule: 'favicon', where: '<head>', fix: 'add favicon' },
      ],
    })!;
    expect(a11y.kind).toBe('fix');
    expect(a11y.label).toBe('Fix 3 accessibility issues');
    expect(a11y.prompt).toContain('score 70/100');
    expect(a11y.prompt).toContain('- HIGH a11y:color-contrast ×2 — .hero p — Elements must meet minimum color contrast');
    expect(a11y.prompt).not.toContain('favicon');
    const mixed = qualitySuggestion({ issues: [{ sev: 'high', rule: 'mobile-overflow', where: 'table', fix: 'wrap' }] })!;
    expect(mixed.label).toBe('Fix 1 quality issue');
  });
});

describe('quality kit end-to-end (fake claudebox)', () => {
  let env: TestEnv;
  let alice: string;
  beforeAll(async () => {
    env = await makeEnv({ libraryDir: LIBRARY_SRC });
    await createUser(env, 'q@test.local', 'q-pass-123');
    alice = await login(env, 'q@test.local', 'q-pass-123');
  });
  afterAll(async () => env.close());

  const runStatus = (id: string) => (env.built.ctx.db.prepare('SELECT status FROM runs WHERE id = ?').get(id) as { status: string } | undefined)?.status;
  async function prompt(projectId: string, text: string, mode = 'auto') {
    const conv = (await api(env, alice, 'POST', `/api/projects/${projectId}/conversations`, {})).json;
    const r = await api(env, alice, 'POST', `/api/conversations/${conv.id}/prompt`, { text, attachments: [], model: 'sonnet', mode });
    expect(r.status).toBe(200);
    await waitFor(() => ['done', 'error', 'aborted'].includes(runStatus(r.json.runId) ?? ''));
    return r.json as { runId: string; assistantMessageId: string };
  }

  it('GET /api/presets + create with a style writes the brand kit and the prompt line', async () => {
    const presets = (await api(env, alice, 'GET', '/api/presets')).json.presets;
    expect(presets).toHaveLength(12);
    expect((await api(env, alice, 'POST', '/api/projects', { name: 'Bad', style: '../x' })).status).toBe(400);
    const p = (await api(env, alice, 'POST', '/api/projects', { name: 'Bean There', style: 'warm-hearth' })).json;
    expect(p.qualityChecks).toBe(true);
    expect(p.designReview).toBe('off');
    const brand = JSON.parse(fs.readFileSync(path.join(env.cfg.projectsDir, p.slug, '.nxeon', 'brand.json'), 'utf8'));
    expect(brand.preset).toBe('warm-hearth');
    await prompt(p.id, 'hello');
    const body = env.fake.bodies.at(-1)!;
    expect(body.library).toBe(true);
    expect(String(body.appendSystemPrompt)).toContain(BRAND_KIT_LINE);
    expect(String(body.appendSystemPrompt)).toContain('/workspace/library');
    // design-critic is not passed while design review is off
    expect(Object.keys((body.agents ?? {}) as object)).not.toContain('design-critic');
  });

  it('a run that changed web files gets a zero-token check → fix chip (and none when checks are off)', async () => {
    const p = (await api(env, alice, 'POST', '/api/projects', { name: 'Checked' })).json;
    env.fake.checkResult = { score: 76, issues: [
      { sev: 'high', rule: 'a11y:image-alt', where: 'img.hero', fix: 'Images must have alternate text', count: 2 },
      { sev: 'med', rule: 'a11y:heading-order', where: 'h4', fix: 'Heading levels should only increase by one' },
    ] };
    const before = env.fake.checkCalls.length;
    const plain = await prompt(p.id, 'just a question');
    expect(env.fake.checkCalls.length).toBe(before); // no web change → no check
    void plain;
    const r = await prompt(p.id, 'build it [web]');
    await waitFor(() => env.fake.checkCalls.length > before);
    expect(env.fake.checkCalls.at(-1)).toMatchObject({ projectSlug: p.slug, port: p.previewPort });
    const sugg = await waitFor(() => {
      const row = env.built.ctx.db.prepare('SELECT suggestions FROM messages WHERE id = ?').get(r.assistantMessageId) as { suggestions: string | null };
      const items = row?.suggestions ? JSON.parse(row.suggestions) : [];
      return items.some((x: { kind: string }) => x.kind === 'fix') ? items : null;
    });
    expect(sugg[0]).toMatchObject({ kind: 'fix', label: 'Fix 3 accessibility issues' });
    expect(sugg[0].prompt).toContain('a11y:image-alt ×2 — img.hero');
