describe('PhotoService (fake Unsplash)', () => {
  const photo = (id: string) => ({
    id, width: 4000, height: 3000, color: '#c08040', alt_description: `a ${id} photo`,
    urls: { raw: `https://images.unsplash.com/photo-${id}?ixid=XYZ&ixlib=rb-4.1.0`, full: '', regular: '', small: 's', thumb: 't' },
    links: { html: `https://unsplash.com/photos/${id}`, download_location: `https://api.unsplash.com/photos/${id}/download?ixid=XYZ` },
    user: { name: 'Jane Doe', username: 'jane', links: { html: 'https://unsplash.com/@jane' } },
  });
  function setup(perHour = 10) {
    const dir = fs.mkdtempSync(path.join(require('node:os').tmpdir(), 'nx-ph-'));
    const db = openDb(path.join(dir, 'x.db'));
    const settings = new Settings(db);
    settings.update({ photoCallsPerHour: perHour });
    const calls: string[] = [];
    let status = 200;
    const fetchImpl = async (url: string, init?: { headers?: Record<string, string> }) => {
      calls.push(url);
      expect(init?.headers?.authorization).toBe('Client-ID KEY');
      const body = url.includes('/search/photos') ? { total: 2, results: [photo('aaa'), photo('bbb')] } : url.includes('/download') ? { url: 'x' } : photo('ccc');
      return { status, headers: { get: (n: string) => (n === 'x-ratelimit-remaining' ? '40' : null) }, json: async () => body, text: async () => (status === 403 ? 'Rate Limit Exceeded' : '') };
    };
    const svc = new PhotoService(db, { unsplashAccessKey: 'KEY', unsplashAppName: 'nxeon_workspace' }, settings, console as never, fetchImpl as never);
    return { svc, calls, db, dir, setStatus: (s: number) => (status = s) };
  }

  it('caches searches for 7 days and reuses cached photos for use()', async () => {
    const { svc, calls } = setup();
    const a = await svc.search({ q: 'Coffee  Shop' }, 'user:u1');
    expect(a.cached).toBe(false);
    expect(a.photos[0]!.attribution.profileUrl).toBe('https://unsplash.com/@jane?utm_source=nxeon_workspace&utm_medium=referral');
    const b = await svc.search({ q: 'coffee shop' }, 'user:u2');
    expect(b.cached).toBe(true);
    expect(calls.filter((u) => u.includes('/search/')).length).toBe(1);
    const used = await svc.use('aaa', 'project:p1');
    // hotlink keeps ixid/ixlib, adds sizing only; attribution with utm params
    expect(used.url).toBe('https://images.unsplash.com/photo-aaa?ixid=XYZ&ixlib=rb-4.1.0&w=1600&q=80&auto=format&fit=max');
    expect(used).toMatchObject({ width: 1600, height: 1200, alt: 'a aaa photo' });
    expect(used.attribution).toEqual({
      name: 'Jane Doe', username: 'jane',
      profileUrl: 'https://unsplash.com/@jane?utm_source=nxeon_workspace&utm_medium=referral',
      unsplashUrl: 'https://unsplash.com/?utm_source=nxeon_workspace&utm_medium=referral',
      photoUrl: 'https://unsplash.com/photos/aaa?utm_source=nxeon_workspace&utm_medium=referral',
    });
    // the download ping (API guideline) fired once; a second use in the same scope is deduped
    expect(calls.filter((u) => u.includes('/download')).length).toBe(1);
    await svc.use('aaa', 'project:p1');
    expect(calls.filter((u) => u.includes('/download')).length).toBe(1);
    expect(calls.filter((u) => /\/photos\/aaa$/.test(u)).length).toBe(0); // no lookup: cached from the search
  });

  it('per-scope quota for Claude runs and graceful rate-limit handling', async () => {
    const { svc, setStatus } = setup(2);
    const got = await svc.forClaude({ q: 'beach', count: 1 }, 'project:p1'); // search + download = 2 upstream calls
    expect(got).toHaveLength(1);
    await expect(svc.forClaude({ q: 'mountains', count: 1 }, 'project:p1')).rejects.toMatchObject({ status: 429, code: 'photo_quota' });
    // another project still has budget; cached queries cost nothing
    expect((await svc.forClaude({ q: 'forest', count: 1 }, 'project:p2'))).toHaveLength(1);
