    setStatus(403);
    await expect(svc.search({ q: 'desert' }, 'user:u1')).rejects.toMatchObject({ code: 'photo_quota', message: 'photo quota reached; use illustrations/gradients instead' });
    setStatus(200);
    await expect(svc.search({ q: 'snow' }, 'user:u1')).rejects.toBeInstanceOf(PhotoError);
  });
});

