"use strict";
// nx-* CLIs that need no browser: nx-new (template copy), nx-font, nx-icon; plus the built library's catalog.
const assert = require("node:assert/strict");
const test = require("node:test");
const fs = require("fs");
const os = require("os");
const path = require("path");
const { execFileSync, spawnSync } = require("child_process");

const TOOLS = path.join(__dirname, "..", "tools");
const REPO_LIB = path.join(__dirname, "..", "..", "library");
const BUILT_LIB = path.join(__dirname, "..", "..", "data", "library");
const TMP = fs.mkdtempSync(path.join(os.tmpdir(), "nx-tools-"));
const LIB = path.join(TMP, "library");

// a tiny library: real templates + one fake font + two icons + catalog
fs.cpSync(path.join(REPO_LIB, "templates"), path.join(LIB, "templates"), { recursive: true });
fs.mkdirSync(path.join(LIB, "fonts", "demo-serif"), { recursive: true });
fs.writeFileSync(path.join(LIB, "fonts", "demo-serif", "demo-serif-latin-400-normal.woff2"), "woff2");
fs.writeFileSync(path.join(LIB, "fonts", "demo-serif", "font-face.css"), "/* header */\n@font-face {\n  font-family: 'Demo Serif';\n  src: url(./demo-serif-latin-400-normal.woff2) format('woff2');\n}\n");
fs.writeFileSync(path.join(LIB, "fonts", "demo-serif", "meta.json"), JSON.stringify({ id: "demo-serif", family: "Demo Serif", role: "serif", tags: "serif", variable: false, weights: ["400"], styles: ["normal"], files: ["demo-serif-latin-400-normal.woff2"] }));
fs.mkdirSync(path.join(LIB, "LICENSES", "fonts"), { recursive: true });
fs.writeFileSync(path.join(LIB, "LICENSES", "fonts", "demo-serif.txt"), "OFL");
fs.mkdirSync(path.join(LIB, "icons", "lucide"), { recursive: true });
fs.writeFileSync(path.join(LIB, "icons", "lucide", "coffee.svg"), '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" stroke="currentColor"><path d="M1 1"/></svg>\n');
fs.writeFileSync(path.join(LIB, "catalog.tsv"), "kind\tset\tid\ttags\tpath\tlicense\nicon\tlucide\tcoffee\tcoffee cup drink\ticons/lucide/coffee.svg\tISC\n");

function run(tool, args, cwd, env = {}) {
  return spawnSync(process.execPath, [path.join(TOOLS, tool), ...args], { cwd, encoding: "utf8", env: { ...process.env, NXEON_LIBRARY_DIR: LIB, ...env } });
}

test("nx-new: lists templates, copies one with placeholders, never overwrites", () => {
  const list = run("nx-new", ["--list"], TMP);
  assert.equal(list.status, 0);
  for (const id of ["static-site", "vite-react", "vite-vanilla", "astro-static", "express-api", "nextjs"]) assert.match(list.stdout, new RegExp(`^${id}\\s`, "m"));
  const dir = path.join(TMP, "proj");
  fs.mkdirSync(dir);
  fs.writeFileSync(path.join(dir, "README.md"), "mine\n");
  const r = run("nx-new", ["static-site"], dir, { NXEON_PROJECT_SLUG: "bean-there" });
  assert.equal(r.status, 0, r.stderr);
  assert.match(r.stdout, /files created, 1 kept/);
  assert.equal(fs.readFileSync(path.join(dir, "README.md"), "utf8"), "mine\n");
  assert.ok(!fs.existsSync(path.join(dir, "template.json")));
  const html = fs.readFileSync(path.join(dir, "index.html"), "utf8");
  assert.ok(html.includes("Bean There") && !html.includes("{{name}}"));
  assert.ok(fs.existsSync(path.join(dir, "assets", "css", "tokens.css")));
  // subdirectory target + explicit name
  const r2 = run("nx-new", ["express-api", "api", "--name", "Bean API"], dir);
  assert.equal(r2.status, 0, r2.stderr);
  assert.ok(fs.existsSync(path.join(dir, "api", "server.js")));
  assert.equal(run("nx-new", ["nope"], dir).status, 1);
  assert.equal(run("nx-new", ["../../etc"], dir).status, 1);
});

test("templates: base path ready (relative URLs on the static site; BASE_PATH in framework configs)", () => {
  const T = path.join(REPO_LIB, "templates");
  const idx = fs.readFileSync(path.join(T, "static-site", "index.html"), "utf8");
  for (const m of idx.matchAll(/\b(?:href|src)="([^"]+)"/g)) assert.ok(!m[1].startsWith("/") || m[1].startsWith("//") === false && !m[1].startsWith("/"), `absolute URL in static-site: ${m[1]}`);
  assert.match(fs.readFileSync(path.join(T, "vite-vanilla", "vite.config.js"), "utf8"), /BASE_PATH/);
  assert.match(fs.readFileSync(path.join(T, "vite-react", "vite.config.ts"), "utf8"), /BASE_PATH/);
  assert.match(fs.readFileSync(path.join(T, "astro-static", "astro.config.mjs"), "utf8"), /BASE_PATH/);
  assert.match(fs.readFileSync(path.join(T, "nextjs", "next.config.mjs"), "utf8"), /BASE_PATH/);
  assert.match(fs.readFileSync(path.join(T, "express-api", "server.js"), "utf8"), /BASE_PATH/);
  for (const id of fs.readdirSync(T)) {
    const meta = JSON.parse(fs.readFileSync(path.join(T, id, "template.json"), "utf8"));
    assert.equal(meta.id, id);
    assert.ok(fs.existsSync(path.join(T, id, "CLAUDE.md")), `${id}: CLAUDE.md`);
    assert.ok(!fs.existsSync(path.join(T, id, "node_modules")), `${id}: node_modules`);
  }
});

test("nx-font copies woff2 + licence and appends @font-face once", () => {
  const dir = path.join(TMP, "fontproj");
  fs.mkdirSync(dir);
  const r = run("nx-font", ["Demo Serif"], dir);
  assert.equal(r.status, 0, r.stderr);
  assert.match(r.stdout, /font-family: 'Demo Serif', Georgia, serif/);
  run("nx-font", ["demo-serif"], dir);
  const css = fs.readFileSync(path.join(dir, "assets", "fonts", "fonts.css"), "utf8");
  assert.equal(css.match(/@font-face/g).length, 1);
  assert.match(css, /url\(\.\/demo-serif-latin-400-normal\.woff2\)/);
  assert.ok(fs.existsSync(path.join(dir, "assets", "fonts", "demo-serif-OFL.txt")));
  const bad = run("nx-font", ["Comic Sans"], dir);
  assert.equal(bad.status, 1);
  assert.match(bad.stderr, /not in the library/);
});

test("nx-icon: inline SVG with currentColor/aria-hidden, file copy, search, unknown names", () => {
  const dir = path.join(TMP, "iconproj");
  fs.mkdirSync(dir);
  const inl = run("nx-icon", ["lucide", "coffee", "--inline"], dir);
  assert.equal(inl.status, 0, inl.stderr);
  assert.match(inl.stdout, /^<svg class="icon" xmlns="http:\/\/www.w3.org\/2000\/svg" viewBox="0 0 24 24" stroke="currentColor" aria-hidden="true">/);
  assert.ok(!/width=/.test(inl.stdout));
  assert.equal(run("nx-icon", ["lucide", "coffee"], dir).status, 0);
  assert.ok(fs.existsSync(path.join(dir, "assets", "icons", "coffee.svg")));
  assert.match(run("nx-icon", ["--search", "cup"], dir).stdout, /lucide coffee/);
  assert.equal(run("nx-icon", ["lucide", "../x"], dir).status, 1);
  assert.equal(run("nx-icon", ["fontawesome", "x"], dir).status, 1);
});

test("nx-photo: clear message without a run token (sandbox never has the key)", () => {
  const r = run("nx-photo", ["coffee"], TMP, { NXEON_PHOTO_TOKEN: "" });
  assert.equal(r.status, 2);
  assert.match(r.stderr, /not available here/);
});

test("built library catalog (data/library): well-formed rows, existing paths, allowed licences", { skip: !fs.existsSync(path.join(BUILT_LIB, "catalog.tsv")) }, () => {
  const allowed = new Set(["MIT", "ISC", "Apache-2.0", "OFL-1.1", "CC0-1.0", "0BSD", "MIT(nxeon)"]);
  const lines = fs.readFileSync(path.join(BUILT_LIB, "catalog.tsv"), "utf8").trim().split("\n");
  assert.equal(lines[0], "kind\tset\tid\ttags\tpath\tlicense");
  const kinds = new Map();
  for (const l of lines.slice(1)) {
    const c = l.split("\t");
    assert.equal(c.length, 6, l);
    assert.ok(allowed.has(c[5]), `licence ${c[5]}`);
    kinds.set(c[0], (kinds.get(c[0]) || 0) + 1);
  }
  for (const k of ["icon", "font", "pairing", "illus", "preset", "section", "template", "pattern", "ui", "css", "checklist"]) assert.ok(kinds.get(k) > 0, k);
  assert.equal(kinds.get("preset"), 12);
  assert.equal(kinds.get("template"), 6);
  assert.ok(kinds.get("font") >= 40);
  assert.ok(kinds.get("section") >= 30);
  // spot-check paths
  for (const l of lines.slice(1).filter((_, i) => i % 97 === 0)) assert.ok(fs.existsSync(path.join(BUILT_LIB, l.split("\t")[4])), l);
  assert.ok(fs.existsSync(path.join(BUILT_LIB, "plugin", ".claude-plugin", "plugin.json")));
  assert.ok(fs.existsSync(path.join(BUILT_LIB, "LICENSES", "NOTICE")));
});

test.after(() => fs.rmSync(TMP, { recursive: true, force: true }));
void execFileSync;

