import { Fragment, useEffect, useState } from 'react';
import { ArrowDown, ArrowUp, ChevronRight, Eye, EyeOff, KeyRound, Leaf, Plus, Save, X } from 'lucide-react';
import { Badge, Button, IconButton, Input, Select, Skeleton, Switch, toast } from '@/components/ui';
import { fmtNum, timeAgo } from '@/lib/format';
import type { ModelInfo } from '@/lib/types';
import { getSettings, saveSettings, type EfficiencySettings, type Family } from './api';
import { Card, ErrorNote, PageHeader, useQuery } from './common';

export default function SettingsPage() {
  const s = useQuery(getSettings, []);
  const [models, setModels] = useState<ModelInfo[]>([]);
  const [def, setDef] = useState('');
  const [cap, setCap] = useState('');
  const [ac, setAc] = useState('');
  const [busy, setBusy] = useState(false);
  const [token, setToken] = useState('');
  const [show, setShow] = useState(false);
  const [tokBusy, setTokBusy] = useState(false);
  const [eff, setEff] = useState<EfficiencySettings | null>(null);
  const [showPrices, setShowPrices] = useState(false);
  const effOf = (d: EfficiencySettings): EfficiencySettings => ({
    leanMode: d.leanMode, coldResumeGuard: d.coldResumeGuard, coldResumeMinutes: d.coldResumeMinutes, coldResumeMinTokens: d.coldResumeMinTokens,
    maxBudgetUsd: { ...d.maxBudgetUsd }, maxTurns: d.maxTurns, newChatHintTokens: d.newChatHintTokens,
    prices: JSON.parse(JSON.stringify(d.prices)),
  });

  useEffect(() => {
    if (!s.data) return;
    setModels(s.data.models.map((m) => ({ ...m })));
    setDef(s.data.defaultModel);
    setCap(s.data.globalDailyTokenCap ? String(s.data.globalDailyTokenCap) : '');
    setAc(String(s.data.autoCompactTokens ?? 0));
    setEff(effOf(s.data));
  }, [s.data]);

  const capNum = cap.trim() ? Number(cap.replace(/[_,\s]/g, '')) : null;
  const acNum = ac.trim() ? Number(ac.replace(/[_,\s]/g, '').replace(/k$/i, '000')) : 0;
  const acValid = Number.isInteger(acNum) && (acNum === 0 || (acNum >= 10_000 && acNum <= 987_000));
  const modelsValid = models.length > 0 && models.every((m) => m.id.trim() && m.label.trim()) && new Set(models.map((m) => m.id.trim())).size === models.length;
  const effDirty = !!s.data && !!eff && JSON.stringify(eff) !== JSON.stringify(effOf(s.data));

function EfficiencyCard({ eff, set, showPrices, setShowPrices }: {
  eff: EfficiencySettings; set: (e: EfficiencySettings) => void; showPrices: boolean; setShowPrices: (v: boolean) => void;
}) {
  const patch = (p: Partial<EfficiencySettings>) => set({ ...eff, ...p });
  return (
