cd /tmp/claude-1000/-home-claude/a5a0e1b8-f10f-4557-a424-37ef9c870766/scratchpad/qa/quality && ./nx.sh login >/dev/null && SID=$(awk '$6=="nx_sid"{print $7}' cookies.txt) && cat > ui.js <<'EOF'
const { chromium } = require("/opt/nx-tools/node_modules/playwright-core");
(async () => {
  const b = await chromium.launch({ args: ["--no-sandbox", "--host-resolver-rules=MAP workspace.trynxeon.com 127.0.0.1"] });
  const ctx = await b.newContext({ viewport: { width: 1280, height: 860 } });
  await ctx.addCookies([{ name: "nx_sid", value: process.env.SID, domain: "workspace.trynxeon.com", path: "/", secure: true, httpOnly: true }]);
  const p = await ctx.newPage();
  await p.goto("https://workspace.trynxeon.com/p/goonies-fanpage", { waitUntil: "networkidle" });
  await p.click('[data-testid="crumb-project"]');
  await p.waitForSelector('[data-testid="quality-settings"]');
  await p.screenshot({ path: "/q/ui-crumb-quality.jpg", type: "jpeg", quality: 70, clip: { x: 0, y: 0, width: 640, height: 520 } });
  await p.keyboard.press("Escape");
  await p.goto("https://workspace.trynxeon.com/", { waitUntil: "networkidle" });
  await p.evaluate(() => { const el = [...document.querySelectorAll("button")].find((b) => /new project/i.test(b.textContent || "")); el && el.click(); });
  await p.waitForTimeout(800);
  const sel = await p.$('select');
  if (sel) { await sel.selectOption("warm-hearth"); }
  await p.waitForTimeout(300);
  await p.screenshot({ path: "/q/ui-new-project-style.jpg", type: "jpeg", quality: 70 });
  await b.close();
})().catch((e) => { console.error(e.message); process.exit(1); });
EOF
